static void mir_emit_random_unique_init(
    FILE *out, const struct MirRandomUniqueInit *plan)
{
    int outer_label = new_label();
    int inner_label = new_label();

    fputs("\tpush ix\n\tld ix,0\n\tadd ix,sp\n"
          "\tdec sp\n\tdec sp\n", out);
    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    fprintf(out,
            "L%d:\n\tld (ix-2),0\n\tld (ix-1),0\n"
            "L%d:\n",
            outer_label, inner_label);
    mir_emit_object_parameter_ix(out, plan);
    mir_machine_emit_hl_offset(out, plan->array_offset, 0);
    fputs("\tld e,(ix-2)\n\tld d,(ix-1)\n"
          "\tex de,hl\n\tadd hl,hl\n\tex de,hl\n"
          "\tadd hl,de\n\tpush hl\n", out);
    mir_machine_emit_symbol_call(out, plan->producer);
    fputs("\tpop de\n\tex de,hl\n\tld (hl),e\n\tinc hl\n\tld (hl),d\n"
          "\tinc (ix-2)\n\tld a,(ix-2)\n", out);
    fprintf(out, "\tcp %d\n\tjp c,L%d\n",
            plan->count, inner_label);
    fprintf(out, "\tld hl,%d\n\tpush hl\n", plan->count);
    mir_emit_object_parameter_ix(out, plan);
    mir_machine_emit_hl_offset(out, plan->array_offset, 0);
    fputs("\tpush hl\n", out);
    mir_machine_emit_symbol_call(out, plan->duplicate_check);
    fputs("\tpop bc\n\tpop bc\n\tld a,h\n\tor l\n", out);
    fprintf(out, "\tjp nz,L%d\n", outer_label);
    fprintf(out, "\tld hl,%d\n\tpush hl\n", plan->count);
    mir_emit_object_parameter_ix(out, plan);
    mir_machine_emit_hl_offset(out, plan->array_offset, 0);
    fputs("\tpush hl\n", out);
    mir_emit_object_parameter_ix(out, plan);
    mir_machine_emit_hl_offset(out, plan->copy_offset, 0);
    fputs("\tpush hl\n", out);
    mir_machine_emit_symbol_call(out, plan->copy_function);
    fputs("\tpop bc\n\tpop bc\n\tpop bc\n", out);
    mir_emit_object_parameter_ix(out, plan);
    mir_machine_emit_hl_offset(out, plan->final_offset, 0);
    fprintf(out,
            "\tld (hl),%d\n\tinc hl\n\tld (hl),%d\n"
            "\tld hl,0\n\tld sp,ix\n\tpop ix\n\tret\n",
            plan->final_value & 0xff,
            (plan->final_value >> 8) & 0xff);
}

static void mir_emit_fixed_row_find(
    FILE *out, const struct MirFixedRowFind *plan)
{
    int add;
    int element;
    int next_labels[3];

    for (element = 0; element < 3; ++element)
        next_labels[element] = new_label();

    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    fprintf(out,
            "\tld hl,%d\n\tadd hl,sp\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tex de,hl\n",
            plan->object_stack_offset);
    mir_machine_emit_hl_offset(out, plan->row_member_offset, 0);
    fputs("\tld c,(hl)\n\tinc hl\n\tld b,(hl)\n\tld hl,0\n", out);
    for (add = 0; add < plan->row_stride; ++add)
        fputs("\tadd hl,bc\n", out);
    mir_machine_emit_global_address_de(out, plan->table, 0);
    fputs("\tadd hl,de\n\tpush hl\n", out);
    fprintf(out,
            "\tld hl,%d\n\tadd hl,sp\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tex de,hl\n",
            plan->object_stack_offset + 2);
    mir_machine_emit_hl_offset(out, plan->target_member_offset, 0);
    fputs("\tld c,(hl)\n\tinc hl\n\tld b,(hl)\n\tpop hl\n", out);
    for (element = 0; element < plan->count; ++element) {
        fputs("\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tinc hl\n"
              "\tld a,e\n\txor c\n", out);
        fprintf(out, "\tjp nz,L%d\n", next_labels[element]);
        fputs("\tld a,d\n\txor b\n", out);
        fprintf(out, "\tjp nz,L%d\n", next_labels[element]);
        fprintf(out,
                "\tld hl,%d\n\tadd hl,sp\n"
                "\tld c,(hl)\n\tinc hl\n\tld b,(hl)\n"
                "\tld h,b\n\tld l,c\n\tld (hl),e\n\tinc hl\n\tld (hl),d\n"
                "\tld hl,1\n\tret\n"
                "L%d:\n",
                plan->output_stack_offset,
                next_labels[element]);
    }
    fputs("\tld hl,0\n\tret\n", out);
}

static void mir_emit_local_byte_fill_call_reports(
    FILE *out, const struct MirLocalByteFillCallReports *plan)
{
    int call_index;
    int loop_label = new_label();

    fputs("\tpush ix\n\tld ix,0\n\tadd ix,sp\n", out);
    fprintf(out,
            "\tld hl,%d\n\tadd hl,sp\n\tld sp,hl\n",
            plan->local_offset);
    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    fprintf(out,
            "\tpush ix\n\tpop hl\n\tld de,%d\n\tadd hl,de\n"
            "\tld a,%d\n\tld b,%d\n"
            "L%d:\n\tld (hl),a\n\tinc hl\n\tinc a\n\tdjnz L%d\n",
            plan->local_offset, plan->fill_initial, plan->count,
            loop_label, loop_label);
    for (call_index = 0; call_index < plan->call_count; ++call_index) {
        if (plan->patch_offset >= 0 &&
            call_index == plan->patch_after_call)
            fprintf(out, "\tld (ix%+d),%d\n",
                    plan->local_offset + plan->patch_offset,
                    plan->patch_value);
        fprintf(out, "\tld hl,%d\n\tpush hl\n",
                plan->call_argument);
        fputs("\tpush ix\n\tpop hl\n", out);
        mir_machine_emit_hl_offset(out, plan->local_offset, 0);
        fputs("\tpush hl\n", out);
        mir_machine_emit_symbol_call(
            out, plan->functions[call_index]);
        fputs("\tpop bc\n\tpop bc\n\tpush hl\n", out);
        fprintf(out, "\tld hl,S%d\n\tpush hl\n",
                plan->string_ids[call_index]);
        mir_machine_emit_symbol_call(out, plan->report_function);
        fputs("\tpop bc\n\tpop bc\n", out);
    }
    fputs("\tld hl,0\n\tld sp,ix\n\tpop ix\n\tret\n", out);
}

static void mir_emit_global_record_pop(
    FILE *out, const struct MirGlobalRecordPop *plan)
{
    int add;
    int loop_label = new_label();
    int done_label = new_label();

    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    fprintf(out,
            "L%d:\n"
            "\tld hl,%d\n\tadd hl,sp\n"
            "\tld c,(hl)\n\tinc hl\n\tld b,(hl)\n",
            loop_label, plan->base_stack_offset);
    mir_machine_emit_global_word(out, plan->state, 0);
    mir_machine_emit_hl_offset(out, plan->index_offset, 0);
    fprintf(out,
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tex de,hl\n"
            "\tld a,h\n\txor 128\n\tld h,a\n"
            "\tld a,b\n\txor 128\n\tld b,a\n"
            "\tor a\n\tsbc hl,bc\n\tjp c,L%d\n"
            "\tld a,h\n\tor l\n\tjp z,L%d\n",
            done_label, done_label);
    mir_machine_emit_global_word(out, plan->state, 0);
    mir_machine_emit_hl_offset(out, plan->index_offset, 0);
    fputs("\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tdec de\n"
          "\tld (hl),d\n\tdec hl\n\tld (hl),e\n"
          "\tld b,d\n\tld c,e\n", out);
    mir_machine_emit_global_word(out, plan->state, 0);
    mir_machine_emit_hl_offset(out, plan->records_offset, 0);
    fputs("\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tld hl,0\n", out);
    for (add = 0; add < plan->stride; ++add)
        fputs("\tadd hl,bc\n", out);
    fputs("\tadd hl,de\n", out);
    mir_machine_emit_hl_offset(out, plan->kind_offset, 0);
    fprintf(out,
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
            "\tld a,e\n\tcp %d\n\tjp nz,L%d\n"
            "\tld a,d\n\tcp %d\n\tjp nz,L%d\n",
            plan->wanted_kind & 0xff, loop_label,
            (plan->wanted_kind >> 8) & 0xff, loop_label);
    mir_machine_emit_hl_offset(
        out, plan->value_offset - plan->kind_offset - 1, 0);
    fputs("\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n", out);
    fprintf(out,
            "\tld hl,%d\n\tadd hl,sp\n"
            "\tld c,(hl)\n\tinc hl\n\tld b,(hl)\n"
            "\tld h,b\n\tld l,c\n\tld (hl),e\n\tinc hl\n\tld (hl),d\n"
            "\tld hl,1\n\tret\n"
            "L%d:\n\tld hl,0\n\tret\n",
            plan->target_stack_offset, done_label);
}

static void mir_emit_word_range_bool(
    FILE *out, const struct MirWordRangeBool *plan)
{
    int outside = new_label();

    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    fprintf(out,
            "\tld hl,%d\n\tadd hl,sp\n"
            "\tld e,(hl)\n\tinc hl\n\tld a,(hl)\n\tor a\n"
            "\tjp nz,L%d\n\tld a,e\n\tcp %d\n\tjp nc,L%d\n"
            "\tld hl,1\n\tret\nL%d:\n\tld hl,0\n\tret\n",
            plan->parameter_stack_offset,
            outside, plan->upper, outside, outside);
}

static void mir_emit_ascii_upper(
    FILE *out, const struct MirAsciiUpper *plan)
{
    int result = new_label();

    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    if (plan->width == 1)
        fprintf(out,
                "\tld hl,%d\n\tadd hl,sp\n\tld a,(hl)\n",
                plan->parameter_stack_offset);
    else
        fprintf(out,
                "\tld hl,%d\n\tadd hl,sp\n"
                "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tex de,hl\n"
                "\tld a,h\n\tor a\n\tjp nz,L%d\n\tld a,l\n",
                plan->parameter_stack_offset, result);
    fprintf(out,
            "\tcp %d\n\tjp c,L%d\n\tcp %d\n\tjp nc,L%d\n",
            plan->lower, result, plan->upper + 1, result);
    if (plan->adjustment < 0)
        fprintf(out, "\tsub %d\n", -plan->adjustment);
    else if (plan->adjustment > 0)
        fprintf(out, "\tadd a,%d\n", plan->adjustment);
    if (plan->width == 1)
        fprintf(out,
                "L%d:\n\tld l,a\n\trlca\n\tsbc a,a\n\tld h,a\n\tret\n",
                result);
    else
        fprintf(out, "\tld l,a\nL%d:\n\tret\n", result);
}

static void mir_emit_fixed_word_array_sum(
    FILE *out, const struct MirFixedWordArraySum *plan)
{
    int element;
    int offset;

    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    if (!plan->pointer_is_volatile) {
        fprintf(out,
                "\tld hl,%d\n\tadd hl,sp\n"
                "\tld c,(hl)\n\tinc hl\n\tld b,(hl)\n"
                "\tld de,0\n",
                plan->parameter_stack_offset);
        for (element = 0; element < plan->count; ++element)
            fputs("\tld a,(bc)\n\tinc bc\n\tld l,a\n"
                  "\tld a,(bc)\n\tinc bc\n\tld h,a\n"
                  "\tadd hl,de\n\tex de,hl\n", out);
        fputs("\tex de,hl\n\tret\n", out);
        return;
    }
    fputs("\tld bc,0\n", out);
    for (element = 0; element < plan->count; ++element) {
        fprintf(out,
                "\tld hl,%d\n\tadd hl,sp\n"
                "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tex de,hl\n",
                plan->parameter_stack_offset);
        for (offset = 0; offset < element * 2; ++offset)
            fputs("\tinc hl\n", out);
        fputs("\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
              "\tld h,b\n\tld l,c\n\tadd hl,de\n"
              "\tld b,h\n\tld c,l\n", out);
    }
    fputs("\tld h,b\n\tld l,c\n\tret\n", out);
}

static void mir_emit_slice_word_sum(
    FILE *out, const struct MirSliceWordSum *plan)
{
    int done = new_label();
    int empty = new_label();
    int loop = new_label();

    fprintf(out,
            ";@dcc.reg claim=iy scope=function sym=%s kind=mir val=0\n"
            "\tpush iy\n",
            mir.name);
    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    fprintf(out,
            "\tld hl,%d\n\tadd hl,sp\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
            "\tbit 7,d\n\tjp nz,L%d\n"
            "\tld a,d\n\tor e\n\tjp z,L%d\n"
            "\tld hl,%d\n\tadd hl,sp\n"
            "\tld c,(hl)\n\tinc hl\n\tld b,(hl)\n"
            "\tpush bc\n\tpop iy\n\tadd iy,de\n\tadd iy,de\n"
            "\tld de,0\n"
            "L%d:\n\tld a,(bc)\n\tinc bc\n\tld l,a\n"
            "\tld a,(bc)\n\tinc bc\n\tld h,a\n"
            "\tadd hl,de\n\tex de,hl\n"
            "\tpush iy\n\tpop hl\n\tor a\n\tsbc hl,bc\n"
            "\tjp nz,L%d\n\tex de,hl\n\tjp L%d\n"
            "L%d:\n\tld hl,0\n"
            "L%d:\n\tpop iy\n"
            ";@dcc.reg free=iy\n\tret\n",
            plan->parameter_stack_offset + plan->count_offset + 2,
            empty, empty,
            plan->parameter_stack_offset + plan->data_offset + 2,
            loop, loop, done, empty, done);
}

static void mir_emit_conditional_null_identity(
    FILE *out, const struct MirConditionalNullIdentity *plan)
{
    int is_false = new_label();
    int is_true = new_label();

    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    fprintf(out,
            "\tld hl,%d\n\tadd hl,sp\n"
            "\tld a,(hl)\n\tinc hl\n\tor (hl)\n\tjp z,L%d\n"
            "\tld hl,%d\n\tadd hl,sp\n"
            "\tld a,(hl)\n\tinc hl\n\tor (hl)\n\tjp nz,L%d\n"
            "L%d:\n\tld hl,1\n\tret\n"
            "L%d:\n\tld hl,0\n\tret\n",
            plan->condition_stack_offset, is_true,
            plan->pointer_stack_offset, is_false,
            is_true, is_false);
}

static void mir_emit_wide_constant_equal(
    FILE *out, const struct MirWideConstantEqual *plan)
{
    int byte;

    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    fprintf(out, "\tld hl,%d\n\tadd hl,sp\n\tld c,0\n",
            plan->parameter_stack_offset);
    for (byte = 0; byte < 4; ++byte) {
        fprintf(out, "\tld a,(hl)\n\txor %lu\n\tor c\n\tld c,a\n",
                (plan->value >> (byte * 8)) & 0xffUL);
        if (byte != 3)
            fputs("\tinc hl\n", out);
    }
    fputs("\tld hl,0\n\tor a\n\tret nz\n\tinc hl\n\tret\n", out);
}

static void mir_emit_float_truth_once(
    FILE *out, const struct MirFloatTruthOnce *plan)
{
    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    fprintf(out,
            "\tld hl,%d\n\tadd hl,sp\n"
            "\tld a,(hl)\n\tinc hl\n\tor (hl)\n\tinc hl\n"
            "\tor (hl)\n\tld c,a\n\tinc hl\n\tld a,(hl)\n"
            "\tand 127\n\tor c\n\tld hl,0\n\tret z\n\tinc hl\n\tret\n",
            plan->parameter_stack_offset);
}

static void mir_emit_nested_word_long_select(
    FILE *out, const struct MirNestedWordLongSelect *plan)
{
    int second = new_label();
    int third = new_label();
    int selected = new_label();

    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    fprintf(out,
            "\tld hl,%d\n\tadd hl,sp\n"
            "\tld a,(hl)\n\tinc hl\n\tor (hl)\n\tjp z,L%d\n"
            "\tld hl,%d\n\tjp L%d\n"
            "L%d:\n\tld hl,%d\n\tadd hl,sp\n"
            "\tld a,(hl)\n\tinc hl\n\tor (hl)\n\tjp z,L%d\n"
            "\tld hl,%d\n\tjp L%d\n"
            "L%d:\n",
            plan->first_condition_stack_offset, second,
            plan->first_value, selected,
            second, plan->second_condition_stack_offset, third,
            plan->second_value, selected, third);
    if (plan->third_is_parameter)
        fprintf(out,
                "\tld hl,%d\n\tadd hl,sp\n"
                "\tld e,(hl)\n\tinc hl\n\tld h,(hl)\n\tld l,e\n",
                plan->third_stack_offset);
    else
        fprintf(out, "\tld hl,%d\n", plan->third_value);
    fprintf(out,
            "L%d:\n\tld a,h\n\trlca\n\tsbc a,a\n"
            "\tld e,a\n\tld d,a\n\tret\n",
            selected);
}

static void mir_emit_float_int_truth(
    FILE *out, const struct MirFloatIntTruth *plan)
{
    int false_result = new_label();
    int true_result = new_label();

    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    fprintf(out,
            "\tld hl,%d\n\tadd hl,sp\n"
            "\tld a,(hl)\n\tinc hl\n\tor (hl)\n\tinc hl\n"
            "\tor (hl)\n\tld c,a\n\tinc hl\n\tld a,(hl)\n"
            "\tand 127\n\tor c\n",
            plan->float_stack_offset);
    if (plan->operation == '&')
        fprintf(out, "\tjp z,L%d\n", false_result);
    else
        fprintf(out, "\tjp nz,L%d\n", true_result);
    fprintf(out,
            "\tld hl,%d\n\tadd hl,sp\n"
            "\tld a,(hl)\n\tinc hl\n\tor (hl)\n",
            plan->int_stack_offset);
    if (plan->operation == '&')
        fprintf(out, "\tjp z,L%d\n", false_result);
    else
        fprintf(out, "\tjp nz,L%d\n", true_result);
    if (plan->operation == '|')
        fprintf(out, "L%d:\n", false_result);
    fprintf(out, "\tld hl,%d\n\tret\n",
            plan->operation == '&' ? 1 : 0);
    if (plan->operation == '&')
        fprintf(out, "L%d:\n\tld hl,0\n\tret\n", false_result);
    else
        fprintf(out, "L%d:\n\tld hl,1\n\tret\n", true_result);
}

static void mir_emit_conditional_float_long(
    FILE *out, const struct MirConditionalFloatLong *plan)
{
    int false_arm = new_label();

    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    fprintf(out,
            "\tld hl,%d\n\tadd hl,sp\n"
            "\tld a,(hl)\n\tinc hl\n\tor (hl)\n\tjp z,L%d\n"
            "\tld hl,%d\n\tld a,h\n\trlca\n\tsbc a,a\n"
            "\tld e,a\n\tld d,a\n\tret\n"
            "L%d:\n",
            plan->condition_stack_offset, false_arm,
            plan->true_value, false_arm);
    if (plan->kind == MIR_CONDITIONAL_FLOAT_ADD) {
        mir_emit_wide_parameter(out, plan->argument_stack_offset);
        fputs("\tpush de\n\tpush hl\n", out);
        fprintf(out, "\tld hl,%lu\n\tld de,%lu\n",
                plan->add_bits & 0xffffUL,
                (plan->add_bits >> 16) & 0xffffUL);
        mir_emit_runtime_call(out, "__faf");
        fputs("\tpop bc\n\tpop bc\n", out);
    } else {
        fprintf(out,
                "\tld hl,%d\n\tadd hl,sp\n"
                "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tpush de\n",
                plan->argument_stack_offset);
        mir_machine_emit_symbol_call(out, plan->function);
        fputs("\tpop bc\n", out);
    }
    mir_emit_runtime_call(out, "__ffl");
    fputs("\tret\n", out);
}

static void mir_emit_word_as_long_return(FILE *out, int value)
{
    fprintf(out,
            "\tld hl,%d\n\tld a,h\n\trlca\n\tsbc a,a\n"
            "\tld e,a\n\tld d,a\n\tret\n",
            value);
}

static void mir_emit_conditional_pointer_float_long(
    FILE *out, const struct MirConditionalPointerFloatLong *plan)
{
    int false_arm = new_label();
    int selected = new_label();

    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    fprintf(out,
            "\tld hl,%d\n\tadd hl,sp\n"
            "\tld a,(hl)\n\tinc hl\n\tor (hl)\n\tjp z,L%d\n",
            plan->condition_stack_offset, false_arm);
    mir_machine_emit_global_address_de(
        out, plan->true_root, plan->element_offset);
    fprintf(out, "\tex de,hl\n\tjp L%d\nL%d:\n",
            selected, false_arm);
    mir_machine_emit_global_word(out, plan->false_pointer, 0);
    if (plan->element_offset != 0)
        fprintf(out, "\tld de,%d\n\tadd hl,de\n",
                plan->element_offset);
    fprintf(out, "L%d:\n", selected);
    fputs("\tld c,(hl)\n\tinc hl\n\tld b,(hl)\n"
          "\tinc hl\n\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
          "\tld l,c\n\tld h,b\n", out);
    mir_emit_runtime_call(out, "__ffl");
    fputs("\tret\n", out);
}

static void mir_emit_nested_member_float_long(
    FILE *out, const struct MirNestedMemberFloatLong *plan)
{
    int second = new_label();
    int third = new_label();

    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    fprintf(out,
            "\tld hl,%d\n\tadd hl,sp\n"
            "\tld a,(hl)\n\tinc hl\n\tor (hl)\n\tjp z,L%d\n",
            plan->first_condition_stack_offset, second);
    mir_emit_word_as_long_return(out, plan->first_value);
    fprintf(out,
            "L%d:\n\tld hl,%d\n\tadd hl,sp\n"
            "\tld a,(hl)\n\tinc hl\n\tor (hl)\n\tjp z,L%d\n",
            second, plan->second_condition_stack_offset, third);
    mir_emit_word_as_long_return(out, plan->second_value);
    fprintf(out,
            "L%d:\n\tld hl,%d\n\tadd hl,sp\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tex de,hl\n",
            third, plan->pointer_stack_offset);
    if (plan->member_offset != 0)
        fprintf(out, "\tld de,%d\n\tadd hl,de\n",
                plan->member_offset);
    fputs("\tld c,(hl)\n\tinc hl\n\tld b,(hl)\n"
          "\tinc hl\n\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
          "\tld l,c\n\tld h,b\n", out);
    mir_emit_runtime_call(out, "__ffl");
    fputs("\tret\n", out);
}

static void mir_emit_conditional_float_compare_long(
    FILE *out, const struct MirConditionalFloatCompareLong *plan)
{
    int false_arm = new_label();
    int nonpositive = new_label();

    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    fprintf(out,
            "\tld hl,%d\n\tadd hl,sp\n"
            "\tld a,(hl)\n\tinc hl\n\tor (hl)\n\tjp z,L%d\n",
            plan->condition_stack_offset, false_arm);
    mir_emit_word_as_long_return(out, plan->true_value);
    fprintf(out, "L%d:\n", false_arm);
    mir_emit_wide_parameter(out, plan->float_stack_offset);
    fputs("\tpush de\n\tpush hl\n\tld hl,0\n\tld de,0\n", out);
    mir_emit_runtime_call(out, "__fltf");
    fputs("\tpop bc\n\tpop bc\n\tld a,h\n\tor l\n", out);
    fprintf(out, "\tjp z,L%d\n", nonpositive);
    mir_emit_word_as_long_return(out, plan->positive_value);
    fprintf(out, "L%d:\n", nonpositive);
    mir_emit_word_as_long_return(out, plan->nonpositive_value);
}

static void mir_emit_conditional_bool(
    FILE *out, const struct MirConditionalBool *plan)
{
    int false_arm = new_label();

    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    if (plan->true_value == plan->false_value) {
        fprintf(out, "\tld hl,%d\n\tret\n", plan->true_value);
        return;
    }
    fprintf(out,
            "\tld hl,%d\n\tadd hl,sp\n"
            "\tld a,(hl)\n\tinc hl\n\tor (hl)\n\tjp z,L%d\n"
            "\tld hl,%d\n\tret\n"
            "L%d:\n\tld hl,%d\n\tret\n",
            plan->condition_stack_offset, false_arm,
            plan->true_value, false_arm, plan->false_value);
}

static void mir_emit_logical_or_parameters(
    FILE *out, const struct MirLogicalOrParameters *plan)
{
    int nonzero = new_label();

    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    fprintf(out,
            "\tld hl,%d\n\tadd hl,sp\n"
            "\tld a,(hl)\n\tinc hl\n\tor (hl)\n\tjp nz,L%d\n"
            "\tld hl,%d\n\tadd hl,sp\n"
            "\tld a,(hl)\n\tinc hl\n\tor (hl)\n\tjp nz,L%d\n"
            "\tld hl,0\n\tret\n"
            "L%d:\n\tld hl,1\n\tret\n",
            plan->first_stack_offset, nonzero,
            plan->second_stack_offset, nonzero, nonzero);
}

static void mir_emit_cleared_record_field(
    FILE *out, int field_offset, int parameter_offset)
{
    fprintf(out,
            "\tld hl,%d\n\tadd hl,sp\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n",
            parameter_offset);
    fputs("\tpush iy\n\tpop hl\n", out);
    mir_machine_emit_hl_offset(out, field_offset, 0);
    fputs("\tld (hl),e\n\tinc hl\n\tld (hl),d\n", out);
}

static void mir_emit_cleared_record_append(
    FILE *out, const struct MirClearedRecordAppend *plan)
{
    fprintf(out,
            ";@dcc.reg claim=iy scope=function sym=%s kind=mir val=0\n"
            "\tpush iy\n",
            mir.name);
    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    mir_machine_emit_global_word(out, plan->root, plan->root_offset);
    mir_machine_emit_hl_offset(out, plan->cursor_member_offset, 0);
    fputs("\tld c,(hl)\n\tinc hl\n\tld b,(hl)\n"
          "\tinc bc\n\tld (hl),b\n\tdec hl\n\tld (hl),c\n", out);
    fputs("\tdec bc\n", out);
    mir_machine_emit_global_word(out, plan->root, plan->root_offset);
    mir_machine_emit_hl_offset(out, plan->array_member_offset, 0);
    fputs("\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
          "\tpush de\n\tld h,b\n\tld l,c\n", out);
    mir_emit_mul_hl_const(out, (unsigned long)plan->stride);
    fputs("\tpop de\n\tadd hl,de\n\tpush hl\n\tpop iy\n", out);
    fprintf(out, "\tld hl,%d\n\tpush hl\n\tld hl,0\n\tpush hl\n",
            plan->stride);
    fputs("\tpush iy\n", out);
    mir_machine_emit_symbol_call(out, plan->clear_function);
    fputs("\tpop bc\n\tpop bc\n\tpop bc\n", out);
    fprintf(out,
            "\tld hl,%d\n\tadd hl,sp\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tpush de\n",
            plan->name_stack_offset + 2);
    fputs("\tpush iy\n", out);
    mir_machine_emit_symbol_call(out, plan->copy_function);
    fputs("\tpop bc\n\tpop bc\n", out);
    mir_emit_cleared_record_field(
        out, plan->kind_field_offset, plan->kind_stack_offset + 2);
    mir_emit_cleared_record_field(
        out, plan->value_field_offset, plan->value_stack_offset + 2);
    mir_machine_emit_global_word(out, plan->root, plan->root_offset);
    mir_machine_emit_hl_offset(out, plan->cursor_member_offset, 0);
    fputs("\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
          "\tex de,hl\n\tdec hl\n\tpop iy\n"
          ";@dcc.reg free=iy\n\tret\n", out);
}

static void mir_emit_record_name_search(
    FILE *out, const struct MirRecordNameSearch *plan)
{
    int done = new_label();
    int found = new_label();
    int loop = new_label();
    int not_found = new_label();

    fprintf(out,
            ";@dcc.reg claim=iy scope=function sym=%s kind=mir val=0\n"
            "\tpush iy\n",
            mir.name);
    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    mir_machine_emit_global_word(out, plan->root, plan->root_offset);
    mir_machine_emit_hl_offset(out, plan->cursor_member_offset, 0);
    fputs("\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
          "\tex de,hl\n\tdec hl\n\tpush hl\n\tpop iy\n", out);
    fprintf(out,
            "L%d:\n\tpush iy\n\tpop hl\n"
            "\tbit 7,h\n\tjp nz,L%d\n",
            loop, not_found);
    mir_machine_emit_global_word(out, plan->root, plan->root_offset);
    mir_machine_emit_hl_offset(out, plan->array_member_offset, 0);
    fputs("\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tpush de\n"
          "\tpush iy\n\tpop hl\n", out);
    mir_emit_mul_hl_const(out, (unsigned long)plan->stride);
    fputs("\tpop de\n\tadd hl,de\n", out);
    mir_machine_emit_hl_offset(out, plan->name_field_offset, 0);
    fputs("\tld c,l\n\tld b,h\n", out);
    fprintf(out,
            "\tld hl,%d\n\tadd hl,sp\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
            "\tpush de\n\tpush bc\n",
            plan->name_stack_offset + 2);
    mir_machine_emit_symbol_call(out, plan->compare_function);
    fputs("\tpop bc\n\tpop bc\n\tld a,h\n\tor l\n", out);
    fprintf(out,
            "\tjp z,L%d\n\tdec iy\n\tjp L%d\n"
            "L%d:\n\tpush iy\n\tpop hl\n\tjp L%d\n"
            "L%d:\n\tld hl,65535\n"
            "L%d:\n\tpop iy\n"
            ";@dcc.reg free=iy\n\tret\n",
            found, loop, found, done,
            not_found, done);
}

static void mir_emit_sequential_unary_reports(
    FILE *out, const struct MirSequentialUnaryReports *plan)
{
    int parameter;

    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    for (parameter = 4; parameter >= 0; --parameter) {
        fprintf(out,
                "\tld hl,%d\n\tadd hl,sp\n"
                "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tpush de\n",
                plan->parameter_stack_offsets[parameter] +
                    (4 - parameter) * 2);
        mir_machine_emit_symbol_call(out, plan->helper);
        fputs("\tpop bc\n\tpush hl\n", out);
    }
    fprintf(out, "\tld hl,S%d\n\tpush hl\n", plan->string_id);
    mir_machine_emit_symbol_call(out, plan->print_function);
    for (parameter = 0; parameter < 6; ++parameter)
        fputs("\tpop bc\n", out);
    fputs("\tret\n", out);
}

static void mir_emit_nibble_append(
    FILE *out, const struct MirNibbleAppend *plan)
{
    int done = new_label();
    int ready = new_label();

    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    fprintf(out,
            "\tld hl,%d\n\tadd hl,sp\n\tld c,(hl)\n"
            "\tld hl,%d\n\tadd hl,sp\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tex de,hl\n"
            "\tld a,c\n\tcp %d\n",
            plan->value_stack_offset,
            plan->pointer_stack_offset, plan->threshold);
    if (plan->high_adjustment < 0)
        fprintf(out, "\tjp c,L%d\n\tsub %d\n\tjp L%d\n",
                ready, -plan->high_adjustment, done);
    else
        fprintf(out, "\tjp c,L%d\n\tadd a,%d\n\tjp L%d\n",
                ready, plan->high_adjustment, done);
    fprintf(out, "L%d:\n", ready);
    if (plan->low_adjustment < 0)
        fprintf(out, "\tsub %d\n", -plan->low_adjustment);
    else if (plan->low_adjustment > 0)
        fprintf(out, "\tadd a,%d\n", plan->low_adjustment);
    fprintf(out, "L%d:\n\tld (hl),a\n\tinc hl\n\tret\n", done);
}

static void mir_emit_volatile_fill_wide_constant(
    FILE *out, const struct MirVolatileFillWideConstant *plan)
{
    int loop = new_label();

    fputs("\tpush ix\n\tld ix,0\n\tadd ix,sp\n", out);
    fprintf(out, "\tld hl,%d\n\tadd hl,sp\n\tld sp,hl\n",
            plan->buffer_offset);
    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    fputs("\tpush ix\n\tpop hl\n", out);
    fprintf(out,
            "\tld de,%d\n\tadd hl,de\n\tld a,0\n\tld b,%d\n"
            "L%d:\n\tld (hl),a\n\tinc hl\n\tinc a\n\tdjnz L%d\n"
            "\tld hl,%lu\n\tld de,%lu\n"
            "\tld sp,ix\n\tpop ix\n\tret\n",
            plan->buffer_offset, plan->count, loop, loop,
            plan->result & 0xffffUL,
            (plan->result >> 16) & 0xffffUL);
}

static void mir_emit_single_signed_div_check(
    FILE *out, const struct MirSingleSignedDivCheck *plan)
{
    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    fprintf(out,
            "\tld hl,%d\n\tadd hl,sp\n"
            "\tld c,(hl)\n\tinc hl\n\tld b,(hl)\n"
            "\tld hl,%d\n\tadd hl,sp\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
            "\tld h,b\n\tld l,c\n",
            plan->numerator_stack_offset,
            plan->denominator_stack_offset);
    mir_emit_runtime_call(
        out, plan->operation == '%' ? "__mods" : "__divs");
    fputs("\tld c,l\n\tld b,h\n", out);
    fprintf(out,
            "\tld hl,%d\n\tadd hl,sp\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tpush de\n"
            "\tld hl,%d\n\tadd hl,sp\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tpush de\n"
            "\tpush bc\n",
            plan->label_stack_offset,
            plan->expected_stack_offset + 2);
    mir_machine_emit_symbol_call(out, plan->check_function);
    fputs("\tpop bc\n\tpop bc\n\tpop bc\n\tret\n", out);
}

static void mir_emit_wide_ix_load(FILE *out, int offset)
{
    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
            "\tld e,(ix%+d)\n\tld d,(ix%+d)\n",
            offset, offset + 1, offset + 2, offset + 3);
}

static void mir_emit_wide_ix_store(FILE *out, int offset)
{
    fprintf(out,
            "\tld (ix%+d),l\n\tld (ix%+d),h\n"
            "\tld (ix%+d),e\n\tld (ix%+d),d\n",
            offset, offset + 1, offset + 2, offset + 3);
}

static void mir_emit_wide_ix_equal_branch(
    FILE *out, int expected_offset, int equal_label)
{
    fprintf(out,
            "\tld a,l\n\txor (ix%+d)\n\tld c,a\n"
            "\tld a,h\n\txor (ix%+d)\n\tor c\n\tld c,a\n"
            "\tld a,e\n\txor (ix%+d)\n\tor c\n\tld c,a\n"
            "\tld a,d\n\txor (ix%+d)\n\tor c\n"
            "\tjp z,L%d\n",
            expected_offset, expected_offset + 1,
            expected_offset + 2, expected_offset + 3,
            equal_label);
}

static void mir_emit_wide_div_failure(
    FILE *out, const struct MirWideDivResultCheck *plan,
    int actual_offset, int expected_offset)
{
    mir_emit_local_wide_argument(out, expected_offset);
    mir_emit_wide_ix_load(out, actual_offset);
    fputs("\tpush de\n\tpush hl\n", out);
    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n\tpush hl\n",
            plan->name_stack_offset + 2,
            plan->name_stack_offset + 3);
    mir_machine_emit_symbol_call(out, plan->failure_function);
    fputs("\tpop bc\n\tpop bc\n\tpop bc\n\tpop bc\n\tpop bc\n", out);
}

static void mir_emit_wide_div_result_check(
    FILE *out, const struct MirWideDivResultCheck *plan)
{
    int quotient_ok = new_label();
    int remainder_ok = new_label();
    int identity_ok = new_label();
    int numerator_offset = plan->numerator_stack_offset + 2;
    int denominator_offset = plan->denominator_stack_offset + 2;
    int expected_quotient_offset =
        plan->expected_quotient_stack_offset + 2;
    int expected_remainder_offset =
        plan->expected_remainder_stack_offset + 2;

    fputs("\tpush ix\n\tld ix,0\n\tadd ix,sp\n"
          "\tld hl,-8\n\tadd hl,sp\n\tld sp,hl\n", out);
    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");

    mir_emit_local_wide_argument(out, denominator_offset);
    mir_emit_local_wide_argument(out, numerator_offset);
    mir_emit_local_address(out, plan->result_offset);
    fputs("\tpush hl\n", out);
    mir_machine_emit_symbol_call(out, plan->divide_function);
    fputs("\tpop bc\n\tpop bc\n\tpop bc\n\tpop bc\n\tpop bc\n", out);

    mir_emit_wide_ix_load(out, plan->result_offset);
    mir_emit_wide_ix_equal_branch(
        out, expected_quotient_offset, quotient_ok);
    mir_emit_wide_div_failure(
        out, plan, plan->result_offset, expected_quotient_offset);
    fprintf(out, "L%d:\n", quotient_ok);

    mir_emit_wide_ix_load(out, plan->result_offset + 4);
    mir_emit_wide_ix_equal_branch(
        out, expected_remainder_offset, remainder_ok);
    mir_emit_wide_div_failure(
        out, plan, plan->result_offset + 4,
        expected_remainder_offset);
    fprintf(out, "L%d:\n", remainder_ok);

    mir_emit_wide_ix_load(out, plan->result_offset);
    fputs("\tpush de\n\tpush hl\n", out);
    mir_emit_wide_ix_load(out, denominator_offset);
    mir_emit_runtime_call(out, "__lmul");
    fputs("\tpop bc\n\tpop bc\n\tpush de\n\tpush hl\n", out);
    mir_emit_wide_ix_load(out, plan->result_offset + 4);
    fputs("\tpop bc\n\tadd hl,bc\n\tex de,hl\n"
          "\tpop bc\n\tadc hl,bc\n\tex de,hl\n", out);
    mir_emit_wide_ix_store(out, plan->result_offset);
    mir_emit_wide_ix_equal_branch(out, numerator_offset, identity_ok);
    mir_emit_wide_div_failure(
        out, plan, plan->result_offset, numerator_offset);
    fprintf(out,
            "L%d:\n\tld sp,ix\n\tpop ix\n\tret\n",
            identity_ok);
}

static void mir_emit_final_call_constant(
    FILE *out, unsigned long value, int width)
{
    if (width == 4)
        mir_emit_fixed_point_constant(out, value);
    else
        fprintf(out, "\tld hl,%lu\n\tpush hl\n",
                value & 0xffffUL);
}

static void mir_emit_final_call_cleanup(
    FILE *out, int words)
{
    while (words-- > 0)
        fputs("\tpop bc\n", out);
}

static void mir_emit_final_call_check(
    FILE *out, const struct MirFinalCallCheck *check)
{
    int argument;
    int words = check->width / 2;

    if (check->kind == MIR_FINAL_CALL_DIRECT) {
        for (argument = 3; argument >= 0; --argument)
            mir_emit_final_call_constant(
                out, check->direct_values[argument],
                check->width);
    } else {
        mir_emit_final_call_constant(
            out, check->expected, check->width);
        if (check->kind == MIR_FINAL_CALL_NESTED_STRING)
            fprintf(out, "\tld hl,S%d\n\tpush hl\n",
                    check->value_string_id);
        else
            mir_emit_final_call_constant(
                out, check->value, check->width);
        mir_machine_emit_symbol_call(
            out, check->value_function);
        mir_emit_final_call_cleanup(
            out,
            check->kind == MIR_FINAL_CALL_NESTED_STRING ?
                1 : words);
        if (check->width == 4)
            fputs("\tpush de\n\tpush hl\n", out);
        else
            fputs("\tpush hl\n", out);
    }
    fprintf(out, "\tld hl,S%d\n\tpush hl\n",
            check->name_string_id);
    mir_machine_emit_symbol_call(
        out, check->check_function);
    mir_emit_final_call_cleanup(
        out,
        check->kind == MIR_FINAL_CALL_DIRECT ?
            1 + 4 * words : 1 + 2 * words);
}

static void mir_emit_final_call_check_schedule(
    FILE *out, const struct MirFinalCallCheckSchedule *plan)
{
    int check;
    int success = new_label();

    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    for (check = 0;
         check < MIR_FINAL_CALL_CHECK_COUNT; ++check)
        mir_emit_final_call_check(out, &plan->checks[check]);
    mir_machine_emit_global_word(
        out, plan->failure_root, plan->failure_offset);
    fputs("\tld a,h\n\tor l\n", out);
    fprintf(out,
            "\tjp z,L%d\n\tld hl,1\n\tret\n"
            "L%d:\n\tld hl,S%d\n\tpush hl\n",
            success, success, plan->success_string_id);
    mir_machine_emit_symbol_call(out, plan->print_function);
    fputs("\tpop bc\n\tld hl,0\n\tret\n", out);
}

static int mir_emit_math_constant_argument(
    FILE *out, const struct MirMathConstant *argument)
{
    if (argument->kind == MIR_MATH_FLOAT_CONSTANT) {
        mir_emit_final_call_constant(out, argument->value, 4);
        return 2;
    }
    fprintf(out, "\tld hl,%lu\n\tpush hl\n",
            argument->value & 0xffffUL);
    return 1;
}

static void mir_emit_math_call_check(
    FILE *out, const struct MirMathCallCheck *check)
{
    int argument;
    int argument_words = 0;

    mir_emit_final_call_constant(
        out, check->expected_bits, 4);
    for (argument = check->argument_count - 1;
         argument >= 0; --argument)
        argument_words += mir_emit_math_constant_argument(
            out, &check->arguments[argument]);
    mir_machine_emit_symbol_call(
        out, check->value_function);
    mir_emit_final_call_cleanup(out, argument_words);
    fputs("\tpush de\n\tpush hl\n", out);
    fprintf(out, "\tld hl,S%d\n\tpush hl\n",
            check->string_id);
    mir_machine_emit_symbol_call(
        out, check->check_function);
    mir_emit_final_call_cleanup(out, 5);
}

static void mir_emit_math_frexp_check(
    FILE *out, const struct MirMathPointerCheck *check)
{
    mir_emit_final_call_constant(
        out, check->result_bits, 4);
    mir_emit_local_address(out, -2);
    fputs("\tpush hl\n", out);
    mir_emit_final_call_constant(
        out, check->input_bits, 4);
    mir_machine_emit_symbol_call(
        out, check->value_function);
    mir_emit_final_call_cleanup(out, 3);
    fputs("\tpush de\n\tpush hl\n", out);
    fprintf(out, "\tld hl,S%d\n\tpush hl\n",
            check->result_string_id);
    mir_machine_emit_symbol_call(
        out, check->check_function);
    mir_emit_final_call_cleanup(out, 5);

    mir_emit_final_call_constant(
        out, check->output_bits, 4);
    fputs("\tld l,(ix-2)\n\tld h,(ix-1)\n", out);
    mir_emit_runtime_call(out, "__fif");
    fputs("\tpush de\n\tpush hl\n", out);
    fprintf(out, "\tld hl,S%d\n\tpush hl\n",
            check->output_string_id);
    mir_machine_emit_symbol_call(
        out, check->check_function);
    mir_emit_final_call_cleanup(out, 5);
}

static void mir_emit_math_modf_check(
    FILE *out, const struct MirMathPointerCheck *check)
{
    mir_emit_final_call_constant(
        out, check->result_bits, 4);
    mir_emit_local_address(out, -4);
    fputs("\tpush hl\n", out);
    mir_emit_final_call_constant(
        out, check->input_bits, 4);
    mir_machine_emit_symbol_call(
        out, check->value_function);
    mir_emit_final_call_cleanup(out, 3);
    fputs("\tpush de\n\tpush hl\n", out);
    fprintf(out, "\tld hl,S%d\n\tpush hl\n",
            check->result_string_id);
    mir_machine_emit_symbol_call(
        out, check->check_function);
    mir_emit_final_call_cleanup(out, 5);

    mir_emit_final_call_constant(
        out, check->output_bits, 4);
    fputs("\tld l,(ix-4)\n\tld h,(ix-3)\n"
          "\tld e,(ix-2)\n\tld d,(ix-1)\n"
          "\tpush de\n\tpush hl\n", out);
    fprintf(out, "\tld hl,S%d\n\tpush hl\n",
            check->output_string_id);
    mir_machine_emit_symbol_call(
        out, check->check_function);
    mir_emit_final_call_cleanup(out, 5);
}

static void mir_emit_math_verification_schedule(
    FILE *out, const struct MirMathVerificationSchedule *plan)
{
    int failure = new_label();
    int check;

    fputs("\tpush ix\n\tld ix,0\n\tadd ix,sp\n"
          "\tld hl,-4\n\tadd hl,sp\n\tld sp,hl\n", out);
    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    fprintf(out, "\tld hl,S%d\n\tpush hl\n",
            plan->intro_string_id);
    mir_machine_emit_symbol_call(
        out, plan->print_function);
    mir_emit_final_call_cleanup(out, 1);

    for (check = 0;
         check < MIR_MATH_ORDINARY_CHECK_COUNT; ++check)
        mir_emit_math_call_check(out, &plan->calls[check]);
    for (check = 0;
         check < MIR_MATH_FREXP_CHECK_COUNT; ++check)
        mir_emit_math_frexp_check(out, &plan->frexp[check]);
    for (check = 0;
         check < MIR_MATH_MODEXP_CHECK_COUNT; ++check)
        mir_emit_math_call_check(
            out,
            &plan->calls[
                MIR_MATH_ORDINARY_CHECK_COUNT + check]);
    for (check = 0;
         check < MIR_MATH_MODF_CHECK_COUNT; ++check)
        mir_emit_math_modf_check(out, &plan->modf[check]);

    fprintf(out, "\tld hl,S%d\n\tpush hl\n",
            plan->separator_string_id);
    mir_machine_emit_symbol_call(
        out, plan->print_function);
    mir_emit_final_call_cleanup(out, 1);
    mir_machine_emit_global_word(
        out, plan->failures_root, plan->failures_offset);
    fputs("\tpush hl\n", out);
    mir_machine_emit_global_word(
        out, plan->checks_root, plan->checks_offset);
    fputs("\tpush hl\n", out);
    fprintf(out, "\tld hl,S%d\n\tpush hl\n",
            plan->summary_string_id);
    mir_machine_emit_symbol_call(
        out, plan->print_function);
    mir_emit_final_call_cleanup(out, 3);

    mir_machine_emit_global_word(
        out, plan->failures_root, plan->failures_offset);
    fputs("\tld a,h\n\tor l\n", out);
    fprintf(out, "\tjp nz,L%d\n\tld hl,S%d\n\tpush hl\n",
            failure, plan->success_string_id);
    mir_machine_emit_symbol_call(
        out, plan->print_function);
    fputs("\tpop bc\n\tld hl,0\n"
          "\tld sp,ix\n\tpop ix\n\tret\n", out);
    fprintf(out, "L%d:\n\tld hl,S%d\n\tpush hl\n",
            failure, plan->failure_string_id);
    mir_machine_emit_symbol_call(
        out, plan->print_function);
    fputs("\tpop bc\n\tld hl,1\n"
          "\tld sp,ix\n\tpop ix\n\tret\n", out);
}

static void mir_emit_ctype_pointer_load(FILE *out)
{
    fputs("\tpop hl\n\tpush hl\n", out);
}

static void mir_emit_ctype_pointer_store(FILE *out)
{
    fputs("\tpop bc\n\tpush hl\n", out);
}

static void mir_emit_ctype_compare_bool(
    FILE *out, unsigned long expected, int comparison)
{
    int done = new_label();

    if ((expected & 0xffffUL) == 0)
        fputs("\tld a,h\n\tor l\n", out);
    else
        fprintf(out, "\tld de,%lu\n\tor a\n\tsbc hl,de\n",
                expected & 0xffffUL);
    fprintf(out,
            "\tld hl,0\n\tjp %s,L%d\n\tinc hl\nL%d:\n",
            comparison == TOK_EQ ? "nz" : "z",
            done, done);
}

static void mir_emit_ctype_check_result(
    FILE *out, unsigned long expected, int comparison,
    int string_id, struct Sym *check_function)
{
    mir_emit_ctype_compare_bool(out, expected, comparison);
    fputs("\tex de,hl\n", out);
    fprintf(out, "\tld hl,S%d\n\tpush hl\n", string_id);
    fputs("\tex de,hl\n\tpush hl\n", out);
    mir_machine_emit_symbol_call(out, check_function);
    fputs("\tpop bc\n\tpop bc\n", out);
}

static void mir_emit_ctype_failure(
    FILE *out, int string_id, struct Sym *print_function)
{
    fprintf(out, "\tld hl,S%d\n\tpush hl\n", string_id);
    mir_machine_emit_symbol_call(out, print_function);
    fputs("\tpop bc\n\tpop bc\n\tld hl,1\n\tret\n", out);
}

static void mir_emit_ctype_resize(
    FILE *out, const struct MirCtypeReallocSchedule *plan,
    unsigned long size)
{
    mir_emit_ctype_pointer_load(out);
    fputs("\tex de,hl\n", out);
    fprintf(out, "\tld hl,%lu\n\tpush hl\n\tpush de\n",
            size & 0xffffUL);
    mir_machine_emit_symbol_call(out, plan->resize_function);
    fputs("\tpop bc\n\tpop bc\n", out);
    mir_emit_ctype_pointer_store(out);
}

static void mir_emit_ctype_realloc_schedule(
    FILE *out, const struct MirCtypeReallocSchedule *plan)
{
    int allocation_ok = new_label();
    int grow_ok = new_label();
    int shrink_ok = new_label();
    int success = new_label();
    int check;
    int byte;

    fputs("\tpush hl\n", out);
    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");

    for (check = 0; check < plan->check_count; ++check) {
        const struct MirCtypeCheck *item = &plan->checks[check];

        fprintf(out,
                "\tld hl,S%d\n\tpush hl\n"
                "\tld hl,%lu\n\tpush hl\n",
                item->string_id, item->input & 0xffffUL);
        mir_machine_emit_symbol_call(out, item->value_function);
        fputs("\tpop bc\n", out);
        mir_emit_ctype_compare_bool(
            out, item->expected, item->comparison);
        fputs("\tpush hl\n", out);
        mir_machine_emit_symbol_call(
            out, plan->check_function);
        fputs("\tpop bc\n\tpop bc\n", out);
    }

    fprintf(out, "\tld hl,%lu\n\tpush hl\n",
            plan->allocation_size & 0xffffUL);
    mir_machine_emit_symbol_call(out, plan->allocate_function);
    fputs("\tpop bc\n", out);
    mir_emit_ctype_pointer_store(out);
    fprintf(out, "\tld a,h\n\tor l\n\tjp nz,L%d\n",
            allocation_ok);
    mir_emit_ctype_failure(
        out, plan->allocation_failure_string_id,
        plan->print_function);
    fprintf(out, "L%d:\n", allocation_ok);

    mir_emit_ctype_pointer_load(out);
    fputs("\tex de,hl\n", out);
    fprintf(out, "\tld hl,S%d\n\tpush hl\n\tpush de\n",
            plan->source_string_id);
    mir_machine_emit_symbol_call(out, plan->copy_function);
    fputs("\tpop bc\n\tpop bc\n", out);

    mir_emit_ctype_resize(out, plan, plan->grow_size);
    fprintf(out, "\tld a,h\n\tor l\n\tjp nz,L%d\n",
            grow_ok);
    mir_emit_ctype_failure(
        out, plan->grow_failure_string_id,
        plan->print_function);
    fprintf(out, "L%d:\n", grow_ok);

    mir_emit_ctype_pointer_load(out);
    fputs("\tex de,hl\n", out);
    fprintf(out,
            "\tld hl,S%d\n\tpush hl\n"
            "\tld hl,S%d\n\tpush hl\n\tpush de\n",
            plan->preserve_string_id,
            plan->source_string_id);
    mir_machine_emit_symbol_call(out, plan->compare_function);
    fputs("\tpop bc\n\tpop bc\n", out);
    mir_emit_ctype_compare_bool(out, 0, TOK_EQ);
    fputs("\tpush hl\n", out);
    mir_machine_emit_symbol_call(out, plan->check_function);
    fputs("\tpop bc\n\tpop bc\n", out);

    for (byte = 0; byte < 2; ++byte) {
        mir_emit_ctype_pointer_load(out);
        mir_machine_emit_hl_offset(
            out, plan->store_indices[byte], 0);
        fprintf(out, "\tld (hl),%lu\n",
                plan->stored_values[byte] & 255UL);
    }

    mir_emit_ctype_resize(out, plan, plan->shrink_size);
    fprintf(out, "\tld a,h\n\tor l\n\tjp nz,L%d\n",
            shrink_ok);
    mir_emit_ctype_failure(
        out, plan->shrink_failure_string_id,
        plan->print_function);
    fprintf(out, "L%d:\n", shrink_ok);

    for (byte = 0; byte < 2; ++byte) {
        mir_emit_ctype_pointer_load(out);
        mir_machine_emit_hl_offset(
            out, plan->byte_indices[byte], 0);
        fputs("\tld l,(hl)\n", out);
        if (plan->byte_unsigned[byte])
            fputs("\tld h,0\n", out);
        else
            fputs("\tld a,l\n\trlca\n\tsbc a,a\n\tld h,a\n",
                  out);
        mir_emit_ctype_check_result(
            out, plan->byte_expected[byte], TOK_EQ,
            plan->byte_string_ids[byte],
            plan->check_function);
    }

    mir_emit_ctype_pointer_load(out);
    fputs("\tpush hl\n", out);
    mir_machine_emit_symbol_call(out, plan->free_function);
    fputs("\tpop bc\n", out);

    mir_machine_emit_global_word(
        out, plan->failure_root, plan->failure_offset);
    fputs("\tld a,h\n\tor l\n", out);
    fprintf(out, "\tjp z,L%d\n\tpush hl\n"
            "\tld hl,S%d\n\tpush hl\n",
            success, plan->final_failure_string_id);
    mir_machine_emit_symbol_call(out, plan->print_function);
    fputs("\tpop bc\n\tpop bc\n\tpop bc\n"
          "\tld hl,1\n\tret\n", out);
    fprintf(out, "L%d:\n\tld hl,S%d\n\tpush hl\n",
            success, plan->success_string_id);
    mir_machine_emit_symbol_call(out, plan->print_function);
    fputs("\tpop bc\n\tpop bc\n\tld hl,0\n\tret\n", out);
}

static void mir_emit_context_wide_global_store(
    FILE *out, struct Sym *root, int offset,
    unsigned long value)
{
    mir_machine_emit_float_bits(out, value);
    mir_machine_emit_global_word_store(out, root, offset);
    fputs("\tex de,hl\n", out);
    mir_machine_emit_global_word_store(out, root, offset + 2);
}

static void mir_emit_context_array_init(
    FILE *out, const struct MirContextOpSchedule *plan)
{
    int loop = new_label();

    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    mir_machine_emit_global_address_de(
        out, plan->array_root, plan->array_offset);
    fputs("\tld b,d\n\tld c,e\n"
          "\tld hl,0\n\tld de,0\n\tld a,8\n", out);
    fprintf(out,
            "L%d:\n\tpush af\n"
            "\tld a,l\n\tld (bc),a\n\tinc bc\n"
            "\tld a,h\n\tld (bc),a\n\tinc bc\n"
            "\tld a,e\n\tld (bc),a\n\tinc bc\n"
            "\tld a,d\n\tld (bc),a\n\tinc bc\n"
            "\tpush bc\n\tld bc,34464\n\tadd hl,bc\n"
            "\tex de,hl\n\tld bc,1\n\tadc hl,bc\n"
            "\tex de,hl\n\tpop bc\n"
            "\tpop af\n\tdec a\n\tjp nz,L%d\n",
            loop, loop);
}

static int mir_emit_context_argument(
    FILE *out, const struct MirContextOpArgument *argument)
{
    mir_emit_final_call_constant(
        out, argument->value, argument->width);
    return argument->width / 2;
}

static void mir_emit_context_check(
    FILE *out, const struct MirContextOpCheck *check)
{
    int argument;
    int argument_words = 0;

    fprintf(out, "\tld hl,S%d\n\tpush hl\n",
            check->string_id);
    mir_emit_final_call_constant(
        out, check->expected, check->check_width);
    for (argument = check->argument_count - 1;
         argument >= 0; --argument)
        argument_words += mir_emit_context_argument(
            out, &check->arguments[argument]);
    mir_machine_emit_symbol_call(out, check->value_function);
    mir_emit_final_call_cleanup(out, argument_words);
    if (check->result_width == 2) {
        if (check->result_unsigned)
            fputs("\tld de,0\n", out);
        else
            fputs("\tld a,h\n\trlca\n\tsbc a,a\n"
                  "\tld e,a\n\tld d,a\n", out);
    }
    fputs("\tpush de\n\tpush hl\n", out);
    mir_machine_emit_symbol_call(out, check->check_function);
    mir_emit_final_call_cleanup(out, 5);
}

static void mir_emit_context_op_schedule(
    FILE *out, const struct MirContextOpSchedule *plan)
{
    int failure = new_label();
    int done = new_label();
    int check;

    mir_emit_context_array_init(out, plan);
    for (check = 0; check < 15; ++check)
        mir_emit_context_check(out, &plan->checks[check]);
    mir_emit_context_wide_global_store(
        out, plan->float_roots[0], plan->float_offsets[0],
        plan->float_values[0]);
    mir_emit_context_wide_global_store(
        out, plan->float_roots[1], plan->float_offsets[1],
        plan->float_values[1]);
    for (; check < MIR_CONTEXT_OP_CHECK_COUNT; ++check)
        mir_emit_context_check(out, &plan->checks[check]);

    mir_machine_emit_global_word(
        out, plan->failure_root, plan->failure_offset);
    fputs("\tld a,h\n\tor l\n", out);
    fprintf(out, "\tjp nz,L%d\n\tld hl,S%d\n\tpush hl\n",
            failure, plan->success_string_id);
    mir_machine_emit_symbol_call(out, plan->print_function);
    fputs("\tpop bc\n", out);
    fprintf(out, "\tjp L%d\nL%d:\n",
            done, failure);
    mir_machine_emit_global_word(
        out, plan->failure_root, plan->failure_offset);
    fprintf(out, "\tpush hl\n\tld hl,S%d\n\tpush hl\n",
            plan->failure_string_id);
    mir_machine_emit_symbol_call(out, plan->print_function);
    fputs("\tpop bc\n\tpop bc\n", out);
    fprintf(out, "L%d:\n", done);
    mir_machine_emit_global_word(
        out, plan->failure_root, plan->failure_offset);
    fputs("\tld a,h\n\tor l\n\tld hl,0\n\tret z\n"
          "\tinc hl\n\tret\n", out);
}

static void mir_emit_local_identity_array_result(
    FILE *out, const struct MirLocalIdentityArrayResult *plan)
{
    fputs("\tpush ix\n\tld ix,0\n\tadd ix,sp\n", out);
    fprintf(out, "\tld hl,%d\n\tadd hl,sp\n\tld sp,hl\n",
            plan->array_offset);
    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    fputs("\tpush ix\n\tpop hl\n", out);
    mir_machine_emit_hl_offset(out, plan->array_offset, 0);
    mir_machine_emit_global_word_store(
        out, plan->escaped_pointer, plan->escaped_pointer_offset);
    fprintf(out,
            "\tld hl,%d\n\tld sp,ix\n\tpop ix\n\tret\n",
            plan->result);
}

static void mir_emit_constant_function(FILE *out, int result)
{
    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    fprintf(out, "\tld hl,%d\n\tret\n", result);
}

static void mir_emit_constant_result_switch(
    FILE *out, const struct MirConstantResultSwitch *plan)
{
    int default_label = new_label();
    int table_label = new_label();
    int width = plan->maximum_case - plan->minimum_case + 1;
    int value;

    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    fprintf(out,
            "\tld hl,%d\n\tadd hl,sp\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tex de,hl\n",
            plan->parameter_stack_offset);
    if (plan->minimum_case != 0)
        fprintf(out, "\tld de,%d\n\tor a\n\tsbc hl,de\n",
                plan->minimum_case);
    fprintf(out,
            "\tld a,h\n\tor a\n\tjp nz,L%d\n"
            "\tld a,l\n\tcp %d\n\tjp nc,L%d\n"
            "\tadd hl,hl\n\tld de,L%d\n\tadd hl,de\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
            "\tex de,hl\n\tret\n"
            "L%d:\n",
            default_label, width, default_label,
            table_label, table_label);
    for (value = 0; value < width; ++value)
        fprintf(out, "\tdw %d\n", plan->results[value]);
    fprintf(out, "L%d:\n\tld hl,%d\n\tret\n",
            default_label, plan->default_result);
}

static void mir_emit_vla_pointer_element_switch(
    FILE *out, const struct MirVlaPointerElementSwitch *plan)
{
    int default_label = new_label();
    int value_ready = new_label();

    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    fprintf(out,
            "\tld hl,%d\n\tadd hl,sp\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
            "\tld hl,%d\n\tor a\n\tsbc hl,de\n"
            "\tjp nz,L%d\n"
            "\tld de,%d\n\tjp L%d\n"
            "L%d:\n\tld de,%d\n"
            "L%d:\n"
            "\tld hl,%d\n\tadd hl,sp\n"
            "\tld c,(hl)\n\tinc hl\n\tld b,(hl)\n"
            "\tld h,b\n\tld l,c\n",
            plan->rows_stack_offset, plan->compare_value,
            default_label, plan->case_value, value_ready,
            default_label, plan->default_value, value_ready,
            plan->pointer_stack_offset);
    mir_machine_emit_hl_offset(out, plan->element_offset, 0);
    fputs("\tld (hl),e\n\tinc hl\n\tld (hl),d\n"
          "\tld d,(hl)\n\tdec hl\n\tld e,(hl)\n"
          "\tex de,hl\n\tret\n", out);
}

static void mir_emit_string_result_switch(
    FILE *out, const struct MirStringResultSwitch *plan)
{
    int default_label = new_label();
    int table_label = new_label();
    int width = plan->maximum_case -
                plan->minimum_case + 1;
    int value;

    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    fprintf(out,
            "\tld hl,%d\n\tadd hl,sp\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
            "\tex de,hl\n",
            plan->parameter_stack_offset);
    if (plan->minimum_case != 0)
        fprintf(out,
                "\tld de,%d\n\tor a\n\tsbc hl,de\n",
                plan->minimum_case);
    fprintf(out,
            "\tld a,h\n\tor a\n\tjp nz,L%d\n"
            "\tld a,l\n\tcp %d\n\tjp nc,L%d\n"
            "\tadd hl,hl\n\tld de,L%d\n\tadd hl,de\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
            "\tex de,hl\n\tret\nL%d:\n",
            default_label, width, default_label,
            table_label, table_label);
    for (value = 0; value < width; ++value)
        if (plan->strings[value] >= 0)
            fprintf(out, "\tdw S%d\n",
                    plan->strings[value]);
        else
            fputs("\tdw 0\n", out);
    if (plan->default_string >= 0)
        fprintf(out,
                "L%d:\n\tld hl,S%d\n\tret\n",
                default_label,
                plan->default_string);
    else
        fprintf(out,
                "L%d:\n\tld hl,0\n\tret\n",
                default_label);
}

static void mir_emit_local_byte_fill_sum_print(
    FILE *out, const struct MirLocalByteFillSumPrint *plan)
{
    int loop = new_label();

    fputs("\tpush ix\n\tld ix,0\n\tadd ix,sp\n", out);
    fprintf(out, "\tld hl,%d\n\tadd hl,sp\n\tld sp,hl\n",
            plan->buffer_offset);
    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    if (plan->fill_has_value)
        fprintf(out, "\tld hl,%d\n\tpush hl\n",
                plan->fill_value);
    fputs("\tpush ix\n\tpop hl\n", out);
    fprintf(out, "\tld de,%d\n\tadd hl,de\n\tpush hl\n",
            plan->buffer_offset);
    mir_machine_emit_symbol_call(out, plan->fill_function);
    fputs("\tpop bc\n", out);
    if (plan->fill_has_value)
        fputs("\tpop bc\n", out);
    fputs("\tpush ix\n\tpop hl\n", out);
    fprintf(out,
            "\tld de,%d\n\tadd hl,de\n\tld de,0\n\tld b,%d\n"
            "L%d:\n",
            plan->buffer_offset, plan->count, loop);
    if (plan->element_is_unsigned) {
        fputs("\tld a,(hl)\n\tinc hl\n\tadd a,e\n\tld e,a\n"
              "\tld a,0\n\tadc a,d\n\tld d,a\n", out);
    } else {
        int sign_done = new_label();

        fprintf(out,
                "\tld c,(hl)\n\tinc hl\n"
                "\tld a,c\n\tadd a,e\n\tld e,a\n"
                "\tld a,0\n\tadc a,d\n"
                "\tbit 7,c\n\tjp z,L%d\n\tdec a\n"
                "L%d:\n\tld d,a\n",
                sign_done, sign_done);
    }
    fprintf(out,
            "\tdjnz L%d\n\tex de,hl\n\tpush hl\n"
            "\tld hl,S%d\n\tpush hl\n",
            loop, plan->string_id);
    mir_machine_emit_symbol_call(out, plan->print_function);
    fputs("\tpop bc\n\tpop bc\n\tld hl,0\n"
          "\tld sp,ix\n\tpop ix\n\tret\n", out);
}

static void mir_fixed_wrapper_load_pointer(
    FILE *out, const struct MirFixedWrapperInit *plan,
    int offset)
{
    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n",
            plan->pointer_stack_offset + 2,
            plan->pointer_stack_offset + 3);
    mir_machine_emit_hl_offset(out, offset, 0);
}

static void mir_fixed_wrapper_load_word(
    FILE *out, const struct MirFixedWrapperInit *plan,
    int constant)
{
    fprintf(out,
            "\tld e,(ix%+d)\n\tld d,(ix%+d)\n"
            "\tld a,e\n\tadd a,%d\n\tld e,a\n"
            "\tld a,d\n\tadc a,%d\n\tld d,a\n",
            plan->base_stack_offset + 2,
            plan->base_stack_offset + 3,
            constant & 255, (constant >> 8) & 255);
}

static void mir_fixed_wrapper_store_word_loop(
    FILE *out, const struct MirFixedWrapperInit *plan,
    int constant, int count)
{
    mir_fixed_wrapper_load_word(out, plan, constant);
    if (count == 1) {
        fputs("\tld (hl),e\n\tinc hl\n"
              "\tld (hl),d\n\tinc hl\n", out);
        return;
    }
    {
        int loop = new_label();

        fprintf(out,
                "\tld b,%d\n"
                "L%d:\n\tld (hl),e\n\tinc hl\n"
                "\tld (hl),d\n\tinc hl\n\tinc de\n"
                "\tdjnz L%d\n",
                count, loop, loop);
    }
}

static void mir_fixed_wrapper_store_char_loop(
    FILE *out, const struct MirFixedWrapperInit *plan,
    int constant, int count)
{
    fprintf(out,
            "\tld a,(ix%+d)\n\tadd a,%d\n\tand 127\n",
            plan->base_stack_offset + 2,
            constant & 255);
    if (count == 1) {
        fputs("\tld (hl),a\n\tinc hl\n", out);
        return;
    }
    {
        int loop = new_label();

        fprintf(out,
                "\tld b,%d\n"
                "L%d:\n\tld (hl),a\n\tinc hl\n"
                "\tinc a\n\tand 127\n\tdjnz L%d\n",
                count, loop, loop);
    }
}

static void mir_fixed_wrapper_load_long(
    FILE *out, int constant)
{
    fprintf(out,
            "\tld c,(ix-4)\n\tld b,(ix-3)\n"
            "\tld e,(ix-2)\n\tld d,(ix-1)\n"
            "\tld a,c\n\tadd a,%d\n\tld c,a\n"
            "\tld a,b\n\tadc a,%d\n\tld b,a\n"
            "\tld a,e\n\tadc a,0\n\tld e,a\n"
            "\tld a,d\n\tadc a,0\n\tld d,a\n",
            constant & 255, (constant >> 8) & 255);
}

static void mir_fixed_wrapper_store_long_loop(
    FILE *out, int constant, int count)
{
    int loop = new_label();
    int no_high_increment = new_label();

    mir_fixed_wrapper_load_long(out, constant);
    if (count > 1)
        fprintf(out, "\tld (ix-5),%d\n", count);
    fprintf(out,
            "L%d:\n\tld (hl),c\n\tinc hl\n"
            "\tld (hl),b\n\tinc hl\n"
            "\tld (hl),e\n\tinc hl\n"
            "\tld (hl),d\n\tinc hl\n",
            loop);
    if (count > 1) {
        fprintf(out,
                "\tinc bc\n\tld a,b\n\tor c\n"
                "\tjp nz,L%d\n\tinc de\n"
                "L%d:\n\tdec (ix-5)\n\tjp nz,L%d\n",
                no_high_increment, no_high_increment, loop);
    }
}

static void mir_fixed_wrapper_store_pointer(
    FILE *out, const struct MirFixedWrapperInit *plan,
    int destination_offset, int source_offset)
{
    mir_fixed_wrapper_load_pointer(
        out, plan, destination_offset);
    fprintf(out,
            "\tld e,(ix%+d)\n\tld d,(ix%+d)\n",
            plan->pointer_stack_offset + 2,
            plan->pointer_stack_offset + 3);
    if (source_offset != 0)
        fprintf(out,
                "\tld a,e\n\tadd a,%d\n\tld e,a\n"
                "\tld a,d\n\tadc a,%d\n\tld d,a\n",
                source_offset & 255,
                (source_offset >> 8) & 255);
    fputs("\tld (hl),e\n\tinc hl\n\tld (hl),d\n", out);
}

static void mir_emit_fixed_wrapper_init(
    FILE *out, const struct MirFixedWrapperInit *plan)
{
    int node;
    int leaf;
    int row;
    int index;

    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    fputs("\tpush ix\n\tld ix,0\n\tadd ix,sp\n"
          "\tld hl,-5\n\tadd hl,sp\n\tld sp,hl\n", out);
    fprintf(out,
            "\tld c,(ix%+d)\n\tld b,(ix%+d)\n"
            "\tld hl,1000\n",
            plan->base_stack_offset + 2,
            plan->base_stack_offset + 3);
    mir_emit_runtime_call(out, "__m1s");
    fputs("\tld (ix-4),l\n\tld (ix-3),h\n"
          "\tld (ix-2),e\n\tld (ix-1),d\n", out);

    for (node = 0; node < plan->node_count; ++node) {
        int node_offset = node * plan->node_stride;

        for (leaf = 0;
             leaf < plan->leaf_count; ++leaf) {
            int leaf_offset =
                node_offset + leaf * plan->leaf_stride;

            mir_fixed_wrapper_load_pointer(
                out, plan, leaf_offset);
            mir_fixed_wrapper_store_word_loop(
                out, plan,
                node * 100 + leaf * 10 + 1, 1);
            mir_fixed_wrapper_store_word_loop(
                out, plan,
                node * 100 + leaf * 10 + 20,
                plan->element_count);
            mir_fixed_wrapper_store_char_loop(
                out, plan,
                node * 20 + leaf * 3 + 2, 1);
            mir_fixed_wrapper_store_char_loop(
                out, plan,
                node * 20 + leaf * 5 + 30,
                plan->element_count);
            mir_fixed_wrapper_store_long_loop(
                out, node * 100 + leaf * 10 + 3, 1);
            mir_fixed_wrapper_store_long_loop(
                out, node * 100 + leaf * 10 + 40,
                plan->element_count);
        }
        for (row = 0; row < plan->row_count; ++row) {
            mir_fixed_wrapper_load_pointer(
                out, plan,
                node_offset + plan->matrix_offset +
                    row * plan->column_count * 2);
            mir_fixed_wrapper_store_word_loop(
                out, plan,
                node * 100 + row * 10 + 200,
                plan->column_count);
            mir_fixed_wrapper_load_pointer(
                out, plan,
                node_offset + plan->char_matrix_offset +
                    row * plan->column_count);
            mir_fixed_wrapper_store_char_loop(
                out, plan,
                node * 20 + row * 5 + 60,
                plan->column_count);
            mir_fixed_wrapper_load_pointer(
                out, plan,
                node_offset + plan->long_matrix_offset +
                    row * plan->column_count * 4);
            mir_fixed_wrapper_store_long_loop(
                out, node * 100 + row * 10 + 300,
                plan->column_count);
        }
        mir_fixed_wrapper_store_pointer(
            out, plan,
            node_offset + plan->leaf_pointer_offset,
            node_offset + plan->leaf_stride);
        mir_fixed_wrapper_store_pointer(
            out, plan,
            node_offset + plan->int_pointer_offset,
            node_offset + plan->matrix_offset +
                plan->column_count * 2);
        mir_fixed_wrapper_store_pointer(
            out, plan,
            node_offset + plan->char_pointer_offset,
            node_offset + plan->char_matrix_offset +
                plan->column_count);
        mir_fixed_wrapper_store_pointer(
            out, plan,
            node_offset + plan->long_pointer_offset,
            node_offset + plan->long_matrix_offset +
                plan->column_count * 4);
    }
    mir_fixed_wrapper_store_pointer(
        out, plan, plan->wrapper_node_pointer_offset, 0);
    for (index = 0; index < plan->leaf_count; ++index) {
        int source_offset =
            (index & 1) * plan->node_stride +
            index * plan->leaf_stride;

        mir_fixed_wrapper_store_pointer(
            out, plan,
            plan->wrapper_leaf_pointers_offset + index * 2,
            source_offset);
    }
    for (index = 0; index < plan->element_count; ++index) {
        int node_offset =
            (index & 1) * plan->node_stride;
        int leaf_offset =
            node_offset +
            (index % plan->leaf_count) * plan->leaf_stride;

        mir_fixed_wrapper_store_pointer(
            out, plan,
            plan->wrapper_int_pointers_offset + index * 2,
            leaf_offset + plan->array_offset +
                (index & 3) * 2);
        mir_fixed_wrapper_store_pointer(
            out, plan,
            plan->wrapper_char_pointers_offset + index * 2,
            leaf_offset + plan->char_array_offset +
                (index & 3));
        mir_fixed_wrapper_store_pointer(
            out, plan,
            plan->wrapper_long_pointers_offset + index * 2,
            leaf_offset + plan->long_array_offset +
                (index & 3) * 4);
    }
    fputs("\tld sp,ix\n\tpop ix\n\tret\n", out);
}

static void mir_emit_inline_fold_check(
    FILE *out, const struct MirInlineFoldCheck *plan)
{
    const char *memory_name =
        asm_name_for(sym_asm_name(plan->memory));
    int fill_loop = new_label();
    int sum_loop = new_label();

    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    fputs("\tpush ix\n\tld ix,0\n\tadd ix,sp\n"
          "\tdec sp\n\tdec sp\n"
          "\tld hl,0\n", out);
    mir_machine_emit_global_word_store(
        out, plan->counter, 0);
    fprintf(out,
            "\tld (ix-2),0\n\tld (ix-1),0\n"
            "L%d:\n",
            fill_loop);
    mir_machine_emit_symbol_call(
        out, plan->next_function);
    fprintf(out,
            "\tld c,l\n\tld b,h\n"
            "\tld l,(ix-2)\n\tld h,0\n\tadd hl,hl\n"
            "\tld de,%s\n\tadd hl,de\n"
            "\tld (hl),c\n\tinc hl\n\tld (hl),b\n"
            "\tinc (ix-2)\n\tld a,(ix-2)\n\tcp %d\n"
            "\tjp nz,L%d\n"
            "\tld hl,%s%+d\n\tld (hl),%d\n"
            "\tld hl,%s\n\tld de,0\n"
            "\tld (ix-2),%d\n"
            "L%d:\n"
            "\tld c,(hl)\n\tinc hl\n"
            "\tld b,(hl)\n\tinc hl\n"
            "\tex de,hl\n\tadd hl,bc\n\tex de,hl\n"
            "\tdec (ix-2)\n\tjp nz,L%d\n",
            memory_name, plan->count, fill_loop,
            memory_name, plan->byte_base + plan->byte_index,
            plan->byte_value & 255,
            memory_name, plan->count,
            sum_loop, sum_loop);
    fprintf(out,
            "\tld hl,%s%+d\n\tld l,(hl)\n\tld h,0\n"
            "\tadd hl,de\n\tld sp,ix\n\tpop ix\n\tret\n",
            memory_name,
            plan->byte_base + plan->byte_index);
}

static void mir_fixed_call_runner_failure(
    FILE *out, const struct MirFixedCallCheckRunner *plan,
    int check, int next_label)
{
    int increment_done = new_label();

    fprintf(out, "\tjp z,L%d\n\tld hl,S%d\n\tpush hl\n",
            next_label, plan->failure_string_ids[check]);
    mir_machine_emit_symbol_call(
        out, plan->print_function);
    fprintf(out,
            "\tpop bc\n\tinc (ix-2)\n"
            "\tjp nz,L%d\n\tinc (ix-1)\n"
            "L%d:\nL%d:\n",
            increment_done, increment_done, next_label);
}

static void mir_fixed_call_runner_word_check(
    FILE *out, const struct MirFixedCallCheckRunner *plan,
    int check, int expected)
{
    int next_label = new_label();

    fprintf(out,
            "\tld de,%d\n\tor a\n\tsbc hl,de\n",
            expected);
    mir_fixed_call_runner_failure(
        out, plan, check, next_label);
}

static void mir_fixed_call_runner_push_long(
    FILE *out, unsigned long value)
{
    fprintf(out,
            "\tld hl,%lu\n\tpush hl\n"
            "\tld hl,%lu\n\tpush hl\n",
            (value >> 16) & 0xffffUL,
            value & 0xffffUL);
}

static void mir_emit_fixed_call_check_runner(
    FILE *out, const struct MirFixedCallCheckRunner *plan)
{
    int success = new_label();
    int done = new_label();
    int next_label;
    int argument;

    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    fputs("\tpush ix\n\tld ix,0\n\tadd ix,sp\n"
          "\tld hl,-6\n\tadd hl,sp\n\tld sp,hl\n"
          "\tld (ix-2),0\n\tld (ix-1),0\n", out);
    for (argument = 0; argument < 4; ++argument)
        fprintf(out, "\tld (ix%+d),%d\n",
                -6 + argument,
                plan->array_values[argument] & 255);

    for (argument = 1; argument >= 0; --argument)
        fprintf(out, "\tld hl,%d\n\tpush hl\n",
                plan->binary_arguments[0][argument]);
    mir_machine_emit_symbol_call(
        out, plan->functions[0]);
    fputs("\tpop bc\n\tpop bc\n", out);
    mir_fixed_call_runner_word_check(
        out, plan, 0, plan->expected_words[0]);

    for (argument = 1; argument >= 0; --argument)
        fprintf(out, "\tld hl,%d\n\tpush hl\n",
                plan->binary_arguments[1][argument]);
    mir_machine_emit_symbol_call(
        out, plan->functions[1]);
    fputs("\tpop bc\n\tpop bc\n", out);
    mir_fixed_call_runner_word_check(
        out, plan, 1, plan->expected_words[1]);

    fprintf(out,
            "\tld hl,%d\n\tpush hl\n"
            "\tpush ix\n\tpop hl\n"
            "\tld de,-6\n\tadd hl,de\n\tpush hl\n",
            plan->pointer_count);
    mir_machine_emit_symbol_call(
        out, plan->functions[2]);
    fputs("\tpop bc\n\tpop bc\n", out);
    mir_fixed_call_runner_word_check(
        out, plan, 2, plan->expected_words[2]);

    mir_fixed_call_runner_push_long(
        out, plan->long_arguments[1]);
    fprintf(out, "\tld hl,%d\n\tpush hl\n",
            plan->long_middle_argument);
    mir_fixed_call_runner_push_long(
        out, plan->long_arguments[0]);
    mir_machine_emit_symbol_call(
        out, plan->functions[3]);
    fputs("\tpop bc\n\tpop bc\n\tpop bc\n"
          "\tpop bc\n\tpop bc\n", out);
    {
        int failure_label = new_label();
        int increment_done = new_label();

        next_label = new_label();
        fprintf(out,
                "\tld bc,%lu\n\tor a\n\tsbc hl,bc\n"
                "\tjp nz,L%d\n\tex de,hl\n"
                "\tld bc,%lu\n\tor a\n\tsbc hl,bc\n"
                "\tjp z,L%d\n"
                "L%d:\n\tld hl,S%d\n\tpush hl\n",
                plan->expected_long & 0xffffUL,
                failure_label,
                (plan->expected_long >> 16) & 0xffffUL,
                next_label, failure_label,
                plan->failure_string_ids[3]);
        mir_machine_emit_symbol_call(
            out, plan->print_function);
        fprintf(out,
                "\tpop bc\n\tinc (ix-2)\n"
                "\tjp nz,L%d\n\tinc (ix-1)\n"
                "L%d:\nL%d:\n",
                increment_done, increment_done, next_label);
    }

    for (argument = 2; argument >= 0; --argument)
        fprintf(out, "\tld hl,%d\n\tpush hl\n",
                plan->byte_arguments[argument]);
    mir_machine_emit_symbol_call(
        out, plan->functions[4]);
    fputs("\tpop bc\n\tpop bc\n\tpop bc\n", out);
    mir_fixed_call_runner_word_check(
        out, plan, 4, plan->expected_words[3]);

    fputs("\tld l,(ix-2)\n\tld h,(ix-1)\n"
          "\tld a,h\n\tor l\n", out);
    fprintf(out,
            "\tjp z,L%d\n\tpush hl\n"
            "\tld hl,S%d\n\tpush hl\n",
            success, plan->summary_string_id);
    mir_machine_emit_symbol_call(
        out, plan->print_function);
    fprintf(out,
            "\tpop bc\n\tpop bc\n\tld hl,1\n"
            "\tjp L%d\n"
            "L%d:\n\tld hl,S%d\n\tpush hl\n",
            done, success, plan->success_string_id);
    mir_machine_emit_symbol_call(
        out, plan->print_function);
    fprintf(out,
            "\tpop bc\n\tld hl,0\n"
            "L%d:\n\tld sp,ix\n\tpop ix\n\tret\n",
            done);
}

static void mir_emit_deterministic_init_check(
    FILE *out, const struct MirDeterministicInitCheck *plan)
{
    int check;
    int bit = 1;

    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    for (check = 0; check < plan->check_count; ++check) {
        fputs("\tld hl,1\n\tpush hl\n", out);
        fprintf(out, "\tld hl,%d\n\tpush hl\n",
                plan->check_ids[check]);
        mir_machine_emit_symbol_call(
            out, plan->check_function);
        fputs("\tpop bc\n\tpop bc\n", out);
    }
    fprintf(out,
            "\tld hl,%d\n\tadd hl,sp\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
            "\tex de,hl\n",
            plan->parameter_stack_offset);
    if (plan->return_multiplier != 1) {
        fputs("\tld c,l\n\tld b,h\n\tld hl,0\n", out);
        while (bit <= plan->return_multiplier / 2)
            bit <<= 1;
        for (; bit != 0; bit >>= 1) {
            fputs("\tadd hl,hl\n", out);
            if ((plan->return_multiplier & bit) != 0)
                fputs("\tadd hl,bc\n", out);
        }
    }
    fprintf(out,
            "\tld de,%d\n\tadd hl,de\n\tret\n",
            plan->return_addend);
}

static void mir_fixed_index_runner_failure(
    FILE *out, int next_label)
{
    int increment_done = new_label();

    fprintf(out,
            "\tjp z,L%d\n\tinc (ix-2)\n"
            "\tjp nz,L%d\n\tinc (ix-1)\n"
            "L%d:\nL%d:\n",
            next_label, increment_done,
            increment_done, next_label);
}

static void mir_fixed_index_runner_word_check(
    FILE *out, int expected)
{
    int next_label = new_label();

    fprintf(out,
            "\tld de,%d\n\tor a\n\tsbc hl,de\n",
            expected);
    mir_fixed_index_runner_failure(out, next_label);
}

static void mir_fixed_index_runner_wide_check(
    FILE *out, unsigned long expected)
{
    int failure = new_label();
    int next_label = new_label();

    fprintf(out,
            "\tld bc,%lu\n\tor a\n\tsbc hl,bc\n"
            "\tjp nz,L%d\n\tex de,hl\n"
            "\tld bc,%lu\n\tor a\n\tsbc hl,bc\n"
            "\tjp z,L%d\n"
            "L%d:\n",
            expected & 0xffffUL, failure,
            (expected >> 16) & 0xffffUL,
            next_label, failure);
    mir_fixed_index_runner_failure(out, next_label);
}

static void mir_emit_fixed_index_call_runner(
    FILE *out, const struct MirFixedIndexCallRunner *plan)
{
    static const int int_offsets[4] = {-50, -48, -46, -44};
    static const int long_offsets[4] = {-42, -38, -34, -30};
    static const int pair_offsets[6] = {
        -26, -22, -18, -14, -10, -6
    };
    static const int pointer_offsets[3] = {-50, -42, -26};
    int success = new_label();
    int done = new_label();
    int item;

    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    fputs("\tpush ix\n\tld ix,0\n\tadd ix,sp\n"
          "\tld hl,-50\n\tadd hl,sp\n\tld sp,hl\n"
          "\tld (ix-2),0\n\tld (ix-1),0\n", out);
    for (item = 0; item < 4; ++item) {
        fprintf(out,
                "\tld hl,%d\n"
                "\tld (ix%+d),l\n\tld (ix%+d),h\n",
                plan->int_values[item],
                int_offsets[item], int_offsets[item] + 1);
        mir_machine_emit_float_bits(
            out, plan->long_values[item]);
        mir_machine_emit_ix_wide_store(
            out, long_offsets[item]);
    }
    for (item = 0; item < 6; ++item) {
        mir_machine_emit_float_bits(
            out, plan->pair_values[item]);
        mir_machine_emit_ix_wide_store(
            out, pair_offsets[item]);
    }

    for (item = 0; item < 2; ++item) {
        fprintf(out, "\tld hl,%d\n\tpush hl\n",
                plan->scalar_arguments[item]);
        mir_machine_emit_symbol_call(
            out, plan->functions[item]);
        fputs("\tpop bc\n", out);
        mir_fixed_index_runner_word_check(
            out, plan->expected_words[item]);
    }
    for (item = 0; item < 3; ++item) {
        fprintf(out,
                "\tld hl,%d\n\tpush hl\n"
                "\tpush ix\n\tpop hl\n"
                "\tld de,%d\n\tadd hl,de\n\tpush hl\n",
                plan->pointer_indices[item],
                pointer_offsets[item]);
        mir_machine_emit_symbol_call(
            out, plan->functions[item + 2]);
        fputs("\tpop bc\n\tpop bc\n", out);
        if (item == 0)
            mir_fixed_index_runner_word_check(
                out, plan->expected_words[2]);
        else
            mir_fixed_index_runner_wide_check(
                out, plan->expected_longs[item - 1]);
    }

    fputs("\tld l,(ix-2)\n\tld h,(ix-1)\n"
          "\tld a,h\n\tor l\n", out);
    fprintf(out,
            "\tjp z,L%d\n\tpush hl\n"
            "\tld hl,S%d\n\tpush hl\n",
            success, plan->failure_string_id);
    mir_machine_emit_symbol_call(
        out, plan->print_function);
    fprintf(out,
            "\tpop bc\n\tpop bc\n\tld hl,1\n"
            "\tjp L%d\n"
            "L%d:\n\tld hl,S%d\n\tpush hl\n",
            done, success, plan->success_string_id);
    mir_machine_emit_symbol_call(
        out, plan->print_function);
    fprintf(out,
            "\tpop bc\n\tld hl,0\n"
            "L%d:\n\tld sp,ix\n\tpop ix\n\tret\n",
            done);
}

static void mir_local_array_struct_store(
    FILE *out, int offset, int width, unsigned long value)
{
    if (width == 1) {
        fprintf(out, "\tld (ix%+d),%lu\n",
                offset, value & 0xffUL);
    } else if (width == 2) {
        fprintf(out,
                "\tld hl,%lu\n"
                "\tld (ix%+d),l\n\tld (ix%+d),h\n",
                value & 0xffffUL, offset, offset + 1);
    } else {
        mir_machine_emit_float_bits(out, value);
        mir_machine_emit_ix_wide_store(out, offset);
    }
}

static void mir_local_array_struct_address(FILE *out, int offset)
{
    fputs("\tpush ix\n\tpop hl\n", out);
    mir_machine_emit_hl_offset(out, offset, 0);
}

static void mir_local_array_struct_normalize(
    FILE *out, int width, int is_unsigned)
{
    if (width == 4)
        return;
    if (width == 1) {
        if (is_unsigned)
            fputs("\tld h,0\n\tld de,0\n", out);
        else
            fputs("\tld a,l\n\trlca\n\tsbc a,a\n"
                  "\tld h,a\n\tld d,a\n\tld e,a\n", out);
        return;
    }
    if (is_unsigned)
        fputs("\tld de,0\n", out);
    else
        fputs("\tld a,h\n\trlca\n\tsbc a,a\n"
              "\tld d,a\n\tld e,a\n", out);
}

static void mir_local_array_struct_load(
    FILE *out, int offset, int width, int is_unsigned)
{
    if (width == 1)
        fprintf(out, "\tld l,(ix%+d)\n", offset);
    else if (width == 2)
        fprintf(out,
                "\tld l,(ix%+d)\n\tld h,(ix%+d)\n",
                offset, offset + 1);
    else
        mir_machine_emit_ix_wide_load(out, offset);
    mir_local_array_struct_normalize(out, width, is_unsigned);
}

static void mir_local_array_struct_check(
    FILE *out, const struct MirLocalArrayStructChecks *plan,
    int check, int is_unsigned)
{
    fputs("\texx\n", out);
    mir_machine_emit_float_bits(
        out, plan->expected_values[check]);
    fputs("\tpush de\n\tpush hl\n\texx\n"
          "\tpush de\n\tpush hl\n", out);
    fprintf(out, "\tld hl,S%d\n\tpush hl\n",
            plan->string_ids[check]);
    mir_machine_emit_symbol_call(
        out, plan->check_functions[is_unsigned]);
    fputs("\tpop bc\n\tpop bc\n\tpop bc\n"
          "\tpop bc\n\tpop bc\n", out);
}

static void mir_local_array_struct_pointer_call(
    FILE *out, struct Sym *function, int offset,
    int width, int is_unsigned, int has_index, int index)
{
    if (has_index)
        fprintf(out, "\tld hl,%d\n\tpush hl\n", index);
    mir_local_array_struct_address(out, offset);
    fputs("\tpush hl\n", out);
    mir_machine_emit_symbol_call(out, function);
    fputs("\tpop bc\n", out);
    if (has_index)
        fputs("\tpop bc\n", out);
    mir_local_array_struct_normalize(out, width, is_unsigned);
}

static void mir_emit_local_array_struct_checks(
    FILE *out, const struct MirLocalArrayStructChecks *plan)
{
    static const int widths[3] = {1, 2, 4};
    static const int unsigned_kinds[3] = {1, 0, 0};
    static const int array_offsets[3] = {-70, -66, -58};
    static const int member_offsets[6] = {0, 1, 2, 4, 6, 10};
    static const int member_widths[6] = {1, 1, 2, 2, 4, 4};
    static const int member_unsigned[6] = {1, 0, 0, 1, 0, 1};
    static const int array_member_offsets[3] = {14, 18, 26};
    const int struct_offset = -42;
    int check = 0;
    int group;
    int item;

    fputs("\tpush ix\n\tld ix,0\n\tadd ix,sp\n"
          "\tld hl,-70\n\tadd hl,sp\n\tld sp,hl\n", out);
    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    for (group = 0; group < 3; ++group)
        for (item = 0; item < 4; ++item)
            mir_local_array_struct_store(
                out, array_offsets[group] + item * widths[group],
                widths[group], plan->array_values[group][item]);
    for (group = 0; group < 3; ++group) {
        int value_offset = array_offsets[group] +
            plan->array_indices[group] * widths[group];

        mir_local_array_struct_pointer_call(
            out, plan->array_functions[group],
            array_offsets[group], widths[group],
            unsigned_kinds[group], 1,
            plan->array_indices[group]);
        mir_local_array_struct_check(
            out, plan, check++, unsigned_kinds[group]);
        mir_local_array_struct_load(
            out, value_offset, widths[group],
            unsigned_kinds[group]);
        mir_local_array_struct_check(
            out, plan, check++, unsigned_kinds[group]);
    }

    for (item = 0; item < 6; ++item)
        mir_local_array_struct_store(
            out, struct_offset + member_offsets[item],
            member_widths[item], plan->scalar_values[item]);
    for (item = 0; item < 6; ++item) {
        mir_local_array_struct_pointer_call(
            out, plan->scalar_functions[item],
            struct_offset + member_offsets[item],
            member_widths[item], member_unsigned[item],
            0, 0);
        mir_local_array_struct_check(
            out, plan, check++, member_unsigned[item]);
        mir_local_array_struct_load(
            out, struct_offset + member_offsets[item],
            member_widths[item], member_unsigned[item]);
        mir_local_array_struct_check(
            out, plan, check++, member_unsigned[item]);
    }

    for (group = 0; group < 3; ++group)
        for (item = 0; item < 4; ++item)
            mir_local_array_struct_store(
                out, struct_offset + array_member_offsets[group] +
                    item * widths[group],
                widths[group],
                plan->member_array_values[group][item]);
    for (group = 0; group < 3; ++group) {
        int base = struct_offset + array_member_offsets[group];
        int value_offset = base +
            plan->member_array_indices[group] * widths[group];

        mir_local_array_struct_pointer_call(
            out, plan->array_functions[group], base,
            widths[group], unsigned_kinds[group], 1,
            plan->member_array_indices[group]);
        mir_local_array_struct_check(
            out, plan, check++, unsigned_kinds[group]);
        mir_local_array_struct_load(
            out, value_offset, widths[group],
            unsigned_kinds[group]);
        mir_local_array_struct_check(
            out, plan, check++, unsigned_kinds[group]);
    }
    fputs("\tld sp,ix\n\tpop ix\n\tret\n", out);
}

static void mir_alias_mix_emit_address(
    FILE *out, const struct MirAliasMixAddress *address)
{
    if (address->indirect) {
        mir_machine_emit_global_word(
            out, address->root, address->root_offset);
        mir_machine_emit_hl_offset(
            out, address->pointee_offset, 0);
    } else {
        mir_machine_emit_global_address_hl(
            out, address->root, address->root_offset);
    }
}

static void mir_alias_mix_emit_store(
    FILE *out, const struct MirAliasMixStore *store)
{
    int byte;

    mir_alias_mix_emit_address(out, &store->address);
    for (byte = 0; byte < store->width; ++byte) {
        fprintf(out, "\tld (hl),%lu\n",
                (store->value >> (byte * 8)) & 255UL);
        if (byte + 1 < store->width)
            fputs("\tinc hl\n", out);
    }
}

static void mir_alias_mix_emit_check(
    FILE *out, const struct MirAliasMixCheck *check)
{
    int cleanup;

    mir_alias_mix_emit_address(out, &check->address);
    if (check->width == 1) {
        fputs("\tld a,(hl)\n\tld l,a\n", out);
        if (check->is_unsigned)
            fputs("\tld h,0\n", out);
        else
            fputs("\trlca\n\tsbc a,a\n\tld h,a\n", out);
        fputs("\tld d,h\n\tld e,l\n", out);
    } else if (check->width == 2) {
        fputs("\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n", out);
    } else {
        fputs("\tld c,(hl)\n\tinc hl\n"
              "\tld b,(hl)\n\tinc hl\n"
              "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n", out);
    }

    if (check->width == 4) {
        mir_emit_fixed_point_constant(out, check->expected);
        fputs("\tpush de\n\tpush bc\n", out);
        cleanup = 5;
    } else {
        fprintf(out, "\tld hl,%lu\n\tpush hl\n",
                check->expected & 0xffffUL);
        fputs("\tpush de\n", out);
        cleanup = 3;
    }
    fprintf(out, "\tld hl,S%d\n\tpush hl\n",
            check->string_id);
    mir_machine_emit_symbol_call(out, check->function);
    while (cleanup-- > 0)
        fputs("\tpop bc\n", out);
}

static void mir_emit_alias_mix_schedule(
    FILE *out, const struct MirAliasMixSchedule *plan)
{
    int item;

    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    for (item = 0; item < 24; ++item)
        mir_alias_mix_emit_store(out, &plan->stores[item]);
    for (item = 0; item < 24; ++item)
        mir_alias_mix_emit_check(out, &plan->checks[item]);
    fputs("\tret\n", out);
}

static void mir_task_array_push_arguments(
    FILE *out, int task_count)
{
    fprintf(out,
            "\tld hl,%d\n\tpush hl\n"
            "\tpush ix\n\tpop hl\n"
            "\tld de,-22\n\tadd hl,de\n\tpush hl\n",
            task_count);
}

static void mir_emit_task_array_check(
    FILE *out, const struct MirTaskArrayCheck *plan)
{
    int count_ok = new_label();
    int nonnull = new_label();
    int priority_ok = new_label();
    int name_failure = new_label();
    int done = new_label();
    int item;

    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    fputs("\tpush ix\n\tld ix,0\n\tadd ix,sp\n"
          "\tld hl,-22\n\tadd hl,sp\n\tld sp,hl\n", out);
    for (item = 0; item < plan->task_count; ++item) {
        int offset = -22 + item * 5;

        fprintf(out,
                "\tld hl,S%d\n"
                "\tld (ix%+d),l\n\tld (ix%+d),h\n"
                "\tld hl,%d\n"
                "\tld (ix%+d),l\n\tld (ix%+d),h\n"
                "\tld (ix%+d),%d\n",
                plan->name_string_ids[item],
                offset, offset + 1,
                plan->priorities[item],
                offset + 2, offset + 3,
                offset + 4, plan->done_values[item]);
    }
    mir_task_array_push_arguments(out, plan->task_count);
    mir_machine_emit_symbol_call(
        out, plan->highest_function);
    fputs("\tpop bc\n\tpop bc\n"
          "\tld (ix-2),l\n\tld (ix-1),h\n", out);

    mir_task_array_push_arguments(out, plan->task_count);
    mir_machine_emit_symbol_call(
        out, plan->count_function);
    fprintf(out,
            "\tpop bc\n\tpop bc\n\tld de,%d\n"
            "\tor a\n\tsbc hl,de\n\tjp z,L%d\n",
            plan->expected_open, count_ok);
    mir_task_array_push_arguments(out, plan->task_count);
    mir_machine_emit_symbol_call(
        out, plan->count_function);
    fprintf(out,
            "\tpop bc\n\tpop bc\n\tld de,%d\n"
            "\tadd hl,de\n\tjp L%d\n"
            "L%d:\n\tld l,(ix-2)\n\tld h,(ix-1)\n"
            "\tld a,h\n\tor l\n\tjp nz,L%d\n"
            "\tld hl,%d\n\tjp L%d\n"
            "L%d:\n\tinc hl\n\tinc hl\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
            "\tex de,hl\n\tld de,%d\n"
            "\tor a\n\tsbc hl,de\n\tjp z,L%d\n"
            "\tadd hl,de\n\tld de,%d\n\tadd hl,de\n"
            "\tjp L%d\n"
            "L%d:\n\tld l,(ix-2)\n\tld h,(ix-1)\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
            "\tex de,hl\n",
            plan->failure_base, done,
            count_ok, nonnull,
            plan->null_result, done,
            nonnull, plan->expected_priority,
            priority_ok, plan->priority_failure_base,
            done, priority_ok);
    for (item = 0; item < 4; ++item) {
        fputs("\tld a,(hl)\n", out);
        fprintf(out, "\tcp %d\n\tjp nz,L%d\n",
                plan->name_bytes[item] & 255,
                name_failure);
        if (item != 3)
            fputs("\tinc hl\n", out);
    }
    fprintf(out,
            "\tld hl,%d\n\tjp L%d\n"
            "L%d:\n\tld hl,%d\n"
            "L%d:\n\tld sp,ix\n\tpop ix\n\tret\n",
            plan->success_result, done,
            name_failure, plan->name_failure_result,
            done);
}

static void mir_emit_literal_check_runner(
    FILE *out, const struct MirLiteralCheckRunner *plan)
{
    int success = new_label();
    int call;

    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    if (plan->has_intro) {
        fprintf(out, "\tld hl,S%d\n\tpush hl\n",
                plan->intro_string_id);
        mir_machine_emit_symbol_call(
            out, plan->print_function);
        fputs("\tpop bc\n\tld hl,0\n", out);
        mir_machine_emit_global_word_store(
            out, plan->failure_root, 0);
    }
    for (call = 0; call < plan->call_count; ++call) {
        const struct MirLiteralCheckCall *check =
            &plan->calls[call];
        int copy;

        for (copy = 0; copy < 2; ++copy) {
            if (check->value_width == 4) {
                fprintf(out,
                        "\tld hl,%lu\n\tpush hl\n"
                        "\tld hl,%lu\n\tpush hl\n",
                        (check->value >> 16) & 0xffffUL,
                        check->value & 0xffffUL);
            } else {
                fprintf(out, "\tld hl,%lu\n\tpush hl\n",
                        check->value & 0xffffUL);
            }
        }
        fprintf(out, "\tld hl,S%d\n\tpush hl\n",
                check->string_id);
        mir_machine_emit_symbol_call(out, check->function);
        if (check->value_width == 4)
            fputs("\tpop bc\n\tpop bc\n\tpop bc\n"
                  "\tpop bc\n\tpop bc\n", out);
        else
            fputs("\tpop bc\n\tpop bc\n\tpop bc\n", out);
    }
    mir_machine_emit_global_word(
        out, plan->failure_root, 0);
    fputs("\tld a,h\n\tor l\n", out);
    fprintf(out, "\tjp z,L%d\n", success);
    if (plan->has_failure_report) {
        fputs("\tpush hl\n", out);
        fprintf(out, "\tld hl,S%d\n\tpush hl\n",
                plan->failure_string_id);
        mir_machine_emit_symbol_call(
            out, plan->print_function);
        fputs("\tpop bc\n\tpop bc\n", out);
    }
    fprintf(out,
            "\tld hl,1\n\tret\n"
            "L%d:\n\tld hl,S%d\n\tpush hl\n",
            success, plan->success_string_id);
    mir_machine_emit_symbol_call(
        out, plan->print_function);
    fputs("\tpop bc\n\tld hl,0\n\tret\n", out);
}

static void mir_emit_compound_check_store(
    FILE *out, const struct MirCompoundCheckEvent *event)
{
    if (event->value_kind == MIR_COMPOUND_CHECK_ADDRESS) {
        fputs("\tpush ix\n\tpop hl\n", out);
        mir_machine_emit_hl_offset(
            out, event->address_offset, 0);
    } else if (event->width == 1) {
        fprintf(out, "\tld (ix%+d),%lu\n",
                event->offset, event->value & 255UL);
        return;
    } else {
        fprintf(out, "\tld hl,%lu\n",
                event->value & 0xffffUL);
    }
    fprintf(out,
            "\tld (ix%+d),l\n"
            "\tld (ix%+d),h\n",
            event->offset, event->offset + 1);
}

static void mir_emit_compound_check_call(
    FILE *out, const struct MirCompoundCheckEvent *event)
{
    fprintf(out,
            "\tld hl,%lu\n\tpush hl\n"
            "\tpush hl\n"
            "\tld hl,S%d\n\tpush hl\n",
            event->value & 0xffffUL, event->string_id);
    mir_machine_emit_symbol_call(out, event->function);
    fputs("\tpop bc\n\tpop bc\n\tpop bc\n", out);
}

static void mir_emit_compound_check_runner(
    FILE *out, const struct MirCompoundCheckRunner *plan)
{
    int success = new_label();
    int event;

    fputs("\tpush ix\n\tld ix,0\n\tadd ix,sp\n", out);
    fprintf(out,
            "\tld hl,-%d\n\tadd hl,sp\n\tld sp,hl\n",
            plan->frame_bytes);
    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    for (event = 0; event < plan->event_count; ++event) {
        const struct MirCompoundCheckEvent *item =
            &plan->events[event];

        if (item->kind == MIR_COMPOUND_CHECK_STORE)
            mir_emit_compound_check_store(out, item);
        else if (item->kind == MIR_COMPOUND_CHECK_CALL)
            mir_emit_compound_check_call(out, item);
        else
            mir_machine_emit_symbol_call(
                out, item->function);
    }
    mir_machine_emit_global_word(
        out, plan->failure_root, plan->failure_offset);
    fputs("\tld a,h\n\tor l\n", out);
    fprintf(out,
            "\tjp z,L%d\n"
            "\tld hl,1\n"
            "\tld sp,ix\n\tpop ix\n\tret\n"
            "L%d:\n"
            "\tld hl,S%d\n\tpush hl\n",
            success, success, plan->success_string_id);
    mir_machine_emit_symbol_call(
        out, plan->print_function);
    fputs("\tpop bc\n"
          "\tld hl,0\n"
          "\tld sp,ix\n\tpop ix\n\tret\n", out);
}

static void mir_emit_fixed_sieve_build(
    FILE *out, const struct MirFixedSieveBuild *plan)
{
    int clear_loop = new_label();
    int p;

    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    fprintf(out,
            "\tld hl,%d\n\tadd hl,sp\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
            "\tex de,hl\n",
            plan->pointer_stack_offset);
    mir_machine_emit_hl_offset(out, plan->member_offset, 0);
    fprintf(out,
            "\tld b,%d\n\txor a\n"
            "L%d:\n\tld (hl),a\n\tinc hl\n"
            "\tdjnz L%d\n",
            (plan->limit + 1) & 255,
            clear_loop, clear_loop);
    fprintf(out,
            "\tld hl,%d\n\tadd hl,sp\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
            "\tex de,hl\n",
            plan->pointer_stack_offset);
    mir_machine_emit_hl_offset(out, plan->member_offset, 0);
    fputs("\tld (hl),1\n\tinc hl\n\tld (hl),1\n", out);

    for (p = 2; p * p <= plan->limit; ++p) {
        int divisor;
        int is_prime = 1;
        int mark_loop;
        int start;
        int count;

        for (divisor = 2;
             divisor * divisor <= p; ++divisor) {
            if (p % divisor == 0) {
                is_prime = 0;
                break;
            }
        }
        if (!is_prime)
            continue;
        mark_loop = new_label();
        start = p * p;
        count = (plan->limit - start) / p + 1;
        fprintf(out,
                "\tld hl,%d\n\tadd hl,sp\n"
                "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
                "\tex de,hl\n",
                plan->pointer_stack_offset);
        mir_machine_emit_hl_offset(
            out, plan->member_offset + start, 0);
        fprintf(out,
                "\tld de,%d\n\tld b,%d\n"
                "L%d:\n\tld (hl),1\n\tadd hl,de\n"
                "\tdjnz L%d\n",
                p, count, mark_loop, mark_loop);
    }
    fputs("\tret\n", out);
}

static void mir_emit_comment_scan_schedule(
    FILE *out, const struct MirCommentScanSchedule *plan)
{
    int loop = new_label();
    int body = new_label();
    int cursor_ready = new_label();
    int line_ready = new_label();
    int done = new_label();

    fputs("\tpush ix\n", out);
    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    mir_machine_emit_global_word(
        out, plan->state_root, plan->state_root_offset);
    fprintf(out,
            "\tpush hl\n\tpop ix\n"
            "\tld e,(ix%+d)\n\tld d,(ix%+d)\n"
            "\tld c,(ix%+d)\n\tld b,(ix%+d)\n"
            "L%d:\n"
            "\tld a,(ix%+d)\n\txor 128\n\tld h,a\n"
            "\tld a,(ix%+d)\n\txor 128\n\tcp h\n"
            "\tjp c,L%d\n\tjp nz,L%d\n"
            "\tld a,(ix%+d)\n\tcp (ix%+d)\n"
            "\tjp c,L%d\n\tjp nz,L%d\n"
            "\tld a,b\n\tcp (ix%+d)\n"
            "\tjp c,L%d\n\tjp nz,L%d\n"
            "\tld a,c\n\tcp (ix%+d)\n\tjp nc,L%d\n"
            "L%d:\n"
            "\tld h,b\n\tld l,c\n\tadd hl,de\n"
            "\tinc bc\n"
            "\tld (ix%+d),c\n\tld (ix%+d),b\n"
            "\tld a,b\n\tor c\n\tjp nz,L%d\n"
            "\tld a,(ix%+d)\n\tinc a\n"
            "\tld (ix%+d),a\n\tjp nz,L%d\n"
            "\tinc (ix%+d)\n"
            "L%d:\n"
            "\tld a,(hl)\n\tcp %d\n\tjp nz,L%d\n"
            "\tinc (ix%+d)\n\tjp nz,L%d\n"
            "\tinc (ix%+d)\n"
            "L%d:\n"
            "\tcp %d\n\tjp z,L%d\n"
            "\tcp %d\n\tjp nz,L%d\n",
            plan->source_offset, plan->source_offset + 1,
            plan->cursor_offset, plan->cursor_offset + 1,
            loop,
            plan->length_offset + 3,
            plan->cursor_offset + 3,
            body, done,
            plan->cursor_offset + 2,
            plan->length_offset + 2,
            body, done,
            plan->length_offset + 1,
            body, done,
            plan->length_offset, done,
            body,
            plan->cursor_offset, plan->cursor_offset + 1,
            cursor_ready,
            plan->cursor_offset + 2,
            plan->cursor_offset + 2, cursor_ready,
            plan->cursor_offset + 3,
            cursor_ready,
            '\n', line_ready,
            plan->line_offset, line_ready,
            plan->line_offset + 1,
            line_ready,
            ')', done,
            0x1a, loop);
    fprintf(out,
            "\tld a,(ix%+d)\n\tld (ix%+d),a\n"
            "\tld a,(ix%+d)\n\tld (ix%+d),a\n"
            "\tld a,(ix%+d)\n\tld (ix%+d),a\n"
            "\tld a,(ix%+d)\n\tld (ix%+d),a\n"
            "L%d:\n\tpop ix\n\tret\n",
            plan->length_offset, plan->cursor_offset,
            plan->length_offset + 1, plan->cursor_offset + 1,
            plan->length_offset + 2, plan->cursor_offset + 2,
            plan->length_offset + 3, plan->cursor_offset + 3,
            done);
}

static void mir_emit_whitespace_scan_schedule(
    FILE *out, const struct MirWhitespaceScanSchedule *plan)
{
    int body = new_label();
    int done = new_label();
    int line_ready = new_label();
    int loop = new_label();
    int byte;

    fputs("\tpush ix\n", out);
    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    mir_machine_emit_global_address_de(
        out, plan->state_root, plan->state_root_offset);
    fputs("\tpush de\n\tpop ix\n", out);
    fprintf(out,
            "L%d:\n"
            "\tld a,(ix%+d)\n\txor 128\n\tld h,a\n"
            "\tld a,(ix%+d)\n\txor 128\n\tcp h\n"
            "\tjp c,L%d\n\tjp nz,L%d\n"
            "\tld a,(ix%+d)\n\tcp (ix%+d)\n"
            "\tjp c,L%d\n\tjp nz,L%d\n"
            "\tld a,(ix%+d)\n\tcp (ix%+d)\n"
            "\tjp c,L%d\n\tjp nz,L%d\n"
            "\tld a,(ix%+d)\n\tcp (ix%+d)\n"
            "\tjp nc,L%d\n"
            "L%d:\n"
            "\tld e,(ix%+d)\n\tld d,(ix%+d)\n"
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
            "\tadd hl,de\n\tld l,(hl)\n\tld h,0\n\tpush hl\n",
            loop,
            plan->length_offset + 3,
            plan->cursor_offset + 3,
            body, done,
            plan->cursor_offset + 2,
            plan->length_offset + 2,
            body, done,
            plan->cursor_offset + 1,
            plan->length_offset + 1,
            body, done,
            plan->cursor_offset,
            plan->length_offset, done,
            body,
            plan->source_offset, plan->source_offset + 1,
            plan->cursor_offset, plan->cursor_offset + 1);
    mir_machine_emit_symbol_call(out, plan->space_function);
    fprintf(out,
            "\tpop bc\n\tld a,h\n\tor l\n\tjp z,L%d\n"
            "\tld e,(ix%+d)\n\tld d,(ix%+d)\n"
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
            "\tadd hl,de\n\tld a,(hl)\n\tcp %d\n"
            "\tjp nz,L%d\n"
            "\tinc (ix%+d)\n\tjp nz,L%d\n"
            "\tinc (ix%+d)\n"
            "L%d:\n",
            done,
            plan->source_offset, plan->source_offset + 1,
            plan->cursor_offset, plan->cursor_offset + 1,
            '\n', line_ready,
            plan->line_offset, line_ready,
            plan->line_offset + 1, line_ready);
    for (byte = 0; byte < 3; ++byte)
        fprintf(out,
                "\tinc (ix%+d)\n\tjp nz,L%d\n",
                plan->cursor_offset + byte,
                loop);
    fprintf(out,
            "\tinc (ix%+d)\n\tjp L%d\n"
            "L%d:\n\tpop ix\n\tret\n",
            plan->cursor_offset + 3, loop, done);
}

static void mir_emit_action_decode_parameter(
    FILE *out, int stack_offset)
{
    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n",
            stack_offset + 2, stack_offset + 3);
}

static void mir_emit_action_decode_store_constant(
    FILE *out, const struct MirActionDecodeSchedule *plan,
    int offset, int value)
{
    mir_emit_action_decode_parameter(
        out, plan->statement_stack_offset);
    mir_machine_emit_hl_offset(out, offset, 0);
    fprintf(out,
            "\tld (hl),%u\n\tinc hl\n\tld (hl),%u\n",
            (unsigned)value & 255,
            ((unsigned)value >> 8) & 255);
}

static void mir_emit_action_decode_prefix_call(
    FILE *out, const struct MirActionDecodeSchedule *plan,
    int string_id)
{
    fprintf(out, "\tld hl,S%d\n\tpush hl\n", string_id);
    mir_emit_action_decode_parameter(
        out, plan->text_stack_offset);
    fputs("\tpush hl\n", out);
    mir_machine_emit_symbol_call(out, plan->prefix_function);
    fputs("\tpop bc\n\tpop bc\n", out);
}

static void mir_emit_action_decode_return(FILE *out)
{
    fputs("\tpop ix\n\tret\n", out);
}

static void mir_emit_action_decode_schedule(
    FILE *out, const struct MirActionDecodeSchedule *plan)
{
    int goto_action = new_label();
    int return_check = new_label();
    int assignment_check = new_label();
    int final_return = new_label();

    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    fputs("\tpush ix\n\tld ix,0\n\tadd ix,sp\n", out);

    mir_emit_action_decode_parameter(
        out, plan->text_stack_offset);
    fputs("\tpush hl\n", out);
    mir_machine_emit_symbol_call(out, plan->trim_function);
    fputs("\tpop bc\n", out);
    mir_emit_action_decode_store_constant(
        out, plan, plan->action_offset,
        plan->default_action);

    mir_emit_action_decode_prefix_call(
        out, plan, plan->goto_string_ids[0]);
    fprintf(out,
            "\tld a,h\n\tor l\n\tjp nz,L%d\n",
            goto_action);
    mir_emit_action_decode_prefix_call(
        out, plan, plan->goto_string_ids[1]);
    fprintf(out,
            "\tld a,h\n\tor l\n\tjp z,L%d\n"
            "L%d:\n",
            return_check, goto_action);
    mir_emit_action_decode_store_constant(
        out, plan, plan->action_offset,
        plan->goto_action);
    mir_emit_action_decode_parameter(
        out, plan->statement_stack_offset);
    mir_machine_emit_hl_offset(
        out, plan->target_offset, 0);
    fputs("\tpush hl\n", out);
    mir_emit_action_decode_parameter(
        out, plan->text_stack_offset);
    fputs("\tpush hl\n", out);
    mir_machine_emit_symbol_call(out, plan->label_function);
    fputs("\tpop bc\n\tex de,hl\n\tpop hl\n", out);
    fputs("\tld (hl),e\n\tinc hl\n\tld (hl),d\n", out);
    mir_emit_action_decode_return(out);

    fprintf(out, "L%d:\n", return_check);
    mir_emit_action_decode_prefix_call(
        out, plan, plan->return_string_id);
    fprintf(out,
            "\tld a,h\n\tor l\n\tjp z,L%d\n",
            assignment_check);
    mir_emit_action_decode_store_constant(
        out, plan, plan->action_offset,
        plan->return_action);
    mir_emit_action_decode_return(out);

    fprintf(out, "L%d:\n\tld hl,%d\n\tpush hl\n",
            assignment_check, plan->separator);
    mir_emit_action_decode_parameter(
        out, plan->text_stack_offset);
    fputs("\tpush hl\n", out);
    mir_machine_emit_symbol_call(out, plan->search_function);
    fprintf(out,
            "\tpop bc\n\tpop bc\n"
            "\tld a,h\n\tor l\n\tjp z,L%d\n"
            "\tld hl,%u\n\tpush hl\n",
            final_return,
            (unsigned)plan->assignment_mode & 0xffffU);
    mir_emit_action_decode_parameter(
        out, plan->text_stack_offset);
    fputs("\tpush hl\n", out);
    mir_emit_action_decode_parameter(
        out, plan->statement_stack_offset);
    fputs("\tpush hl\n", out);
    mir_machine_emit_symbol_call(
        out, plan->assignment_function);
    fputs("\tpop bc\n\tpop bc\n\tpop bc\n", out);
    mir_emit_action_decode_return(out);

    fprintf(out, "L%d:\n", final_return);
    mir_emit_action_decode_return(out);
}

static void mir_emit_matrix_product_stack_word_de(
    FILE *out, int stack_offset)
{
    fprintf(out,
            "\tld hl,%d\n\tadd hl,sp\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n",
            stack_offset + 6);
}

static void mir_emit_matrix_product_source(
    FILE *out, const struct MirMatrixProductSchedule *plan)
{
    fprintf(out,
            "\tld hl,%d\n\tadd hl,sp\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
            "\tinc de\n\tinc de\n"
            "\tld (hl),d\n\tdec hl\n\tld (hl),e\n"
            "\tdec de\n\tdec de\n\tex de,hl\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
            "\tld hl,0\n\tadd hl,sp\n"
            "\tld (hl),e\n\tinc hl\n\tld (hl),d\n",
            plan->source_stack_offset + 6);
}

static void mir_emit_matrix_product_wide_sum(FILE *out)
{
    fputs("\tld a,h\n\trlca\n\tsbc a,a\n"
          "\tld d,a\n\tld e,a\n\tpush de\n\tpush hl\n"
          "\tld l,c\n\tld h,b\n"
          "\tld a,h\n\trlca\n\tsbc a,a\n"
          "\tld d,a\n\tld e,a\n"
          "\tpop bc\n\tor a\n\tadd hl,bc\n"
          "\tex de,hl\n\tpop bc\n\tadc hl,bc\n\tex de,hl\n",
          out);
}

static void mir_emit_matrix_product_convert(
    FILE *out, const struct MirMatrixProductSchedule *plan)
{
    mir_emit_runtime_call(out, "__m1s");
    fputs("\tpush de\n\tpush hl\n", out);
    mir_machine_emit_symbol_call(out, plan->convert_function);
    fputs("\tpop bc\n\tpop bc\n", out);
}

static void mir_emit_matrix_product_clamp(
    FILE *out, const struct MirMatrixProductSchedule *plan)
{
    fputs("\tpush de\n\tpush hl\n", out);
    mir_machine_emit_symbol_call(out, plan->clamp_function);
    fputs("\tpop bc\n\tpop bc\n", out);
}

static void mir_emit_matrix_product_add_accumulator(FILE *out)
{
    fputs("\tpush de\n\tpush hl\n"
          "\tld hl,8\n\tadd hl,sp\n"
          "\tld c,(hl)\n\tinc hl\n\tld b,(hl)\n"
          "\tpop de\n\tex de,hl\n\tadd hl,bc\n\tex de,hl\n"
          "\tdec hl\n\tld (hl),e\n\tinc hl\n\tld (hl),d\n"
          "\tinc hl\n\tpop de\n"
          "\tld c,(hl)\n\tinc hl\n\tld b,(hl)\n"
          "\tex de,hl\n\tadc hl,bc\n\tex de,hl\n"
          "\tdec hl\n\tld (hl),e\n\tinc hl\n\tld (hl),d\n",
          out);
}

static void mir_emit_matrix_product_q16_to_word(FILE *out)
{
    int negative = new_label();
    int convert_positive = new_label();
    int maximum = new_label();
    int minimum = new_label();
    int done = new_label();

    fprintf(out,
            "\tld a,d\n\tor a\n\tjp m,L%d\n\tjp nz,L%d\n"
            "\tld a,e\n\tcp 128\n\tjp nc,L%d\n"
            "\tcp 127\n\tjp c,L%d\n"
            "\tld a,h\n\tcp 255\n\tjp c,L%d\n"
            "\tld a,l\n\tor a\n\tjp nz,L%d\n"
            "L%d:\n\tld l,h\n\tld h,e\n\tjp L%d\n"
            "L%d:\n\tld a,d\n\tcp 255\n\tjp nz,L%d\n"
            "\tld a,e\n\tcp 128\n\tjp c,L%d\n"
            "\tld a,l\n\tld l,h\n\tld h,e\n\tor a\n"
            "\tjp z,L%d\n\tinc hl\n\tjp L%d\n"
            "L%d:\n\tld hl,32767\n\tjp L%d\n"
            "L%d:\n\tld hl,32768\n"
            "L%d:\n",
            negative, maximum, maximum, convert_positive,
            convert_positive, maximum, convert_positive, done,
            negative, minimum, minimum, done, done,
            maximum, done, minimum, done);
}

static void mir_emit_matrix_product_add_schedule(
    FILE *out, const struct MirMatrixProductSchedule *plan)
{
    int outer = new_label();
    int inner = new_label();
    int row_done = new_label();
    int done = new_label();

    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    fputs("\tpush ix\n\tld hl,0\n\tpush hl\n\tpush hl\n", out);
    mir_emit_matrix_product_stack_word_de(
        out, plan->matrix_stack_offset);
    fputs("\tpush de\n\tpop ix\n", out);
    fprintf(out,
            "\tld hl,%d\n\tadd hl,sp\n\tld b,(hl)\n"
            "L%d:\n\tld a,b\n\tor a\n\tjp z,L%d\n"
            "\txor a\n\tld hl,0\n\tadd hl,sp\n"
            "\tld (hl),a\n\tinc hl\n\tld (hl),a\n"
            "\tinc hl\n\tld (hl),a\n\tinc hl\n\tld (hl),a\n",
            plan->rows_stack_offset + 6, outer, done);
    mir_emit_matrix_product_stack_word_de(
        out, plan->source_stack_offset);
    fprintf(out,
            "\tld hl,%d\n\tadd hl,sp\n\tld c,(hl)\n"
            "L%d:\n\tld a,c\n\tor a\n\tjp z,L%d\n"
            "\tpush bc\n"
            "\tld l,(ix+0)\n\tld h,(ix+1)\n"
            "\tinc ix\n\tinc ix\n"
            "\tld a,(de)\n\tld c,a\n\tinc de\n"
            "\tld a,(de)\n\tld b,a\n\tinc de\n\tpush de\n",
            plan->columns_stack_offset + 6, inner, row_done);
    mir_emit_runtime_call(out, "__m1s");
    mir_emit_matrix_product_add_accumulator(out);
    fprintf(out,
            "\tpop de\n\tpop bc\n\tdec c\n\tjp L%d\n"
            "L%d:\n\tpush bc\n"
            "\tld hl,2\n\tadd hl,sp\n"
            "\tld c,(hl)\n\tinc hl\n\tld b,(hl)\n"
            "\tinc hl\n\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
            "\tld l,c\n\tld h,b\n",
            inner, row_done);
    mir_emit_matrix_product_q16_to_word(out);
    fputs("\tpush hl\n", out);
    fprintf(out,
            "\tld hl,%d\n\tadd hl,sp\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
            "\tinc de\n\tinc de\n"
            "\tld (hl),d\n\tdec hl\n\tld (hl),e\n"
            "\tdec de\n\tdec de\n\tpush de\n"
            "\tld a,(de)\n\tld l,a\n\tinc de\n"
            "\tld a,(de)\n\tld h,a\n\tdec de\n"
            "\tpush hl\n\tld hl,4\n\tadd hl,sp\n"
            "\tld c,(hl)\n\tinc hl\n\tld b,(hl)\n\tpop hl\n",
            plan->vector_stack_offset + 10);
    mir_emit_matrix_product_wide_sum(out);
    mir_emit_matrix_product_clamp(out, plan);
    fprintf(out,
            "\tpop de\n\tld a,l\n\tld (de),a\n\tinc de\n"
            "\tld a,h\n\tld (de),a\n"
            "\tpop hl\n\tpop bc\n\tdec b\n\tjp L%d\n"
            "L%d:\n\tpop hl\n\tpop hl\n\tpop ix\n\tret\n",
            outer, done);
}

static void mir_emit_matrix_product_schedule(
    FILE *out, const struct MirMatrixProductSchedule *plan)
{
    int outer;
    int inner;
    int row_done;
    int done;

    if (plan->kind == MIR_MATRIX_PRODUCT_ADD) {
        mir_emit_matrix_product_add_schedule(out, plan);
        return;
    }
    outer = new_label();
    inner = new_label();
    row_done = new_label();
    done = new_label();
    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    fputs("\tpush ix\n\tld hl,0\n\tpush hl\n\tpush hl\n", out);

    if (plan->kind == MIR_MATRIX_PRODUCT_TRANSPOSED) {
        fprintf(out,
                "\tld hl,%d\n\tadd hl,sp\n"
                "\tld c,(hl)\n\tld b,0\n\tsla c\n\trl b\n",
                plan->columns_stack_offset + 6);
        mir_emit_matrix_product_stack_word_de(
            out, plan->vector_stack_offset);
        fputs("\tex de,hl\n\tld e,0\n", out);
        mir_emit_runtime_call(out, "__msf");
    }

    mir_emit_matrix_product_stack_word_de(
        out, plan->matrix_stack_offset);
    fputs("\tpush de\n\tpop ix\n", out);
    fprintf(out,
            "\tld hl,%d\n\tadd hl,sp\n\tld a,(hl)\n"
            "\tld hl,2\n\tadd hl,sp\n\tld (hl),a\n"
            "L%d:\n\tld b,(hl)\n\tld a,b\n\tor a\n\tjp z,L%d\n",
            plan->rows_stack_offset + 6, outer, done);

    mir_emit_matrix_product_source(out, plan);
    mir_emit_matrix_product_stack_word_de(
        out, plan->vector_stack_offset);
    fprintf(out,
            "\tld hl,%d\n\tadd hl,sp\n\tld c,(hl)\n"
            "L%d:\n\tld a,c\n\tor a\n\tjp z,L%d\n",
            plan->columns_stack_offset + 6, inner, row_done);

    if (plan->kind == MIR_MATRIX_PRODUCT_TRANSPOSED) {
        fputs("\tpush bc\n\tpush de\n"
              "\tld hl,4\n\tadd hl,sp\n"
              "\tld c,(hl)\n\tinc hl\n\tld b,(hl)\n"
              "\tld l,(ix+0)\n\tld h,(ix+1)\n"
              "\tinc ix\n\tinc ix\n",
              out);
    } else {
        fputs("\tld a,(de)\n\tld l,a\n\tinc de\n"
              "\tld a,(de)\n\tld h,a\n\tinc de\n"
              "\tpush bc\n\tpush de\n\tpush hl\n"
              "\tld hl,6\n\tadd hl,sp\n"
              "\tld c,(hl)\n\tinc hl\n\tld b,(hl)\n"
              "\tpop hl\n",
              out);
    }
    mir_emit_matrix_product_convert(out, plan);
    fputs("\tpop de\n\tpop bc\n", out);

    if (plan->kind == MIR_MATRIX_PRODUCT_TRANSPOSED) {
        fputs("\tpush bc\n\tpush de\n"
              "\tld a,(de)\n\tld c,a\n\tinc de\n"
              "\tld a,(de)\n\tld b,a\n\tdec de\n",
              out);
        mir_emit_matrix_product_wide_sum(out);
        mir_emit_matrix_product_clamp(out, plan);
        fputs("\tpop de\n\tld a,l\n\tld (de),a\n\tinc de\n"
              "\tld a,h\n\tld (de),a\n\tinc de\n\tpop bc\n",
              out);
    } else {
        fputs("\tpush bc\n\tpush de\n\tpush ix\n\tpop de\n"
              "\tinc ix\n\tinc ix\n\tpush de\n"
              "\tld a,(de)\n\tld c,a\n\tinc de\n"
              "\tld a,(de)\n\tld b,a\n\tdec de\n",
              out);
        mir_emit_matrix_product_wide_sum(out);
        mir_emit_matrix_product_clamp(out, plan);
        fputs("\tpop de\n\tld a,l\n\tld (de),a\n\tinc de\n"
              "\tld a,h\n\tld (de),a\n"
              "\tpop de\n\tpop bc\n",
              out);
    }

    fprintf(out,
            "\tdec c\n\tjp L%d\n"
            "L%d:\n\tdec b\n\tld hl,2\n\tadd hl,sp\n"
            "\tld (hl),b\n\tjp nz,L%d\n"
            "L%d:\n\tpop hl\n\tpop hl\n\tpop ix\n\tret\n",
            inner, row_done, outer, done);
}

static void mir_emit_softmax_schedule(
    FILE *out, const struct MirSoftmaxSchedule *plan)
{
    int exponential_loop = new_label();
    int exponential_ready = new_label();
    int nonnegative = new_label();
    int index_ready = new_label();
    int normalization_loop = new_label();
    int done = new_label();

    fputs("\tpush ix\n\tld ix,0\n\tadd ix,sp\n"
          "\tld hl,-6\n\tadd hl,sp\n\tld sp,hl\n",
          out);
    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");

    fputs("\tpush ix\n\tpop hl\n\tdec hl\n\tdec hl\n"
          "\tpush hl\n", out);
    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,0\n\tpush hl\n"
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n\tpush hl\n",
            plan->length_stack_offset + 2,
            plan->vector_stack_offset + 2,
            plan->vector_stack_offset + 3);
    mir_machine_emit_symbol_call(out, plan->maximum_function);
    fputs("\tpop bc\n\tpop bc\n\tpop bc\n"
          "\tld (ix-4),l\n\tld (ix-3),h\n"
          "\txor a\n\tld (ix-6),a\n\tld (ix-5),a\n",
          out);

    fprintf(out,
            "\tld a,(ix%+d)\n\tor a\n\tjp z,L%d\n"
            "\tld b,a\n\tld e,(ix%+d)\n\tld d,(ix%+d)\n"
            "L%d:\n\tpush bc\n\tpush de\n"
            "\tld a,(de)\n\tld c,a\n\tinc de\n"
            "\tld a,(de)\n\tld b,a\n\tld d,b\n\tld e,c\n"
            "\tld l,(ix-4)\n\tld h,(ix-3)\n"
            "\tor a\n\tsbc hl,de\n\tbit 7,h\n"
            "\tjp z,L%d\n\tld hl,0\n"
            "L%d:\n\tsra h\n\trr l\n\tsra h\n\trr l\n"
            "\tsra h\n\trr l\n\tld a,h\n\tor a\n"
            "\tjp z,L%d\n\tld hl,255\n"
            "L%d:\n\tadd hl,hl\n",
            plan->length_stack_offset + 2, exponential_ready,
            plan->vector_stack_offset + 2,
            plan->vector_stack_offset + 3,
            exponential_loop, nonnegative, nonnegative,
            index_ready, index_ready);
    mir_machine_emit_global_address_de(
        out, plan->table, plan->table_offset);
    fputs("\tadd hl,de\n\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
          "\tpop bc\n\tld a,e\n\tld (bc),a\n\tinc bc\n"
          "\tld a,d\n\tld (bc),a\n\tinc bc\n"
          "\tld l,(ix-6)\n\tld h,(ix-5)\n\tadd hl,de\n"
          "\tld (ix-6),l\n\tld (ix-5),h\n"
          "\tld d,b\n\tld e,c\n\tpop bc\n\tdjnz ",
          out);
    fprintf(out, "L%d\n", exponential_loop);

    fprintf(out,
            "L%d:\n\tld a,(ix%+d)\n\tor a\n\tjp z,L%d\n"
            "\tld b,a\n\tld e,(ix%+d)\n\tld d,(ix%+d)\n"
            "L%d:\n\tpush bc\n\tpush de\n"
            "\tld a,(de)\n\tld l,a\n\tinc de\n"
            "\tld a,(de)\n\tld h,a\n\tld a,h\n\trlca\n"
            "\tsbc a,a\n\tld d,a\n\tld e,a\n"
            "\tld d,e\n\tld e,h\n\tld h,l\n\tld l,0\n"
            "\tpush de\n\tpush hl\n"
            "\tld l,(ix-6)\n\tld h,(ix-5)\n"
            "\tld a,h\n\trlca\n\tsbc a,a\n"
            "\tld d,a\n\tld e,a\n",
            exponential_ready, plan->length_stack_offset + 2, done,
            plan->vector_stack_offset + 2,
            plan->vector_stack_offset + 3,
            normalization_loop);
    mir_emit_runtime_call(out, "__lds");
    fputs("\tpop bc\n\tpop bc\n\tpush de\n\tpush hl\n", out);
    mir_machine_emit_symbol_call(out, plan->clamp_function);
    fputs("\tpop bc\n\tpop bc\n\tpop de\n"
          "\tld a,l\n\tld (de),a\n\tinc de\n"
          "\tld a,h\n\tld (de),a\n\tinc de\n"
          "\tpop bc\n\tdjnz ", out);
    fprintf(out,
            "L%d\nL%d:\n\tld sp,ix\n\tpop ix\n\tret\n",
            normalization_loop, done);
}

static void mir_emit_backward_address_hl(
    FILE *out, const struct MirBackwardPassSchedule *plan,
    int location, int byte_offset)
{
    const struct MirBackwardLocation *global =
        &plan->locations[location];

    mir_machine_emit_global_address_de(
        out, global->root, global->offset + byte_offset);
    fputs("\tex de,hl\n", out);
}

static void mir_emit_backward_push_address(
    FILE *out, const struct MirBackwardPassSchedule *plan,
    int location, int byte_offset)
{
    mir_emit_backward_address_hl(
        out, plan, location, byte_offset);
    fputs("\tpush hl\n", out);
}

static void mir_emit_backward_cleanup(FILE *out, int words)
{
    while (words-- > 0)
        fputs("\tpop bc\n", out);
}

static void mir_emit_backward_byte_index_address(
    FILE *out, const struct MirBackwardPassSchedule *plan,
    int location, int byte_offset, int outer_frame_offset,
    int outer_scale, int inner_frame_offset, int inner_scale)
{
    if (outer_frame_offset != 0) {
        fprintf(out,
                "\tld l,(ix%+d)\n\tld h,0\n",
                outer_frame_offset);
        mir_emit_mul_hl_const(out, (unsigned long)outer_scale);
    } else {
        fputs("\tld hl,0\n", out);
    }
    if (inner_frame_offset != 0) {
        fprintf(out,
                "\tld c,(ix%+d)\n\tld b,0\n",
                inner_frame_offset);
        if (inner_scale == 2)
            fputs("\tsla c\n\trl b\n", out);
        else if (inner_scale != 1) {
            fputs("\tpush hl\n\tld l,c\n\tld h,b\n", out);
            mir_emit_mul_hl_const(
                out, (unsigned long)inner_scale);
            fputs("\tld c,l\n\tld b,h\n\tpop hl\n", out);
        }
        fputs("\tadd hl,bc\n", out);
    }
    mir_machine_emit_global_address_de(
        out, plan->locations[location].root,
        plan->locations[location].offset + byte_offset);
    fputs("\tadd hl,de\n", out);
}

static void mir_emit_backward_word_index_address(
    FILE *out, const struct MirBackwardPassSchedule *plan,
    int location, int byte_offset, int word_frame_offset,
    int word_scale, int inner_frame_offset)
{
    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n",
            word_frame_offset, word_frame_offset + 1);
    mir_emit_mul_hl_const(out, (unsigned long)word_scale);
    if (inner_frame_offset != 0)
        fprintf(out,
                "\tld c,(ix%+d)\n\tld b,0\n"
                "\tsla c\n\trl b\n\tadd hl,bc\n",
                inner_frame_offset);
    mir_machine_emit_global_address_de(
        out, plan->locations[location].root,
        plan->locations[location].offset + byte_offset);
    fputs("\tadd hl,de\n", out);
}

static void mir_emit_backward_load_word(FILE *out)
{
    fputs("\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
          "\tex de,hl\n", out);
}

static void mir_emit_backward_sign_extend(FILE *out)
{
    fputs("\tld a,h\n\trlca\n\tsbc a,a\n"
          "\tld d,a\n\tld e,a\n", out);
}

static void mir_emit_backward_combine_long(
    FILE *out, int subtract)
{
    fputs("\tld c,l\n\tld b,h\n\tpop hl\n", out);
    if (subtract)
        fputs("\tor a\n\tsbc hl,bc\n", out);
    else
        fputs("\tadd hl,bc\n", out);
    fputs("\tex (sp),hl\n", out);
    if (subtract)
        fputs("\tsbc hl,de\n", out);
    else
        fputs("\tadc hl,de\n", out);
    fputs("\tex de,hl\n\tpop hl\n", out);
}

static void mir_emit_backward_long_call(
    FILE *out, struct Sym *function)
{
    fputs("\tpush de\n\tpush hl\n", out);
    mir_machine_emit_symbol_call(out, function);
    mir_emit_backward_cleanup(out, 2);
}

static void mir_emit_backward_clear(
    FILE *out, const struct MirBackwardPassSchedule *plan,
    int location, int bytes)
{
    fprintf(out, "\tld hl,%d\n\tpush hl\n"
                 "\tld hl,0\n\tpush hl\n", bytes);
    mir_emit_backward_push_address(out, plan, location, 0);
    mir_machine_emit_symbol_call(
        out, plan->functions[MIR_BACKWARD_CLEAR_FUNCTION]);
    mir_emit_backward_cleanup(out, 3);
}

static void mir_emit_backward_copy(
    FILE *out, const struct MirBackwardPassSchedule *plan,
    int destination, int source, int bytes)
{
    fprintf(out, "\tld hl,%d\n\tpush hl\n", bytes);
    mir_emit_backward_push_address(out, plan, source, 0);
    mir_emit_backward_push_address(out, plan, destination, 0);
    mir_machine_emit_symbol_call(
        out, plan->functions[MIR_BACKWARD_COPY_FUNCTION]);
    mir_emit_backward_cleanup(out, 3);
}

static void mir_emit_backward_clamped_add(
    FILE *out, const struct MirBackwardPassSchedule *plan,
    int destination, int destination_byte_offset,
    int destination_outer_frame, int destination_outer_scale,
    int source, int source_byte_offset,
    int source_outer_frame, int source_outer_scale,
    int inner_frame)
{
    mir_emit_backward_byte_index_address(
        out, plan, source, source_byte_offset,
        source_outer_frame, source_outer_scale,
        inner_frame, 2);
    mir_emit_backward_load_word(out);
    fputs("\tld (ix-4),l\n\tld (ix-3),h\n", out);

    mir_emit_backward_byte_index_address(
        out, plan, destination, destination_byte_offset,
        destination_outer_frame, destination_outer_scale,
        inner_frame, 2);
    fputs("\tpush hl\n", out);
    mir_emit_backward_load_word(out);
    mir_emit_backward_sign_extend(out);
    fputs("\tpush de\n\tpush hl\n"
          "\tld l,(ix-4)\n\tld h,(ix-3)\n", out);
    mir_emit_backward_sign_extend(out);
    mir_emit_backward_combine_long(out, 0);
    mir_emit_backward_long_call(
        out, plan->functions[MIR_BACKWARD_CLAMP_FUNCTION]);
    fputs("\tpop de\n\tld a,l\n\tld (de),a\n"
          "\tinc de\n\tld a,h\n\tld (de),a\n", out);
}

static void mir_emit_backward_pass_schedule(
    FILE *out, const struct MirBackwardPassSchedule *plan)
{
    int step1 = new_label();
    int step1_scale = new_label();
    int step1_scale_done = new_label();
    int step2_outer = new_label();
    int step2_inner = new_label();
    int step2_inner_done = new_label();
    int step2_row_done = new_label();
    int step3_outer = new_label();
    int step3_inner = new_label();
    int step3_inner_done = new_label();
    int step4_query = new_label();
    int step4_key = new_label();
    int step4_copy = new_label();
    int step4_copy_done = new_label();
    int step5 = new_label();
    int step6_outer = new_label();
    int step6_inner = new_label();
    int done = new_label();
    int shift;

    fputs("\tpush ix\n\tld ix,0\n\tadd ix,sp\n"
          "\tld hl,-6\n\tadd hl,sp\n\tld sp,hl\n", out);
    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");

    mir_emit_backward_clear(
        out, plan, MIR_BACKWARD_ATTENTION_OUTPUT_GRADIENTS, 256);
    fputs("\txor a\n\tld (ix-1),a\n", out);
    fprintf(out, "L%d:\n", step1);
    fputs("\tld a,(ix-1)\n\tcp 8\n", out);
    fprintf(out, "\tjp z,L%d\n", step2_outer);

    fputs("\tld hl,20\n\tpush hl\n", out);
    mir_emit_backward_byte_index_address(
        out, plan, MIR_BACKWARD_LOGITS, 0, -1, 20, 0, 0);
    fputs("\tpush hl\n", out);
    mir_emit_backward_push_address(
        out, plan, MIR_BACKWARD_LOGIT_GRADIENTS, 0);
    mir_machine_emit_symbol_call(
        out, plan->functions[MIR_BACKWARD_COPY_FUNCTION]);
    mir_emit_backward_cleanup(out, 3);

    fputs("\tld hl,10\n\tpush hl\n", out);
    mir_emit_backward_push_address(
        out, plan, MIR_BACKWARD_LOGIT_GRADIENTS, 0);
    mir_machine_emit_symbol_call(
        out, plan->functions[MIR_BACKWARD_SOFTMAX_FUNCTION]);
    mir_emit_backward_cleanup(out, 2);

    mir_emit_backward_byte_index_address(
        out, plan, MIR_BACKWARD_TARGETS, 0, -1, 2, 0, 0);
    mir_emit_backward_load_word(out);
    fputs("\tadd hl,hl\n", out);
    mir_machine_emit_global_address_de(
        out, plan->locations[MIR_BACKWARD_LOGIT_GRADIENTS].root,
        plan->locations[MIR_BACKWARD_LOGIT_GRADIENTS].offset);
    fputs("\tadd hl,de\n\tpush hl\n", out);
    mir_emit_backward_load_word(out);
    fputs("\tld de,256\n\tor a\n\tsbc hl,de\n"
          "\tpop de\n\tld a,l\n\tld (de),a\n"
          "\tinc de\n\tld a,h\n\tld (de),a\n"
          "\txor a\n\tld (ix-2),a\n", out);

    fprintf(out, "L%d:\n", step1_scale);
    fputs("\tld a,(ix-2)\n\tcp 10\n", out);
    fprintf(out, "\tjp z,L%d\n", step1_scale_done);
    mir_emit_backward_byte_index_address(
        out, plan, MIR_BACKWARD_LOGIT_GRADIENTS, 0,
        -2, 2, 0, 0);
    fputs("\tpush hl\n", out);
    mir_emit_backward_load_word(out);
    mir_emit_backward_sign_extend(out);
    for (shift = 0; shift < 7; ++shift)
        fputs("\tadd hl,hl\n\trl e\n\trl d\n", out);
    mir_emit_backward_long_call(
        out, plan->functions[MIR_BACKWARD_CLAMP_FUNCTION]);
    fputs("\tpop de\n\tld a,l\n\tld (de),a\n"
          "\tinc de\n\tld a,h\n\tld (de),a\n"
          "\tinc (ix-2)\n", out);
    fprintf(out, "\tjp L%d\nL%d:\n",
            step1_scale, step1_scale_done);

    fputs("\tld hl,10\n\tpush hl\n"
          "\tld hl,16\n\tpush hl\n", out);
    mir_emit_backward_push_address(
        out, plan, MIR_BACKWARD_LOGIT_GRADIENTS, 0);
    mir_emit_backward_byte_index_address(
        out, plan, MIR_BACKWARD_ATTENTION_OUTPUT, 0,
        -1, 32, 0, 0);
    fputs("\tpush hl\n", out);
    mir_emit_backward_push_address(
        out, plan, MIR_BACKWARD_OUTPUT_WEIGHT_GRADIENTS, 0);
    mir_machine_emit_symbol_call(
        out, plan->functions[MIR_BACKWARD_OUTER_PRODUCT_FUNCTION]);
    mir_emit_backward_cleanup(out, 5);

    fputs("\tld hl,10\n\tpush hl\n"
          "\tld hl,16\n\tpush hl\n", out);
    mir_emit_backward_byte_index_address(
        out, plan, MIR_BACKWARD_ATTENTION_OUTPUT_GRADIENTS, 0,
        -1, 32, 0, 0);
    fputs("\tpush hl\n", out);
    mir_emit_backward_push_address(
        out, plan, MIR_BACKWARD_LOGIT_GRADIENTS, 0);
    mir_emit_backward_push_address(
        out, plan, MIR_BACKWARD_OUTPUT_WEIGHTS, 0);
    mir_machine_emit_symbol_call(
        out, plan->functions[MIR_BACKWARD_MATRIX_MULTIPLY_FUNCTION]);
    mir_emit_backward_cleanup(out, 5);
    fputs("\tinc (ix-1)\n", out);
    fprintf(out, "\tjp L%d\n", step1);

    fprintf(out, "L%d:\n", step2_outer);
    mir_emit_backward_clear(
        out, plan, MIR_BACKWARD_VALUE_STATE_GRADIENTS, 256);
    fputs("\txor a\n\tld (ix-1),a\n", out);
    fprintf(out, "L%d:\n", step2_inner_done);
    fputs("\tld a,(ix-1)\n\tcp 8\n", out);
    fprintf(out, "\tjp z,L%d\n\txor a\n\tld (ix-2),a\n",
            step3_outer);
    fprintf(out, "L%d:\n", step2_inner);
    fputs("\tld a,(ix-2)\n\tcp 8\n", out);
    fprintf(out, "\tjp z,L%d\n", step2_row_done);

    mir_emit_backward_byte_index_address(
        out, plan, MIR_BACKWARD_ATTENTION_SCORE_GRADIENTS, 0,
        -1, 16, -2, 2);
    fputs("\tpush hl\n\tld hl,16\n\tpush hl\n", out);
    mir_emit_backward_byte_index_address(
        out, plan, MIR_BACKWARD_ATTENTION_OUTPUT_GRADIENTS, 0,
        -1, 32, 0, 0);
    fputs("\tpush hl\n", out);
    mir_emit_backward_byte_index_address(
        out, plan, MIR_BACKWARD_ATTENTION_WORKSPACE, 512,
        -2, 32, 0, 0);
    fputs("\tpush hl\n", out);
    mir_machine_emit_symbol_call(
        out, plan->functions[MIR_BACKWARD_DOT_PRODUCT_FUNCTION]);
    mir_emit_backward_cleanup(out, 3);
    fputs("\tpop de\n\tld a,l\n\tld (de),a\n"
          "\tinc de\n\tld a,h\n\tld (de),a\n", out);

    mir_emit_backward_byte_index_address(
        out, plan, MIR_BACKWARD_ATTENTION_WORKSPACE, 768,
        -1, 16, -2, 2);
    mir_emit_backward_load_word(out);
    fputs("\tld (ix-4),l\n\tld (ix-3),h\n"
          "\tld hl,16\n\tpush hl\n", out);
    mir_emit_backward_byte_index_address(
        out, plan, MIR_BACKWARD_VALUE_STATE_GRADIENTS, 0,
        -2, 32, 0, 0);
    fputs("\tpush hl\n", out);
    mir_emit_backward_byte_index_address(
        out, plan, MIR_BACKWARD_ATTENTION_OUTPUT_GRADIENTS, 0,
        -1, 32, 0, 0);
    fputs("\tpush hl\n\tld l,(ix-4)\n\tld h,(ix-3)\n"
          "\tpush hl\n", out);
    mir_machine_emit_symbol_call(
        out, plan->functions[MIR_BACKWARD_SCALED_ADD_FUNCTION]);
    mir_emit_backward_cleanup(out, 4);
    fputs("\tinc (ix-2)\n", out);
    fprintf(out, "\tjp L%d\nL%d:\n\tinc (ix-1)\n\tjp L%d\n",
            step2_inner, step2_row_done, step2_inner_done);

    fprintf(out, "L%d:\n", step3_outer);
    fputs("\txor a\n\tld (ix-1),a\n", out);
    {
        int step3_rows = new_label();

        fprintf(out, "L%d:\n", step3_rows);
        fputs("\tld a,(ix-1)\n\tcp 8\n", out);
        fprintf(out, "\tjp z,L%d\n", step4_query);
        fputs("\tld hl,8\n\tpush hl\n", out);
        mir_emit_backward_byte_index_address(
            out, plan, MIR_BACKWARD_ATTENTION_SCORE_GRADIENTS, 0,
            -1, 16, 0, 0);
        fputs("\tpush hl\n", out);
        mir_emit_backward_byte_index_address(
            out, plan, MIR_BACKWARD_ATTENTION_WORKSPACE, 768,
            -1, 16, 0, 0);
        fputs("\tpush hl\n", out);
        mir_machine_emit_symbol_call(
            out, plan->functions[MIR_BACKWARD_DOT_PRODUCT_FUNCTION]);
        mir_emit_backward_cleanup(out, 3);
        fputs("\tld (ix-6),l\n\tld (ix-5),h\n"
              "\txor a\n\tld (ix-2),a\n", out);
        fprintf(out, "L%d:\n", step3_inner);
        fputs("\tld a,(ix-2)\n\tcp 8\n", out);
        fprintf(out, "\tjp z,L%d\n", step3_inner_done);

        mir_emit_backward_byte_index_address(
            out, plan, MIR_BACKWARD_ATTENTION_SCORE_GRADIENTS, 0,
            -1, 16, -2, 2);
        mir_emit_backward_load_word(out);
        mir_emit_backward_sign_extend(out);
        fputs("\tpush de\n\tpush hl\n"
              "\tld l,(ix-6)\n\tld h,(ix-5)\n", out);
        mir_emit_backward_sign_extend(out);
        mir_emit_backward_combine_long(out, 1);
        mir_emit_backward_long_call(
            out, plan->functions[MIR_BACKWARD_CLAMP_FUNCTION]);
        fputs("\tld (ix-4),l\n\tld (ix-3),h\n", out);

        mir_emit_backward_byte_index_address(
            out, plan, MIR_BACKWARD_ATTENTION_WORKSPACE, 768,
            -1, 16, -2, 2);
        mir_emit_backward_load_word(out);
        fputs("\tld c,(ix-4)\n\tld b,(ix-3)\n", out);
        mir_emit_runtime_call(out, "__m1s");
        mir_emit_backward_long_call(
            out, plan->functions[MIR_BACKWARD_Q16_FUNCTION]);
        fputs("\tld (ix-4),l\n\tld (ix-3),h\n", out);

        mir_emit_backward_byte_index_address(
            out, plan, MIR_BACKWARD_ATTENTION_SCORE_GRADIENTS, 0,
            -1, 16, -2, 2);
        fputs("\tpush hl\n\tld hl,2\n\tpush hl\n"
              "\tld l,(ix-4)\n\tld h,(ix-3)\n\tpush hl\n", out);
        mir_machine_emit_symbol_call(
            out, plan->functions[MIR_BACKWARD_SHIFT_FUNCTION]);
        mir_emit_backward_cleanup(out, 2);
        fputs("\tpop de\n\tld a,l\n\tld (de),a\n"
              "\tinc de\n\tld a,h\n\tld (de),a\n"
              "\tinc (ix-2)\n", out);
        fprintf(out, "\tjp L%d\nL%d:\n\tinc (ix-1)\n\tjp L%d\n",
                step3_inner, step3_inner_done, step3_rows);
    }

    fprintf(out, "L%d:\n", step4_query);
    fputs("\txor a\n\tld (ix-1),a\n", out);
    {
        int query_loop = new_label();

        fprintf(out, "L%d:\n", query_loop);
        fputs("\tld a,(ix-1)\n\tcp 8\n", out);
        fprintf(out, "\tjp z,L%d\n", step4_key);
        fputs("\tld hl,16\n\tpush hl\n"
              "\tld hl,8\n\tpush hl\n", out);
        mir_emit_backward_byte_index_address(
            out, plan, MIR_BACKWARD_QUERY_STATE_GRADIENTS, 0,
            -1, 32, 0, 0);
        fputs("\tpush hl\n", out);
        mir_emit_backward_byte_index_address(
            out, plan, MIR_BACKWARD_ATTENTION_SCORE_GRADIENTS, 0,
            -1, 16, 0, 0);
        fputs("\tpush hl\n", out);
        mir_emit_backward_push_address(
            out, plan, MIR_BACKWARD_ATTENTION_WORKSPACE, 256);
        mir_machine_emit_symbol_call(
            out, plan->functions[MIR_BACKWARD_TRANSPOSE_FUNCTION]);
        mir_emit_backward_cleanup(out, 5);
        fputs("\tinc (ix-1)\n", out);
        fprintf(out, "\tjp L%d\n", query_loop);
    }

    fprintf(out, "L%d:\n", step4_key);
    fputs("\txor a\n\tld (ix-2),a\n", out);
    {
        int key_loop = new_label();

        fprintf(out, "L%d:\n", key_loop);
        fputs("\tld a,(ix-2)\n\tcp 8\n", out);
        fprintf(out, "\tjp z,L%d\n\txor a\n\tld (ix-1),a\n",
                step5);
        fprintf(out, "L%d:\n", step4_copy);
        fputs("\tld a,(ix-1)\n\tcp 8\n", out);
        fprintf(out, "\tjp z,L%d\n", step4_copy_done);
        mir_emit_backward_byte_index_address(
            out, plan, MIR_BACKWARD_ATTENTION_SCORE_GRADIENTS, 0,
            -1, 16, -2, 2);
        mir_emit_backward_load_word(out);
        fputs("\tpush hl\n", out);
        mir_emit_backward_byte_index_address(
            out, plan, MIR_BACKWARD_GRADIENT_COLUMN, 0,
            -1, 2, 0, 0);
        fputs("\tpop de\n\tld (hl),e\n\tinc hl\n\tld (hl),d\n"
              "\tinc (ix-1)\n", out);
        fprintf(out, "\tjp L%d\nL%d:\n",
                step4_copy, step4_copy_done);
        fputs("\tld hl,16\n\tpush hl\n"
              "\tld hl,8\n\tpush hl\n", out);
        mir_emit_backward_byte_index_address(
            out, plan, MIR_BACKWARD_KEY_STATE_GRADIENTS, 0,
            -2, 32, 0, 0);
        fputs("\tpush hl\n", out);
        mir_emit_backward_push_address(
            out, plan, MIR_BACKWARD_GRADIENT_COLUMN, 0);
        mir_emit_backward_push_address(
            out, plan, MIR_BACKWARD_ATTENTION_WORKSPACE, 0);
        mir_machine_emit_symbol_call(
            out, plan->functions[MIR_BACKWARD_TRANSPOSE_FUNCTION]);
        mir_emit_backward_cleanup(out, 5);
        fputs("\tinc (ix-2)\n", out);
        fprintf(out, "\tjp L%d\n", key_loop);
    }

    fprintf(out, "L%d:\n", step5);
    mir_emit_backward_copy(
        out, plan, MIR_BACKWARD_EMBEDDING_GRADIENTS,
        MIR_BACKWARD_ATTENTION_OUTPUT_GRADIENTS, 256);
    fputs("\txor a\n\tld (ix-1),a\n", out);
    {
        int projection_loop = new_label();

        fprintf(out, "L%d:\n", projection_loop);
        fputs("\tld a,(ix-1)\n\tcp 8\n", out);
        fprintf(out, "\tjp z,L%d\n", step6_outer);

#define MIR_BACKWARD_EMIT_MATRIX_CALL(function_slot, matrix_slot, input_slot, output_slot) \
        fputs("\tld hl,16\n\tpush hl\n" \
              "\tld hl,16\n\tpush hl\n", out); \
        mir_emit_backward_byte_index_address( \
            out, plan, output_slot, 0, -1, 32, 0, 0); \
        fputs("\tpush hl\n", out); \
        mir_emit_backward_byte_index_address( \
            out, plan, input_slot, 0, -1, 32, 0, 0); \
        fputs("\tpush hl\n", out); \
        mir_emit_backward_push_address(out, plan, matrix_slot, 0); \
        mir_machine_emit_symbol_call(out, plan->functions[function_slot]); \
        mir_emit_backward_cleanup(out, 5)

        MIR_BACKWARD_EMIT_MATRIX_CALL(
            MIR_BACKWARD_MATRIX_ADD_FUNCTION,
            MIR_BACKWARD_QUERY_WEIGHTS,
            MIR_BACKWARD_QUERY_STATE_GRADIENTS,
            MIR_BACKWARD_EMBEDDING_GRADIENTS);
        MIR_BACKWARD_EMIT_MATRIX_CALL(
            MIR_BACKWARD_OUTER_PRODUCT_FUNCTION,
            MIR_BACKWARD_QUERY_WEIGHT_GRADIENTS,
            MIR_BACKWARD_EMBEDDINGS,
            MIR_BACKWARD_QUERY_STATE_GRADIENTS);
        MIR_BACKWARD_EMIT_MATRIX_CALL(
            MIR_BACKWARD_MATRIX_ADD_FUNCTION,
            MIR_BACKWARD_KEY_WEIGHTS,
            MIR_BACKWARD_KEY_STATE_GRADIENTS,
            MIR_BACKWARD_EMBEDDING_GRADIENTS);
        MIR_BACKWARD_EMIT_MATRIX_CALL(
            MIR_BACKWARD_OUTER_PRODUCT_FUNCTION,
            MIR_BACKWARD_KEY_WEIGHT_GRADIENTS,
            MIR_BACKWARD_EMBEDDINGS,
            MIR_BACKWARD_KEY_STATE_GRADIENTS);
        MIR_BACKWARD_EMIT_MATRIX_CALL(
            MIR_BACKWARD_MATRIX_ADD_FUNCTION,
            MIR_BACKWARD_VALUE_WEIGHTS,
            MIR_BACKWARD_VALUE_STATE_GRADIENTS,
            MIR_BACKWARD_EMBEDDING_GRADIENTS);
        MIR_BACKWARD_EMIT_MATRIX_CALL(
            MIR_BACKWARD_OUTER_PRODUCT_FUNCTION,
            MIR_BACKWARD_VALUE_WEIGHT_GRADIENTS,
            MIR_BACKWARD_EMBEDDINGS,
            MIR_BACKWARD_VALUE_STATE_GRADIENTS);
#undef MIR_BACKWARD_EMIT_MATRIX_CALL

        fputs("\tinc (ix-1)\n", out);
        fprintf(out, "\tjp L%d\n", projection_loop);
    }

    fprintf(out, "L%d:\n", step6_outer);
    fputs("\txor a\n\tld (ix-1),a\n", out);
    {
        int embedding_outer = new_label();

        fprintf(out, "L%d:\n", embedding_outer);
        fputs("\tld a,(ix-1)\n\tcp 8\n", out);
        fprintf(out, "\tjp z,L%d\n", done);
        mir_emit_backward_byte_index_address(
            out, plan, MIR_BACKWARD_TOKENS, 0,
            -1, 2, 0, 0);
        mir_emit_backward_load_word(out);
        fputs("\tld (ix-6),l\n\tld (ix-5),h\n"
              "\txor a\n\tld (ix-2),a\n", out);
        fprintf(out, "L%d:\n", step6_inner);
        fputs("\tld a,(ix-2)\n\tcp 16\n", out);
        {
            int embedding_inner_done = new_label();

            fprintf(out, "\tjp z,L%d\n", embedding_inner_done);

            mir_emit_backward_byte_index_address(
                out, plan, MIR_BACKWARD_EMBEDDING_GRADIENTS, 0,
                -1, 32, -2, 2);
            mir_emit_backward_load_word(out);
            fputs("\tld (ix-4),l\n\tld (ix-3),h\n", out);
            mir_emit_backward_word_index_address(
                out, plan, MIR_BACKWARD_TOKEN_GRADIENTS, 0,
                -6, 32, -2);
            fputs("\tpush hl\n", out);
            mir_emit_backward_load_word(out);
            mir_emit_backward_sign_extend(out);
            fputs("\tpush de\n\tpush hl\n"
                  "\tld l,(ix-4)\n\tld h,(ix-3)\n", out);
            mir_emit_backward_sign_extend(out);
            mir_emit_backward_combine_long(out, 0);
            mir_emit_backward_long_call(
                out, plan->functions[MIR_BACKWARD_CLAMP_FUNCTION]);
            fputs("\tpop de\n\tld a,l\n\tld (de),a\n"
                  "\tinc de\n\tld a,h\n\tld (de),a\n", out);

            mir_emit_backward_clamped_add(
                out, plan,
                MIR_BACKWARD_POSITION_GRADIENTS, 0, -1, 32,
                MIR_BACKWARD_EMBEDDING_GRADIENTS, 0, -1, 32,
                -2);
            fputs("\tinc (ix-2)\n", out);
            fprintf(out, "\tjp L%d\nL%d:\n\tinc (ix-1)\n\tjp L%d\n",
                    step6_inner, embedding_inner_done,
                    embedding_outer);
        }
    }

    fprintf(out,
            "L%d:\n\tld sp,ix\n\tpop ix\n\tret\n",
            done);
}

static void mir_emit_unsigned_long_sqrt_schedule(
    FILE *out, const struct MirUnsignedLongSqrtSchedule *plan)
{
    int initialize = new_label();
    int loop_body = new_label();
    int done = new_label();
    int early_return = new_label();
    int epilogue = new_label();
    int high_decrement_ready = new_label();
    int loop = new_label();
    int low_increment_ready = new_label();
    int subtract_mid = new_label();
    int use_mid = new_label();

    fputs("\tpush ix\n\tld ix,0\n\tadd ix,sp\n"
          "\tld hl,-12\n\tadd hl,sp\n\tld sp,hl\n", out);
    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    fprintf(out,
            "\tld a,(ix%+d)\n\tor (ix%+d)\n"
            "\tor (ix%+d)\n\tjp nz,L%d\n"
            "\tld a,(ix%+d)\n\tcp 2\n\tjp c,L%d\n"
            "L%d:\n"
            "\tld hl,1\n\tld de,0\n",
            plan->parameter_stack_offset + 5,
            plan->parameter_stack_offset + 4,
            plan->parameter_stack_offset + 3,
            initialize,
            plan->parameter_stack_offset + 2,
            early_return,
            initialize);
    mir_machine_emit_ix_wide_store(out, -4);
    fputs("\txor a\n"
          "\tld (ix-12),a\n\tld (ix-11),a\n"
          "\tld (ix-10),a\n\tld (ix-9),a\n", out);
    mir_machine_emit_ix_wide_load(
        out, plan->parameter_stack_offset + 2);
    fputs("\tsrl d\n\trr e\n\trr h\n\trr l\n", out);
    mir_machine_emit_ix_wide_store(out, -8);

    fprintf(out,
            "L%d:\n"
            "\tld a,(ix-5)\n\tcp (ix-1)\n"
            "\tjp c,L%d\n\tjp nz,L%d\n"
            "\tld a,(ix-6)\n\tcp (ix-2)\n"
            "\tjp c,L%d\n\tjp nz,L%d\n"
            "\tld a,(ix-7)\n\tcp (ix-3)\n"
            "\tjp c,L%d\n\tjp nz,L%d\n"
            "\tld a,(ix-8)\n\tcp (ix-4)\n"
            "\tjp c,L%d\n"
            "L%d:\n",
            loop,
            done, loop_body,
            done, loop_body,
            done, loop_body,
            done,
            loop_body);

    mir_machine_emit_ix_wide_load(out, -8);
    fputs("\tld c,(ix-4)\n\tld b,(ix-3)\n"
          "\tor a\n\tsbc hl,bc\n\tex de,hl\n"
          "\tld c,(ix-2)\n\tld b,(ix-1)\n"
          "\tsbc hl,bc\n\tex de,hl\n"
          "\tsrl d\n\trr e\n\trr h\n\trr l\n"
          "\tld c,(ix-4)\n\tld b,(ix-3)\n"
          "\tadd hl,bc\n\tex de,hl\n"
          "\tld c,(ix-2)\n\tld b,(ix-1)\n"
          "\tadc hl,bc\n\tex de,hl\n"
          "\tpush de\n\tpush hl\n", out);

    mir_machine_emit_ix_wide_load(
        out, plan->parameter_stack_offset + 2);
    /* __ldu takes the dividend on the stack and the divisor in DE:HL. */
    fputs("\tpush de\n\tpush hl\n"
          "\tld l,(ix-16)\n\tld h,(ix-15)\n"
          "\tld e,(ix-14)\n\tld d,(ix-13)\n", out);
    mir_emit_runtime_call(out, "__ldu");
    fputs("\tpop bc\n\tpop bc\n", out);
    fprintf(out,
            "\tld a,d\n\tcp (ix-13)\n"
            "\tjp c,L%d\n\tjp nz,L%d\n"
            "\tld a,e\n\tcp (ix-14)\n"
            "\tjp c,L%d\n\tjp nz,L%d\n"
            "\tld a,h\n\tcp (ix-15)\n"
            "\tjp c,L%d\n\tjp nz,L%d\n"
            "\tld a,l\n\tcp (ix-16)\n"
            "\tjp c,L%d\n"
            "L%d:\n\tpop hl\n\tpop de\n",
            subtract_mid, use_mid,
            subtract_mid, use_mid,
            subtract_mid, use_mid,
            subtract_mid,
            use_mid);
    mir_machine_emit_ix_wide_store(out, -12);
    fputs("\tinc hl\n\tld a,h\n\tor l\n", out);
    fprintf(out, "\tjp nz,L%d\n\tinc de\nL%d:\n",
            low_increment_ready, low_increment_ready);
    mir_machine_emit_ix_wide_store(out, -4);
    fprintf(out, "\tjp L%d\n", loop);

    fprintf(out, "L%d:\n\tpop hl\n\tpop de\n"
                 "\tld a,h\n\tor l\n\tjp nz,L%d\n"
                 "\tdec de\nL%d:\n\tdec hl\n",
            subtract_mid,
            high_decrement_ready, high_decrement_ready);
    mir_machine_emit_ix_wide_store(out, -8);
    fprintf(out, "\tjp L%d\n", loop);

    fprintf(out, "L%d:\n", done);
    mir_machine_emit_ix_wide_load(
        out, -12);
    fprintf(out, "\tjp L%d\nL%d:\n",
            epilogue, early_return);
    mir_machine_emit_ix_wide_load(
        out, plan->parameter_stack_offset + 2);
    fprintf(out,
            "L%d:\n\tld sp,ix\n\tpop ix\n\tret\n",
            epilogue);
}

static void mir_emit_format_buffer_schedule(
    FILE *out, const struct MirFormatBufferSchedule *plan)
{
    int check;
    int failure = new_label();
    int summary = new_label();
    int epilogue = new_label();

    fputs("\tpush ix\n\tld ix,0\n\tadd ix,sp\n"
          "\tld hl,-64\n\tadd hl,sp\n\tld sp,hl\n", out);
    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    mir_emit_local_address(out, -64);
    fputs("\tex de,hl\n", out);

    for (check = 0;
         check < MIR_FORMAT_BUFFER_CHECK_COUNT;
         ++check) {
        const struct MirFormatBufferCheck *item =
            &plan->checks[check];

        if (item->value_size == 4)
            mir_emit_fixed_point_constant(out, item->value);
        else
            fprintf(out, "\tld hl,%lu\n\tpush hl\n",
                    item->value & 0xffffUL);
        fprintf(out, "\tld hl,S%d\n\tpush hl\n",
                item->format_string_id);
        fputs("\tpush de\n", out);
        if ((item->runtime_flags &
             MIR_CALL_FLAG_FORMAT_HEX) != 0)
            mir_emit_runtime_call(out, "__pfehx");
        if ((item->runtime_flags &
             MIR_CALL_FLAG_FORMAT_OCTAL) != 0)
            mir_emit_runtime_call(out, "__pfeoc");
        mir_emit_runtime_call(out, item->call_name);
        fputs("\tpop de\n\tpop bc\n\tpop bc\n", out);
        if (item->value_size == 4)
            fputs("\tpop bc\n", out);

        fprintf(out,
                "\tld hl,S%d\n\tpush hl\n"
                "\tld hl,S%d\n\tpush hl\n",
                item->description_string_id,
                item->expected_string_id);
        fputs("\tpush de\n", out);
        mir_machine_emit_symbol_call(
            out, plan->check_function);
        fputs("\tpop de\n\tpop bc\n\tpop bc\n", out);
    }

    mir_machine_emit_global_word(
        out, plan->failure_root, plan->failure_offset);
    fputs("\tld a,h\n\tor l\n", out);
    fprintf(out, "\tjp nz,L%d\n", failure);
    fprintf(out, "\tld hl,S%d\n\tpush hl\n",
            plan->success_string_id);
    mir_emit_runtime_call(out, plan->success_call_name);
    fputs("\tpop bc\n", out);
    fprintf(out, "\tjp L%d\nL%d:\n",
            summary, failure);
    mir_machine_emit_global_word(
        out, plan->failure_root, plan->failure_offset);
    fputs("\tpush hl\n", out);
    fprintf(out, "\tld hl,S%d\n\tpush hl\n",
            plan->failure_string_id);
    mir_emit_runtime_call(out, plan->failure_call_name);
    fputs("\tpop bc\n\tpop bc\n", out);

    fprintf(out, "L%d:\n", summary);
    mir_machine_emit_global_word(
        out, plan->failure_root, plan->failure_offset);
    fputs("\tld a,h\n\tor l\n", out);
    fprintf(out,
            "\tld hl,0\n\tjr z,L%d\n\tinc l\n"
            "L%d:\n\tld sp,ix\n\tpop ix\n\tret\n",
            epilogue, epilogue);
}

static void mir_emit_atof_schedule_cleanup(
    FILE *out, int words)
{
    if (words >= 5) {
        fprintf(out,
                "\tld hl,%d\n\tadd hl,sp\n\tld sp,hl\n",
                words * 2);
        return;
    }
    mir_emit_final_call_cleanup(out, words);
}

static void mir_emit_atof_schedule_value(
    FILE *out, const struct MirAtofSchedule *plan,
    const struct MirAtofScheduleCheck *item)
{
    fprintf(out, "\tld hl,S%d\n\tpush hl\n",
            item->input_string_id);
    mir_machine_emit_symbol_call(out, plan->value_function);
    fputs("\tpop bc\n", out);
    if (item->has_scale) {
        fputs("\tpush de\n\tpush hl\n", out);
        mir_machine_emit_float_bits(out, item->scale);
        mir_emit_runtime_call(out, "__fmf");
        fputs("\tpop bc\n\tpop bc\n", out);
    }
}

static void mir_emit_atof_schedule_check(
    FILE *out, const struct MirAtofSchedule *plan,
    const struct MirAtofScheduleCheck *item)
{
    if (item->kind == MIR_ATOF_SCHEDULE_FLOAT) {
        mir_emit_final_call_constant(out, item->tolerance, 4);
        mir_emit_final_call_constant(out, item->expected, 4);
        mir_emit_atof_schedule_value(out, plan, item);
        fputs("\tpush de\n\tpush hl\n", out);
        fprintf(out, "\tld hl,S%d\n\tpush hl\n",
                item->name_string_id);
        mir_machine_emit_symbol_call(
            out, plan->float_check_function);
        mir_emit_atof_schedule_cleanup(out, 7);
        return;
    }
    if (item->kind == MIR_ATOF_SCHEDULE_INT) {
        fprintf(out, "\tld hl,%lu\n\tpush hl\n",
                item->expected & 0xffffUL);
        mir_emit_atof_schedule_value(out, plan, item);
        mir_emit_runtime_call(out, "__ffi");
        fputs("\tpush hl\n", out);
        fprintf(out, "\tld hl,S%d\n\tpush hl\n",
                item->name_string_id);
        mir_machine_emit_symbol_call(
            out, plan->int_check_function);
        mir_emit_atof_schedule_cleanup(out, 3);
        return;
    }
    if (item->kind == MIR_ATOF_SCHEDULE_END) {
        fprintf(out,
                "\tld hl,%lu\n\tpush hl\n"
                "\tld hl,S%d\n\tpush hl\n"
                "\tld hl,S%d\n\tpush hl\n",
                item->expected & 0xffffUL,
                item->input_string_id,
                item->name_string_id);
        mir_machine_emit_symbol_call(
            out, plan->end_check_function);
        mir_emit_atof_schedule_cleanup(out, 3);
        return;
    }
    if (item->kind == MIR_ATOF_SCHEDULE_INFINITY) {
        fprintf(out, "\tld hl,%lu\n\tpush hl\n",
                item->expected & 0xffffUL);
        mir_emit_atof_schedule_value(out, plan, item);
        fputs("\tpush de\n\tpush hl\n", out);
        fprintf(out, "\tld hl,S%d\n\tpush hl\n",
                item->name_string_id);
        mir_machine_emit_symbol_call(
            out, plan->infinity_check_function);
        mir_emit_atof_schedule_cleanup(out, 4);
        return;
    }
    mir_emit_atof_schedule_value(out, plan, item);
    fputs("\tpush de\n\tpush hl\n", out);
    fprintf(out, "\tld hl,S%d\n\tpush hl\n",
            item->name_string_id);
    mir_machine_emit_symbol_call(
        out, plan->nan_check_function);
    mir_emit_atof_schedule_cleanup(out, 3);
}

static void mir_emit_atof_schedule(
    FILE *out, const struct MirAtofSchedule *plan)
{
    int success = new_label();
    int summary = new_label();
    int check;

    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    for (check = 0;
         check < MIR_ATOF_SCHEDULE_CHECK_COUNT;
         ++check)
        mir_emit_atof_schedule_check(
            out, plan, &plan->checks[check]);

    mir_machine_emit_global_word(
        out, plan->failure_root, plan->failure_offset);
    fputs("\tld a,h\n\tor l\n", out);
    fprintf(out, "\tjp z,L%d\n", success);
    mir_machine_emit_global_word(
        out, plan->failure_root, plan->failure_offset);
    fputs("\tpush hl\n", out);
    fprintf(out, "\tld hl,S%d\n\tpush hl\n",
            plan->failure_string_id);
    mir_machine_emit_symbol_call(out, plan->print_function);
    mir_emit_atof_schedule_cleanup(out, 2);
    fprintf(out, "\tjp L%d\nL%d:\n",
            summary, success);
    mir_machine_emit_global_word(
        out, plan->checks_root, plan->checks_offset);
    fputs("\tpush hl\n", out);
    fprintf(out, "\tld hl,S%d\n\tpush hl\n",
            plan->success_string_id);
    mir_machine_emit_symbol_call(out, plan->print_function);
    mir_emit_atof_schedule_cleanup(out, 2);
    fprintf(out, "L%d:\n", summary);
    mir_machine_emit_global_word(
        out, plan->failure_root, plan->failure_offset);
    fputs("\tld a,h\n\tor l\n\tld hl,0\n\tret z\n"
          "\tinc hl\n\tret\n", out);
}

static int mir_float_report_expression_rematerializable(
    const struct MirFloatReportSchedule *plan,
    int value, int depth)
{
    const struct MirInsn *definition;

    if (depth > 32)
        return 0;
    if (mir_float_report_snapshot_index(plan, value) >= 0 ||
        mir_float_report_setup_index(plan, value) >= 0)
        return 1;
    definition = mir_definition(value);
    if (definition == NULL)
        return 0;
    if (definition->opcode == MIR_CONST ||
        definition->opcode == MIR_FLOAT_CONST ||
        definition->opcode == MIR_STRING_ADDRESS ||
        definition->opcode == MIR_ADDRESS)
        return 1;
    return definition->opcode == MIR_UNARY &&
        definition->immediate == '-' &&
        mir_float_report_expression_rematerializable(
            plan, definition->src1, depth + 1);
}

static void mir_float_report_emit_global_wide(
    FILE *out, struct Sym *symbol, int offset)
{
    const char *name = asm_name_for(sym_asm_name(symbol));

    if ((symbol->storage == SC_EXTERN || symbol->needs_extrn) &&
        mir_extrn_should_emit(symbol))
        fprintf(out, "\textrn %s\n", name);
    fprintf(out, "\tld hl,%s\n", name);
    if (offset != 0)
        fprintf(out, "\tld de,%d\n\tadd hl,de\n", offset);
    fputs("\tld c,(hl)\n\tinc hl\n\tld b,(hl)\n"
          "\tinc hl\n\tld e,(hl)\n\tinc hl\n"
          "\tld d,(hl)\n\tld h,b\n\tld l,c\n", out);
}

static void mir_float_report_emit_stack_load(
    FILE *out, int offset, int width)
{
    if (width == 2) {
        fprintf(out,
                "\tld hl,%d\n\tadd hl,sp\n"
                "\tld a,(hl)\n\tinc hl\n"
                "\tld h,(hl)\n\tld l,a\n",
                offset);
        return;
    }
    fprintf(out,
            "\tld hl,%d\n\tadd hl,sp\n"
            "\tld c,(hl)\n\tinc hl\n"
            "\tld b,(hl)\n\tinc hl\n"
            "\tld e,(hl)\n\tinc hl\n"
            "\tld d,(hl)\n\tld h,b\n\tld l,c\n",
            offset);
}

static void mir_float_report_push_value(FILE *out, int width)
{
    if (width == 4)
        fputs("\tpush de\n\tpush hl\n", out);
    else
        fputs("\tpush hl\n", out);
}

static const char *mir_float_report_binary_helper(
    const struct MirInsn *binary)
{
    switch ((int)binary->immediate) {
    case '+': return "__faf";
    case '-': return "__fsf";
    case '*': return "__fmf";
    case '/': return "__fdf";
    case TOK_EQ: return "__feqf";
    case TOK_NE: return "__fnef";
    case '<': return "__fgtf";
    case '>': return "__fltf";
    case TOK_LE: return "__fgef";
    case TOK_GE: return "__flef";
    default: return NULL;
    }
}

static void mir_emit_float_report_expression(
    FILE *out, const struct MirFloatReportSchedule *plan,
    int value);

static void mir_emit_float_report_call(
    FILE *out, const struct MirFloatReportSchedule *plan,
    const struct MirInsn *call)
{
    struct Sym *function = find_global(call->name);
    int arguments[MIR_FLOAT_REPORT_MAX_CALL_ARGS];
    int order[MIR_FLOAT_REPORT_MAX_CALL_ARGS];
    int temp_before[MIR_FLOAT_REPORT_MAX_CALL_ARGS];
    int saved[MIR_FLOAT_REPORT_MAX_CALL_ARGS] = {0, 0, 0, 0};
    int order_count = 0;
    int temp_words = 0;
    int actual_words = 0;
    int direct_argument = -1;
    int argument;

    if (function == NULL ||
        !mir_float_report_call_arguments(
            call, function->proto_nargs, arguments))
        fatal("invalid scheduled float-report call");
    for (argument = 0;
         argument < function->proto_nargs; ++argument) {
        int position;

        temp_before[argument] = 0;
        if (mir_float_report_expression_rematerializable(
                plan, arguments[argument], 0))
            continue;
        position = order_count++;
        while (position > 0 &&
               mir_definition(arguments[order[position - 1]]) >
                   mir_definition(arguments[argument])) {
            order[position] = order[position - 1];
            --position;
        }
        order[position] = argument;
    }
    if (order_count > 0) {
        int last = order[order_count - 1];
        int scheduled;

        direct_argument = last;
        for (scheduled = 0;
             scheduled < order_count - 1; ++scheduled)
            if (order[scheduled] > direct_argument)
                direct_argument = -1;
    }
    for (argument = 0;
         argument < order_count -
             (direct_argument >= 0 ? 1 : 0);
         ++argument) {
        int index = order[argument];
        int width =
            mir_float_report_value_width(arguments[index]);

        temp_before[index] = temp_words;
        mir_emit_float_report_expression(
            out, plan, arguments[index]);
        mir_float_report_push_value(out, width);
        temp_words += width / 2;
        saved[index] = 1;
    }
    for (argument = function->proto_nargs - 1;
         argument >= 0; --argument) {
        int width =
            mir_float_report_value_width(arguments[argument]);
        int words = width / 2;

        if (direct_argument >= 0 &&
            argument == direct_argument) {
            mir_emit_float_report_expression(
                out, plan, arguments[argument]);
            mir_float_report_push_value(out, width);
            actual_words += words;
            continue;
        }
        if (saved[argument]) {
            int base_words =
                temp_words -
                (temp_before[argument] + words);

            mir_float_report_emit_stack_load(
                out, 2 * (base_words + actual_words),
                width);
        } else {
            mir_emit_float_report_expression(
                out, plan, arguments[argument]);
        }
        mir_float_report_push_value(out, width);
        actual_words += words;
    }
    mir_machine_emit_symbol_call(out, function);
    mir_emit_final_call_cleanup(
        out, actual_words + temp_words);
}

static void mir_emit_float_report_expression(
    FILE *out, const struct MirFloatReportSchedule *plan,
    int value)
{
    const struct MirInsn *definition = mir_definition(value);
    int snapshot =
        mir_float_report_snapshot_index(plan, value);
    int setup =
        mir_float_report_setup_index(plan, value);
    int width = mir_float_report_value_width(value);

    if (snapshot >= 0) {
        mir_machine_emit_ix_wide_load(
            out, plan->snapshots[snapshot].ix_offset);
        return;
    }
    if (setup >= 0) {
        mir_machine_emit_ix_wide_load(
            out,
            plan->outputs[
                plan->setups[setup].output_index].ix_offset);
        return;
    }
    if (definition == NULL)
        fatal("missing scheduled float-report value");
    switch (definition->opcode) {
    case MIR_CONST:
        if (width == 4)
            mir_machine_emit_float_bits(
                out, (unsigned long)definition->immediate);
        else
            fprintf(out, "\tld hl,%lu\n",
                    (unsigned long)definition->immediate &
                        0xffffUL);
        return;
    case MIR_FLOAT_CONST:
        mir_machine_emit_float_bits(
            out, (unsigned long)definition->immediate);
        return;
    case MIR_STRING_ADDRESS:
        fprintf(out, "\tld hl,S%ld\n",
                definition->immediate);
        return;
    case MIR_ADDRESS:
        {
            int memory_type;
            int memory_storage;
            int memory_offset;
            int local;

            if (!mir_scalar_memory_location(
                    definition, &memory_type,
                    &memory_storage, &memory_offset))
                fatal("invalid scheduled float-report address");
            local = mir_float_report_find_local(
                plan->outputs, plan->output_count,
                memory_storage, memory_offset);
            if (local < 0)
                fatal("missing scheduled float-report address");
            fprintf(out,
                    "\tpush ix\n\tpop hl\n"
                    "\tld de,%d\n\tadd hl,de\n",
                    plan->outputs[local].ix_offset);
        }
        return;
    case MIR_LOAD:
        {
            int memory_type;
            int memory_storage;
            int memory_offset;
            int local;

            if (!mir_scalar_memory_location(
                    definition, &memory_type,
                    &memory_storage, &memory_offset))
                fatal("invalid scheduled float-report load");
            local = mir_float_report_find_local(
                plan->outputs, plan->output_count,
                memory_storage, memory_offset);
            if (local < 0)
                fatal("missing scheduled float-report load");
            mir_machine_emit_ix_wide_load(
                out, plan->outputs[local].ix_offset);
        }
        return;
    case MIR_UNARY:
        mir_emit_float_report_expression(
            out, plan, definition->src1);
        fputs("\tld a,d\n\txor 128\n\tld d,a\n", out);
        return;
    case MIR_BINARY:
        mir_emit_float_report_expression(
            out, plan, definition->src1);
        fputs("\tpush de\n\tpush hl\n", out);
        mir_emit_float_report_expression(
            out, plan, definition->src2);
        mir_emit_runtime_call(
            out, mir_float_report_binary_helper(definition));
        fputs("\tpop bc\n\tpop bc\n", out);
        return;
    case MIR_CALL:
        mir_emit_float_report_call(out, plan, definition);
        return;
    default:
        fatal("unsupported scheduled float-report expression");
    }
}

static void mir_emit_float_report_variant_expression(
    FILE *out, const struct MirFloatReportSchedule *plan,
    int value);

static void mir_emit_float_report_variant_call(
    FILE *out, const struct MirFloatReportSchedule *plan,
    const struct MirInsn *call)
{
    struct Sym *function = find_global(call->name);
    int arguments[MIR_FLOAT_REPORT_MAX_CALL_ARGS];
    int actual_words = 0;
    int argument;

    if (function == NULL ||
        !mir_float_report_call_arguments(
            call, function->proto_nargs, arguments))
        fatal("invalid scheduled float-report variant call");
    /* These exact profiles reproduce the legacy ABI argument evaluation
     * order, avoiding temporary saves between nested float calls. */
    for (argument = function->proto_nargs - 1;
         argument >= 0; --argument) {
        int width =
            mir_float_report_value_width(arguments[argument]);

        mir_emit_float_report_variant_expression(
            out, plan, arguments[argument]);
        mir_float_report_push_value(out, width);
        actual_words += width / 2;
    }
    mir_machine_emit_symbol_call(out, function);
    mir_emit_final_call_cleanup(out, actual_words);
}

static void mir_emit_float_report_variant_expression(
    FILE *out, const struct MirFloatReportSchedule *plan,
    int value)
{
    const struct MirInsn *definition = mir_definition(value);
    int snapshot =
        mir_float_report_snapshot_index(plan, value);
    int setup =
        mir_float_report_setup_index(plan, value);
    int width = mir_float_report_value_width(value);

    if (snapshot >= 0) {
        mir_machine_emit_ix_wide_load(
            out, plan->snapshots[snapshot].ix_offset);
        return;
    }
    if (setup >= 0) {
        mir_machine_emit_ix_wide_load(
            out,
            plan->outputs[
                plan->setups[setup].output_index].ix_offset);
        return;
    }
    if (definition == NULL)
        fatal("missing scheduled float-report variant value");
    switch (definition->opcode) {
    case MIR_CONST:
        if (width == 4)
            mir_machine_emit_float_bits(
                out, (unsigned long)definition->immediate);
        else
            fprintf(out, "\tld hl,%lu\n",
                    (unsigned long)definition->immediate &
                        0xffffUL);
        return;
    case MIR_FLOAT_CONST:
        mir_machine_emit_float_bits(
            out, (unsigned long)definition->immediate);
        return;
    case MIR_STRING_ADDRESS:
        fprintf(out, "\tld hl,S%ld\n",
                definition->immediate);
        return;
    case MIR_ADDRESS:
        {
            int memory_type;
            int memory_storage;
            int memory_offset;
            int local;

            if (!mir_scalar_memory_location(
                    definition, &memory_type,
                    &memory_storage, &memory_offset))
                fatal("invalid scheduled float-report variant address");
            local = mir_float_report_find_local(
                plan->outputs, plan->output_count,
                memory_storage, memory_offset);
            if (local < 0)
                fatal("missing scheduled float-report variant address");
            fprintf(out,
                    "\tpush ix\n\tpop hl\n"
                    "\tld de,%d\n\tadd hl,de\n",
                    plan->outputs[local].ix_offset);
        }
        return;
    case MIR_LOAD:
        {
            int memory_type;
            int memory_storage;
            int memory_offset;
            int local;

            if (!mir_scalar_memory_location(
                    definition, &memory_type,
                    &memory_storage, &memory_offset))
                fatal("invalid scheduled float-report variant load");
            local = mir_float_report_find_local(
                plan->outputs, plan->output_count,
                memory_storage, memory_offset);
            if (local < 0)
                fatal("missing scheduled float-report variant load");
            mir_machine_emit_ix_wide_load(
                out, plan->outputs[local].ix_offset);
        }
        return;
    case MIR_UNARY:
        {
            const struct MirInsn *operand =
                mir_definition(definition->src1);

            if (operand != NULL &&
                (operand->opcode == MIR_CONST ||
                 operand->opcode == MIR_FLOAT_CONST)) {
                mir_machine_emit_float_bits(
                    out,
                    ((unsigned long)operand->immediate) ^
                        0x80000000UL);
                return;
            }
        }
        mir_emit_float_report_variant_expression(
            out, plan, definition->src1);
        fputs("\tld a,d\n\txor 128\n\tld d,a\n", out);
        return;
    case MIR_BINARY:
        mir_emit_float_report_variant_expression(
            out, plan, definition->src1);
        fputs("\tpush de\n\tpush hl\n", out);
        mir_emit_float_report_variant_expression(
            out, plan, definition->src2);
        mir_emit_runtime_call(
            out, mir_float_report_binary_helper(definition));
        fputs("\tpop bc\n\tpop bc\n", out);
        return;
    case MIR_CALL:
        mir_emit_float_report_variant_call(
            out, plan, definition);
        return;
    default:
        fatal("unsupported scheduled float-report variant expression");
    }
}

static void mir_emit_float_report_epilogue(
    FILE *out, const struct MirFloatReportSchedule *plan)
{
    if (plan->frame_bytes > 0)
        fputs("\tld sp,ix\n\tpop ix\n", out);
    fputs("\tret\n", out);
}

static void mir_emit_float_report_schedule(
    FILE *out, const struct MirFloatReportSchedule *plan)
{
    int failure_string = new_label();
    int result_ready = new_label();
    int return_failure = new_label();
    int snapshot;
    int setup = 0;
    int check;

    if (plan->frame_bytes > 0) {
        fputs("\tpush ix\n\tld ix,0\n\tadd ix,sp\n", out);
        fprintf(out,
                "\tld hl,-%d\n\tadd hl,sp\n\tld sp,hl\n",
                plan->frame_bytes);
    }
    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    for (snapshot = 0;
         snapshot < plan->snapshot_count; ++snapshot) {
        mir_float_report_emit_global_wide(
            out, plan->snapshots[snapshot].root,
            plan->snapshots[snapshot].memory_offset);
        mir_machine_emit_ix_wide_store(
            out, plan->snapshots[snapshot].ix_offset);
    }
    for (check = 0; check < plan->check_count; ++check) {
        while (setup < plan->setup_count &&
               plan->setups[setup].before_check == check) {
            if (plan->variant == MIR_FLOAT_REPORT_SHARED)
                mir_emit_float_report_call(
                    out, plan,
                    &mir.insns[plan->setups[setup].call_index]);
            else
                mir_emit_float_report_variant_call(
                    out, plan,
                    &mir.insns[plan->setups[setup].call_index]);
            mir_machine_emit_ix_wide_store(
                out,
                plan->outputs[
                    plan->setups[setup].output_index].ix_offset);
            ++setup;
        }
        if (plan->variant == MIR_FLOAT_REPORT_SHARED)
            mir_emit_float_report_call(
                out, plan,
                &mir.insns[plan->checks[check].call_index]);
        else
            mir_emit_float_report_variant_call(
                out, plan,
                &mir.insns[plan->checks[check].call_index]);
    }

    mir_machine_emit_global_word(
        out, plan->failures_root, plan->failures_offset);
    fputs("\tpush hl\n", out);
    mir_machine_emit_global_word(
        out, plan->checks_root, plan->checks_offset);
    fputs("\tpush hl\n", out);
    fprintf(out, "\tld hl,S%d\n\tpush hl\n",
            plan->summary_string_id);
    mir_machine_emit_symbol_call(out, plan->print_function);
    mir_emit_final_call_cleanup(out, 3);

    mir_machine_emit_global_word(
        out, plan->failures_root, plan->failures_offset);
    fputs("\tld a,h\n\tor l\n", out);
    if (plan->variant == MIR_FLOAT_REPORT_SHARED)
        fprintf(out,
                "\tjp nz,L%d\n\tld hl,S%d\n\tpush hl\n"
                "\tjp L%d\nL%d:\n"
                "\tld hl,S%d\n\tpush hl\nL%d:\n"
                "\tld hl,S%d\n\tpush hl\n",
                failure_string, plan->success_string_id,
                result_ready, failure_string,
                plan->failure_string_id, result_ready,
                plan->result_string_id);
    else
        fprintf(out,
                "\tjr nz,L%d\n\tld hl,S%d\n\tpush hl\n"
                "\tjr L%d\nL%d:\n"
                "\tld hl,S%d\n\tpush hl\nL%d:\n"
                "\tld hl,S%d\n\tpush hl\n",
                failure_string, plan->success_string_id,
                result_ready, failure_string,
                plan->failure_string_id, result_ready,
                plan->result_string_id);
    mir_machine_emit_symbol_call(out, plan->print_function);
    mir_emit_final_call_cleanup(out, 2);

    mir_machine_emit_global_word(
        out, plan->failures_root, plan->failures_offset);
    fputs("\tld a,h\n\tor l\n", out);
    if (plan->variant == MIR_FLOAT_REPORT_SHARED) {
        fprintf(out, "\tjp nz,L%d\n\tld hl,0\n",
                return_failure);
        mir_emit_float_report_epilogue(out, plan);
        fprintf(out, "L%d:\n\tld hl,1\n", return_failure);
        mir_emit_float_report_epilogue(out, plan);
    } else {
        fprintf(out, "\tjr z,L%d\n\tld hl,1\n",
                return_failure);
        mir_emit_float_report_epilogue(out, plan);
        fprintf(out, "L%d:\n\tld hl,0\n", return_failure);
        mir_emit_float_report_epilogue(out, plan);
    }
}

static void mir_emit_raw_conversion_check_schedule(
    FILE *out, const struct MirRawConversionCheckSchedule *plan)
{
    int failure_string = new_label();
    int result_ready = new_label();
    int return_success = new_label();
    int check;

    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    for (check = 0;
         check < MIR_RAW_CONVERSION_BOOL_CHECKS; ++check) {
        const struct MirRawConversionCheck *item =
            &plan->boolean_checks[check];

        mir_emit_final_call_constant(out, item->expected, 2);
        mir_emit_final_call_constant(out, item->input, 4);
        mir_machine_emit_symbol_call(out, item->value_function);
        mir_emit_final_call_cleanup(out, 2);
        fputs("\tpush hl\n", out);
        fprintf(out, "\tld hl,S%d\n\tpush hl\n",
                item->name_string_id);
        mir_machine_emit_symbol_call(
            out, plan->boolean_check_function);
        mir_emit_final_call_cleanup(out, 3);
    }
    for (check = 0;
         check < MIR_RAW_CONVERSION_WIDE_CHECKS; ++check) {
        const struct MirRawConversionCheck *item =
            &plan->wide_checks[check];

        if (item->conversion_width == 2) {
            fprintf(out, "\tld hl,%lu\n",
                    item->conversion_input & 0xffffUL);
            mir_emit_runtime_call(out, "__fif");
        } else {
            mir_machine_emit_float_bits(
                out, item->conversion_input);
            mir_emit_runtime_call(out, "__flf");
        }
        fputs("\tpush de\n\tpush hl\n", out);
        mir_emit_final_call_constant(
            out, item->input, item->input_width);
        mir_machine_emit_symbol_call(out, item->value_function);
        mir_emit_final_call_cleanup(
            out, item->input_width / 2);
        fputs("\tpush de\n\tpush hl\n", out);
        fprintf(out, "\tld hl,S%d\n\tpush hl\n",
                item->name_string_id);
        mir_machine_emit_symbol_call(
            out, plan->wide_check_function);
        mir_emit_final_call_cleanup(out, 5);
    }

    mir_machine_emit_global_word(
        out, plan->failures_root, plan->failures_offset);
    fputs("\tpush hl\n", out);
    mir_machine_emit_global_word(
        out, plan->checks_root, plan->checks_offset);
    fputs("\tpush hl\n", out);
    fprintf(out, "\tld hl,S%d\n\tpush hl\n",
            plan->summary_string_id);
    mir_machine_emit_symbol_call(out, plan->print_function);
    mir_emit_final_call_cleanup(out, 3);

    mir_machine_emit_global_word(
        out, plan->failures_root, plan->failures_offset);
    fputs("\tld a,h\n\tor l\n", out);
    fprintf(out,
            "\tjr nz,L%d\n\tld hl,S%d\n\tpush hl\n"
            "\tjr L%d\nL%d:\n\tld hl,S%d\n\tpush hl\n"
            "L%d:\n\tld hl,S%d\n\tpush hl\n",
            failure_string, plan->success_string_id,
            result_ready, failure_string,
            plan->failure_string_id, result_ready,
            plan->result_string_id);
    mir_machine_emit_symbol_call(out, plan->print_function);
    mir_emit_final_call_cleanup(out, 2);

    mir_machine_emit_global_word(
        out, plan->failures_root, plan->failures_offset);
    fputs("\tld a,h\n\tor l\n", out);
    fprintf(out,
            "\tjr z,L%d\n\tld hl,1\n\tret\n"
            "L%d:\n\tld hl,0\n\tret\n",
            return_success, return_success);
}

static void mir_emit_buffered_declaration_address(
    FILE *out, const struct MirBufferedDeclarationSchedule *plan)
{
    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n",
            plan->cursor_offset, plan->cursor_offset + 1);
}

static void mir_emit_buffered_declaration_prefix_call(
    FILE *out, const struct MirBufferedDeclarationSchedule *plan,
    int string_id)
{
    fprintf(out, "\tld hl,S%d\n\tpush hl\n", string_id);
    mir_emit_buffered_declaration_address(out, plan);
    fputs("\tpush hl\n", out);
    mir_machine_emit_symbol_call(out, plan->prefix_function);
    fputs("\tpop de\n\tpop de\n", out);
}

static void mir_emit_buffered_declaration_call(
    FILE *out, const struct MirBufferedDeclarationSchedule *plan,
    int declaration_type)
{
    fprintf(out, "\tld hl,%u\n\tpush hl\n",
            (unsigned)declaration_type & 0xffffU);
    mir_emit_buffered_declaration_address(out, plan);
    fputs("\tpush hl\n", out);
    mir_machine_emit_symbol_call(
        out, plan->declaration_function);
    fputs("\tpop de\n\tpop de\n", out);
}

static void mir_emit_buffered_declaration_schedule(
    FILE *out, const struct MirBufferedDeclarationSchedule *plan)
{
    int done = new_label();
    int loop = new_label();
    int next = new_label();
    int second = new_label();
    int third = new_label();

    fputs("\tpush ix\n\tld ix,0\n\tadd ix,sp\n", out);
    fprintf(out,
            "\tld hl,-%d\n\tadd hl,sp\n\tld sp,hl\n",
            plan->frame_bytes);
    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    fputs("\tpush ix\n\tpop hl\n", out);
    mir_machine_emit_hl_offset(
        out, plan->buffer_offset, 0);
    fprintf(out,
            "\tld (ix%+d),l\n\tld (ix%+d),h\n",
            plan->cursor_offset, plan->cursor_offset + 1);
    fputs("\tld bc,0\n", out);
    fprintf(out, "L%d:\n", loop);
    mir_machine_emit_global_word(
        out, plan->count_root, plan->count_offset);
    fputs("\tex de,hl\n"
          "\tld h,b\n\tld l,c\n"
          "\tld a,h\n\txor 128\n\tld h,a\n"
          "\tld a,d\n\txor 128\n\tld d,a\n"
          "\tor a\n\tsbc hl,de\n", out);
    fprintf(out, "\tjp nc,L%d\n\tpush bc\n", done);

    fputs("\tld h,b\n\tld l,c\n", out);
    mir_emit_mul_hl_const(
        out, (unsigned long)plan->record_stride);
    fputs("\tpush hl\n", out);
    mir_machine_emit_global_word(
        out, plan->statements_root,
        plan->statements_offset);
    fputs("\tpop de\n\tadd hl,de\n", out);
    mir_machine_emit_hl_offset(
        out, plan->text_offset, 0);
    fputs("\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
          "\tpush de\n", out);
    mir_emit_buffered_declaration_address(out, plan);
    fputs("\tpush hl\n", out);
    mir_machine_emit_symbol_call(out, plan->copy_function);
    fputs("\tpop de\n\tpop de\n", out);

    mir_emit_buffered_declaration_address(out, plan);
    fputs("\tpush hl\n", out);
    mir_machine_emit_symbol_call(out, plan->trim_function);
    fputs("\tpop de\n", out);

    mir_emit_buffered_declaration_prefix_call(
        out, plan, plan->string_ids[0]);
    fputs("\tld a,h\n\tor l\n", out);
    fprintf(out, "\tjp z,L%d\n", second);
    mir_emit_buffered_declaration_call(
        out, plan, plan->declaration_types[0]);
    fprintf(out, "\tjp L%d\nL%d:\n", next, second);

    mir_emit_buffered_declaration_prefix_call(
        out, plan, plan->string_ids[1]);
    fputs("\tld a,h\n\tor l\n", out);
    fprintf(out, "\tjp z,L%d\n", third);
    mir_emit_buffered_declaration_call(
        out, plan, plan->declaration_types[1]);
    fprintf(out, "\tjp L%d\nL%d:\n", next, third);

    mir_emit_buffered_declaration_prefix_call(
        out, plan, plan->string_ids[2]);
    fputs("\tld a,h\n\tor l\n", out);
    fprintf(out, "\tjp z,L%d\n", next);
    mir_emit_buffered_declaration_call(
        out, plan, plan->declaration_types[2]);

    fprintf(out,
            "L%d:\n\tpop bc\n\tinc bc\n\tjp L%d\n"
            "L%d:\n\tld sp,ix\n\tpop ix\n\tret\n",
            next, loop, done);
}

static void mir_emit_symbol_find_schedule(
    FILE *out, const struct MirSymbolFindSchedule *plan)
{
    int capacity_error = new_label();
    int capacity_ready = new_label();
    int cursor_ready = new_label();
    int found = new_label();
    int loop = new_label();
    int memory_error = new_label();
    int memory_ready = new_label();
    int next = new_label();
    int no_match = new_label();

    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
    fprintf(out,
            "\tld hl,%d\n\tadd hl,sp\n"
            "\tld c,(hl)\n\tinc hl\n\tld b,(hl)\n"
            "\tpush bc\n",
            plan->name_stack_offset);
    mir_machine_emit_global_word(
        out, plan->symbols_root, plan->symbols_offset);
    fputs("\tpush hl\n", out);
    mir_machine_emit_global_word(
        out, plan->count_root, plan->count_offset);
    fputs("\tex de,hl\n\tpop hl\n\tld bc,0\n", out);

    fprintf(out,
            "L%d:\n"
            "\tpush hl\n\tpush de\n"
            "\tld h,b\n\tld l,c\n"
            "\tld a,h\n\txor 128\n\tld h,a\n"
            "\tld a,d\n\txor 128\n\tld d,a\n"
            "\tor a\n\tsbc hl,de\n"
            "\tpop de\n\tpop hl\n"
            "\tjp nc,L%d\n"
            "\tpush bc\n\tpush hl\n\tpush de\n"
            "\tld hl,6\n\tadd hl,sp\n"
            "\tld c,(hl)\n\tinc hl\n\tld b,(hl)\n"
            "\tpush bc\n"
            "\tld hl,4\n\tadd hl,sp\n"
            "\tld c,(hl)\n\tinc hl\n\tld b,(hl)\n"
            "\tpush bc\n",
            loop, no_match);
    mir_machine_emit_symbol_call(out, plan->compare_function);
    fputs("\tld a,h\n\tor l\n"
          "\tinc sp\n\tinc sp\n\tinc sp\n\tinc sp\n"
          "\tpop de\n\tpop hl\n\tpop bc\n", out);
    fprintf(out,
            "\tjp nz,L%d\n"
            "L%d:\n"
            "\tld a,l\n\tadd a,%d\n\tld l,a\n"
            "\tjp nc,L%d\n\tinc h\n"
            "L%d:\n\tinc bc\n\tjp L%d\n"
            "L%d:\n",
            found, next, plan->record_stride,
            cursor_ready, cursor_ready, loop, no_match);

    mir_machine_emit_global_word(
        out, plan->count_root, plan->count_offset);
    fprintf(out,
            "\tbit 7,h\n\tjp nz,L%d\n"
            "\tld a,h\n\tor a\n\tjp nz,L%d\n"
            "\tld a,l\n\tcp %d\n\tjp c,L%d\n"
            "L%d:\n\tld hl,S%d\n\tpush hl\n",
            capacity_ready, capacity_error,
            plan->symbol_limit, capacity_ready,
            capacity_error, plan->symbol_error_string_id);
    mir_machine_emit_symbol_call(out, plan->error_function);
    fprintf(out, "\tpop bc\nL%d:\n", capacity_ready);

    mir_machine_emit_global_word(
        out, plan->symbols_root, plan->symbols_offset);
    fputs("\tpush hl\n", out);
    mir_machine_emit_global_word(
        out, plan->count_root, plan->count_offset);
    mir_emit_mul_hl_const(
        out, (unsigned long)plan->record_stride);
    fputs("\tpop de\n\tadd hl,de\n\tpush hl\n", out);
    fprintf(out, "\tld hl,%d\n\tpush hl\n",
            plan->name_field_size - 1);
    fputs("\tld hl,4\n\tadd hl,sp\n"
          "\tld c,(hl)\n\tinc hl\n\tld b,(hl)\n"
          "\tpush bc\n"
          "\tld hl,4\n\tadd hl,sp\n"
          "\tld c,(hl)\n\tinc hl\n\tld b,(hl)\n"
          "\tpush bc\n", out);
    mir_machine_emit_symbol_call(out, plan->copy_function);
    fputs("\tpop bc\n\tpop bc\n\tpop bc\n\tpop hl\n"
          "\tpush hl\n", out);
    mir_machine_emit_global_word(
        out, plan->memory_top_root, plan->memory_top_offset);
    fputs("\tld c,l\n\tld b,h\n\tinc hl\n", out);
    mir_machine_emit_global_word_store(
        out, plan->memory_top_root, plan->memory_top_offset);
    fputs("\tpop hl\n", out);
    mir_machine_emit_hl_offset(
        out, plan->scalar_field_offset, 1);
    fputs("\tld (hl),c\n\tinc hl\n\tld (hl),b\n"
          "\tinc hl\n\tld (hl),255\n"
          "\tinc hl\n\tld (hl),255\n"
          "\tinc hl\n\txor a\n\tld (hl),a\n"
          "\tinc hl\n\tld (hl),a\n", out);

    mir_machine_emit_global_word(
        out, plan->memory_top_root, plan->memory_top_offset);
    fprintf(out,
            "\tbit 7,h\n\tjp nz,L%d\n"
            "\tld de,%d\n\tor a\n\tsbc hl,de\n"
            "\tjp nc,L%d\n\tjp L%d\n"
            "L%d:\n\tld hl,S%d\n\tpush hl\n",
            memory_ready, plan->memory_limit,
            memory_error, memory_ready,
            memory_error, plan->memory_error_string_id);
    mir_machine_emit_symbol_call(out, plan->error_function);
    fprintf(out, "\tpop bc\nL%d:\n", memory_ready);

    mir_machine_emit_global_word(
        out, plan->count_root, plan->count_offset);
    fputs("\tpush hl\n\tinc hl\n", out);
    mir_machine_emit_global_word_store(
        out, plan->count_root, plan->count_offset);
    fputs("\tpop hl\n\tpop bc\n\tret\n", out);

    fprintf(out,
            "L%d:\n\tld h,b\n\tld l,c\n\tpop de\n\tret\n",
            found);
}

int mir_try_emit_speculation_safe_machine_cfg(FILE *out)
{
    struct MirWideNarrowDivision division;
    struct MirIndexedMemberWrite write;

    if (mir_match_wide_narrow_division(&division)) {
        fprintf(out, "%s\n", MIR_EXACT_KERNEL_MARKER);
        fprintf(out, "%s\n", MIR_SPECULATION_SAFE_MARKER);
        mir_emit_wide_narrow_division(out, &division);
        return 1;
    }

    if (!mir_match_indexed_member_write(&write))
        return 0;
    fprintf(out, "%s\n", MIR_EXACT_KERNEL_MARKER);
    fprintf(out, "%s\n", MIR_SPECULATION_SAFE_MARKER);
    mir_emit_indexed_member_write(out, &write);
    return 1;
}

